window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch04"]={"id": "ch04", "title": "第四章 分子生物学方法（一）", "sub": "朱玉贤《现代分子生物学》第5版 · 教师课件逐页详解", "sub2": "分子分离 · 杂交 · PCR · 克隆 · 表达 · 基因操作 · 组学", "modules": [{"i": 0, "name": "模块一：方法总览与核酸凝胶电泳", "slides": [{"i": 0, "sec": "方法总览与核酸凝胶电泳", "title": "分子生物学技术总览 (p2)", "notes": "本页概括了分子生物学常用技术体系：分子分离与检测用于对特定DNA/RNA和蛋白质进行定性或定量分析；PCR及反转录、实时定量PCR用于检测mRNA水平，实现基因表达产物的定量；基因克隆与克隆基因表达用于获得和表达目标基因；基因操作用于研究基因功能；基因组/转录组测序则从组学尺度开展研究。这些技术相互支撑，构成现代分子生物学研究的方法学基础。", "page": 2, "level": "理解", "img": "assets/img/ch04/p002.jpg", "anim": null, "fig": null, "points": ["分子分离与检测用于对DNA/RNA和蛋白质定性或定量分析", "PCR、反转录及实时定量PCR用于检测mRNA水平、定量基因表达产物", "基因克隆与克隆基因表达用于获得和表达目标基因，基因操作用于研究基因功能", "基因组/转录组测序从组学尺度开展研究", "各技术相互支撑，构成现代分子生物学方法学基础"], "check": {"q": "根据本页对分子生物学技术体系的概括，下列哪项技术主要用于检测mRNA水平并实现基因表达产物的定量？", "o": ["A. 基因克隆与克隆基因表达", "B. PCR及反转录、实时定量PCR", "C. 基因组/转录组测序", "D. 离子交换层析"], "a": "B", "e": "本页指出PCR及反转录、实时定量PCR用于检测mRNA水平，实现基因表达产物的定量。"}, "cards": [{"front": "分子生物学常用技术体系包括哪些方面？", "back": "分子分离与检测、PCR及反转录/实时定量PCR、基因克隆与克隆基因表达、基因操作、基因组/转录组测序。", "mnemonic": "分离检测、PCR定量、克隆表达、基因操作、组学测序", "useImg": false}]}, {"i": 1, "sec": "方法总览与核酸凝胶电泳", "title": "分子分离技术分类 (p3)", "notes": "分子分离技术主要包括核酸凝胶电泳、蛋白质单向/双向凝胶电泳、离子交换层析、凝胶过滤层析和亲和层析。电泳主要按分子大小、电荷和形状等差异分离核酸或蛋白质；层析则依据电荷、分子大小或特异性相互作用进行分离纯化。这些方法既可用于分析，也可用于纯化特定的蛋白质或核酸，是下游鉴定与功能研究的前提。", "page": 3, "level": "掌握", "img": "assets/img/ch04/p003.jpg", "anim": null, "fig": null, "points": ["分子分离技术包括核酸凝胶电泳、蛋白质单向/双向凝胶电泳、离子交换层析、凝胶过滤层析和亲和层析", "电泳主要按分子大小、电荷和形状差异分离核酸或蛋白质", "层析依据电荷、分子大小或特异性相互作用进行分离纯化", "这些方法既可用于分析，也可用于纯化特定蛋白质或核酸，是下游鉴定与功能研究的前提"], "check": {"q": "关于分子分离技术的分类与依据，下列叙述正确的是？", "o": ["A. 电泳仅按分子大小分离，层析仅按电荷分离", "B. 电泳主要按分子大小、电荷和形状等差异分离，层析依据电荷、分子大小或特异性相互作用分离", "C. 层析只能用于分析，不能用于纯化", "D. 凝胶电泳只能分离核酸，不能分离蛋白质"], "a": "B", "e": "本页明确电泳按大小、电荷、形状等差异分离，层析依据电荷、分子大小或特异性相互作用分离纯化。"}, "cards": [{"front": "分子分离技术主要包括哪些方法？", "back": "核酸凝胶电泳、蛋白质单向/双向凝胶电泳、离子交换层析、凝胶过滤层析、亲和层析。", "mnemonic": "电泳看大小电荷形状，层析看电荷大小特异结合", "useImg": false}]}, {"i": 2, "sec": "方法总览与核酸凝胶电泳", "title": "凝胶电泳的基本原理 (p4)", "notes": "凝胶电泳是在电场作用下使DNA分子通过凝胶基质，按分子大小（并受分子量、形状、电荷、拓扑性质等影响）进行分离。电泳一词源于希腊语，意为“携带穿过”。分离后的DNA条带需用荧光染料染色显示，如溴化乙锭（EB）。该方法是核酸分析最基础、最常用的手段，可用于判断片段大小、数量及纯度。", "page": 4, "level": "掌握", "img": "assets/img/ch04/p004.jpg", "anim": null, "fig": null, "points": ["凝胶电泳是在电场作用下使DNA通过凝胶基质，按分子大小分离", "迁移还受分子量、形状、电荷、拓扑性质等影响", "电泳（electrophoresis）源于希腊语，意为“携带穿过”", "分离后DNA条带需用荧光染料（如溴化乙锭EB）染色显示", "该方法是核酸分析最基础、最常用的手段，可判断片段大小、数量及纯度"], "check": {"q": "关于凝胶电泳基本原理，下列叙述正确的是？", "o": ["A. DNA在电场中向负极迁移", "B. 分离后的DNA条带无需染色即可肉眼观察", "C. 凝胶电泳是在电场作用下使DNA通过凝胶基质，按分子大小等因素分离，条带需用荧光染料如EB染色显示", "D. 电泳一词源于拉丁语，意为“切割”"], "a": "C", "e": "本页说明电泳是在电场下使DNA通过凝胶基质按大小等分离，条带需荧光染料（如EB）染色显示。"}, "cards": [{"front": "凝胶电泳分离DNA的基本原理是什么？", "back": "电场作用下DNA通过凝胶基质，按分子大小（并受分子量、形状、电荷、拓扑性质影响）分离。", "mnemonic": "电场推着走，凝胶网筛大小", "useImg": false}]}, {"i": 3, "sec": "方法总览与核酸凝胶电泳", "title": "DNA拓扑构象的凝胶电泳分析 (p5)", "notes": "本页示意图展示超螺旋DNA、开环/切口环状DNA与线性DNA在凝胶电泳中的迁移差异。超螺旋DNA结构最紧凑，在凝胶网络中迁移最快；开环或切口环状DNA较松散，迁移最慢；线性DNA居中。因此电泳不仅可分离不同大小的DNA，还可用于检测质粒DNA的超螺旋程度和拓扑构象变化，是质粒质量分析的常用方法。", "page": 5, "level": "理解", "img": "assets/img/ch04/p005.jpg", "anim": null, "fig": "图中同一泳道方向展示三种构象DNA的条带位置：最靠前（迁移最快）的是超螺旋DNA，居中为线性DNA，最靠后（迁移最慢）为开环/切口环状DNA。据此可判断质粒样品的构象组成与超螺旋比例。", "points": ["超螺旋DNA结构最紧凑，在凝胶网络中迁移最快", "开环/切口环状DNA较松散，迁移最慢", "线性DNA迁移速度居中", "电泳可检测质粒DNA的超螺旋程度和拓扑构象变化，是质粒质量分析的常用方法"], "check": {"q": "在凝胶电泳中，超螺旋DNA、开环/切口环状DNA与线性DNA的迁移速度关系通常是？", "o": ["A. 超螺旋最快，线性居中，开环最慢", "B. 开环最快，超螺旋居中，线性最慢", "C. 线性最快，超螺旋居中，开环最慢", "D. 三者迁移速度相同"], "a": "A", "e": "本页指出超螺旋结构最紧凑迁移最快，开环/切口环状最松散迁移最慢，线性居中。"}, "cards": [{"front": "电泳后DNA条带如何显示？常用染料是什么？", "back": "用荧光染料染色显示，经典染料为溴化乙锭（EB）。", "mnemonic": "EB染DNA，紫外下发光", "useImg": false}]}, {"i": 4, "sec": "方法总览与核酸凝胶电泳", "title": "DNA/RNA片段的电泳分离 (p6)", "notes": "电泳可分离DNA和RNA片段。DNA分子因磷酸骨架带负电荷，在电场中向正极迁移。凝胶基质形成多孔网络，较长的分子在迁移中更容易被网络“捕获”而移动较慢，较短的分子则移动较快，从而实现按大小分离。该原理是核酸凝胶电泳的核心，也是后续片段回收、Southern blot和测序样品分析的基础。", "page": 6, "level": "掌握", "img": "assets/img/ch04/p006.jpg", "anim": null, "fig": null, "points": ["DNA因磷酸骨架带负电荷，在电场中向正极迁移", "凝胶基质形成多孔网络，较长分子易被网络“捕获”而移动较慢", "较短分子移动较快，从而实现按大小分离", "该原理是核酸凝胶电泳的核心，也是片段回收、Southern blot和测序样品分析的基础"], "check": {"q": "DNA片段在凝胶电泳中按大小分离的主要原因是？", "o": ["A. DNA带正电荷向负极迁移，长片段移动更快", "B. DNA因磷酸骨架带负电荷向正极迁移，凝胶多孔网络使较长分子更易被“捕获”而移动较慢", "C. 凝胶基质带正电荷吸引DNA", "D. 短片段因电荷更多而移动更慢"], "a": "B", "e": "本页说明DNA磷酸骨架带负电向正极迁移，凝胶网络使长片段更易被捕获而移动较慢，短片段较快。"}, "cards": [{"front": "超螺旋、开环/切口环状与线性DNA在凝胶电泳中迁移顺序如何？", "back": "超螺旋最快，线性居中，开环/切口环状最慢。", "mnemonic": "越紧凑跑越快：超螺旋>线性>开环", "useImg": false}]}, {"i": 5, "sec": "方法总览与核酸凝胶电泳", "title": "凝胶基质：琼脂糖与聚丙烯酰胺 (p7)", "notes": "凝胶基质是类似果冻的多孔材料，可支撑并允许大分子通过。琼脂糖分辨率较低，但分离范围宽，可分离几百bp至数十kb的DNA；聚丙烯酰胺分辨率高，可区分仅相差一个碱基的DNA片段，但分离范围窄。实际实验中应根据目标片段大小和所需分辨率选择合适的凝胶种类与浓度，这是核酸电泳实验设计的关键。", "page": 7, "level": "掌握", "img": "assets/img/ch04/p007.jpg", "anim": null, "fig": null, "points": ["凝胶基质是类似果冻的多孔材料，可支撑并允许大分子通过", "琼脂糖分辨率较低但分离范围宽，可分离几百bp至数十kb的DNA", "聚丙烯酰胺分辨率高，可区分仅相差一个碱基的DNA片段，但分离范围窄", "应根据目标片段大小和所需分辨率选择合适的凝胶种类与浓度，这是实验设计的关键"], "check": {"q": "关于琼脂糖与聚丙烯酰胺凝胶的比较，下列叙述正确的是？", "o": ["A. 琼脂糖分辨率高，可区分相差一个碱基的片段", "B. 聚丙烯酰胺分离范围宽，可分离数十kb的DNA", "C. 琼脂糖分辨率较低但分离范围宽，聚丙烯酰胺分辨率高但分离范围窄", "D. 两者分辨率和分离范围完全相同"], "a": "C", "e": "本页指出琼脂糖分辨率较低但分离范围宽（几百bp至数十kb），聚丙烯酰胺分辨率高可区分单碱基差异但分离范围窄。"}, "cards": [{"front": "DNA在电场中向哪一极迁移？为什么？", "back": "向正极迁移，因为磷酸骨架带负电荷。", "mnemonic": "DNA带负电，正极招手", "useImg": false}]}, {"i": 6, "sec": "方法总览与核酸凝胶电泳", "title": "琼脂糖凝胶的特点与应用 (p8)", "notes": "琼脂糖凝胶分辨率低于聚丙烯酰胺，但可分离长达数十kb的DNA分子，适合常规DNA片段分析。电泳后可用荧光染料染色使DNA可视化，常用染料包括溴化乙锭（EB）、GelRed、RedSafe、GelSafe等。EB虽经典但具诱变毒性，使用时需注意安全；新型染料在灵敏度和安全性方面有所改进。", "page": 8, "level": "掌握", "img": "assets/img/ch04/p008.jpg", "anim": null, "fig": null, "points": ["琼脂糖凝胶分辨率低于聚丙烯酰胺，但可分离长达数十kb的DNA，适合常规DNA片段分析", "电泳后可用荧光染料染色使DNA可视化", "常用染料包括EB、GelRed、RedSafe、GelSafe等", "EB虽经典但具诱变毒性，使用时需注意安全；新型染料在灵敏度和安全性方面有所改进"], "check": {"q": "关于琼脂糖凝胶的特点与应用，下列叙述正确的是？", "o": ["A. 琼脂糖凝胶可分离长达数十kb的DNA，电泳后可用EB、GelRed等荧光染料染色可视化", "B. 琼脂糖凝胶分辨率高于聚丙烯酰胺，适合单碱基差异分析", "C. EB安全无毒，是首选染料", "D. 琼脂糖凝胶电泳后DNA无需染色即可观察"], "a": "A", "e": "本页指出琼脂糖可分离长达数十kb的DNA，电泳后可用EB、GelRed、RedSafe等荧光染料染色可视化；EB具诱变毒性。"}, "cards": [{"front": "凝胶电泳中DNA片段大小与迁移速度的关系是什么？", "back": "较长分子易被凝胶网络捕获而移动慢，较短分子移动快，从而实现按大小分离。", "mnemonic": "大块卡网慢，小块钻网快", "useImg": false}]}, {"i": 7, "sec": "方法总览与核酸凝胶电泳", "title": "琼脂糖凝胶基质示意图 (p9)", "notes": "本页为琼脂糖凝胶基质示意图，结合前页内容可知：琼脂糖形成较大孔径的多孔网络，适合分离较大范围的DNA片段。凝胶浓度越高，孔径越小，适合分离较小片段；浓度越低，孔径越大，适合分离较大片段。琼脂糖凝胶制备简便、分离范围宽，是常规DNA电泳最常用的基质。", "page": 9, "level": "理解", "img": "assets/img/ch04/p009.jpg", "anim": null, "fig": "示意图以网状结构表示琼脂糖凝胶的孔径大小，可将其理解为分子筛：孔径越大越适合大片段通过，孔径越小则对小片段分辨更好。结合浓度与孔径的反比关系理解凝胶选择。", "points": ["琼脂糖形成较大孔径的多孔网络，适合分离较大范围的DNA片段", "凝胶浓度越高，孔径越小，适合分离较小片段", "浓度越低，孔径越大，适合分离较大片段", "琼脂糖凝胶制备简便、分离范围宽，是常规DNA电泳最常用的基质"], "check": {"q": "关于琼脂糖凝胶作为电泳基质，下列说法正确的是？", "o": ["A. 琼脂糖凝胶孔径很小，只能分离小于10 bp的片段", "B. 琼脂糖凝胶浓度越高，孔径越小，适合分离较小片段", "C. 琼脂糖凝胶浓度越低，孔径越小，适合分离较大片段", "D. 琼脂糖凝胶分辨率极高，可分辨相差一个碱基的片段"], "a": "B", "e": "琼脂糖形成较大孔径网络，浓度越高孔径越小、适合较小片段；浓度越低孔径越大、适合较大片段。高单碱基分辨是聚丙烯酰胺凝胶的特点。"}, "cards": [{"front": "琼脂糖凝胶与聚丙烯酰胺凝胶在分辨率和分离范围上有何区别？", "back": "琼脂糖分辨率较低但分离范围宽（几百bp至数十kb）；聚丙烯酰胺分辨率高（可分辨相差一个碱基）但分离范围窄（约1至几百bp）。", "mnemonic": "琼脂糖宽而粗，聚丙烯酰胺窄而精", "useImg": false}]}, {"i": 8, "sec": "方法总览与核酸凝胶电泳", "title": "聚丙烯酰胺凝胶的高分辨率 (p10)", "notes": "聚丙烯酰胺凝胶分辨率高，可分辨仅相差一个碱基对的DNA片段，但只能分离较窄范围（约1至几百bp）的DNA。其孔径可通过丙烯酰胺与交联剂比例精确调节，因而广泛用于需要单碱基分辨的场合，如DNA测序、PCR产物精细分析和蛋白质电泳。选择凝胶时应权衡分辨率与分离范围。", "page": 10, "level": "掌握", "img": "assets/img/ch04/p010.jpg", "anim": null, "fig": null, "points": ["聚丙烯酰胺凝胶分辨率高，可分辨仅相差一个碱基对的DNA片段", "只能分离较窄范围（约1至几百bp）的DNA", "孔径可通过丙烯酰胺与交联剂比例精确调节", "广泛用于DNA测序、PCR产物精细分析和蛋白质电泳", "选择凝胶时应权衡分辨率与分离范围"], "check": {"q": "关于聚丙烯酰胺凝胶电泳，下列描述正确的是？", "o": ["A. 分辨率低，只能粗略区分大片段DNA", "B. 可分辨仅相差一个碱基对的DNA片段，但分离范围较窄", "C. 孔径固定不可调节，因此重复性差", "D. 只用于分离大于10 Mb的完整染色体"], "a": "B", "e": "聚丙烯酰胺凝胶分辨率高，可分辨相差1个碱基的片段，但分离范围窄（约1至几百bp），孔径可通过单体与交联剂比例调节。"}, "cards": [{"front": "琼脂糖凝胶浓度与分离片段大小的关系是什么？", "back": "浓度越高孔径越小，适合分离较小片段；浓度越低孔径越大，适合分离较大片段。", "mnemonic": "浓胶筛小片，稀胶过大片", "useImg": false}]}, {"i": 9, "sec": "方法总览与核酸凝胶电泳", "title": "聚丙烯酰胺凝胶基质示意图 (p11)", "notes": "本页为聚丙烯酰胺凝胶基质示意图，结合前页内容可知：聚丙烯酰胺形成孔径较小且可调控的三维网络，因而具有高分辨率，能区分长度相差极小的DNA片段。其分离范围窄，适合小片段核酸的高分辨分析，也是蛋白质单向和双向电泳的常用基质。凝胶孔径由单体和交联剂比例决定。", "page": 11, "level": "理解", "img": "assets/img/ch04/p011.jpg", "anim": null, "fig": "示意图以细密的三维网状结构表示聚丙烯酰胺凝胶，孔径明显小于琼脂糖。可据此理解其高分辨率与窄分离范围的来源，以及孔径由单体与交联剂比例调控。", "points": ["聚丙烯酰胺形成孔径较小且可调控的三维网络，因而具有高分辨率", "能区分长度相差极小的DNA片段", "分离范围窄，适合小片段核酸的高分辨分析", "也是蛋白质单向和双向电泳的常用基质", "凝胶孔径由单体和交联剂比例决定"], "check": {"q": "聚丙烯酰胺凝胶具有高分辨率的主要原因是？", "o": ["A. 其孔径较大且均匀，适合分离长链DNA", "B. 其形成孔径较小且可通过单体与交联剂比例调控的三维网络", "C. 它只能在变性条件下使用", "D. 它依靠电场方向周期性切换来分离分子"], "a": "B", "e": "聚丙烯酰胺形成孔径小且可调控的网络，因而能区分长度相差极小的片段；电场切换是PFGE的原理。"}, "cards": [{"front": "聚丙烯酰胺凝胶的孔径由什么决定？主要用于哪些场合？", "back": "孔径由丙烯酰胺与交联剂比例决定；用于DNA测序、PCR产物精细分析和蛋白质电泳等需单碱基分辨的场合。", "mnemonic": "单体交联调孔径，测序蛋白都靠它", "useImg": false}]}, {"i": 10, "sec": "方法总览与核酸凝胶电泳", "title": "脉冲场凝胶电泳（PFGE） (p12)", "notes": "普通凝胶电泳中，大于10kb的DNA分子迁移速度接近，难以分离。脉冲场凝胶电泳通过周期性改变电场方向，使DNA分子在凝胶中不断调整取向：较小的分子转向快、迁移快，较大的分子转向困难、迁移慢，从而按分子量、形状和拓扑特性分离。PFGE可有效分离10kb至10Mb的大分子DNA，是基因组图谱和染色体分析的重要方法。", "page": 12, "level": "掌握", "img": "assets/img/ch04/p012.jpg", "anim": null, "fig": null, "points": ["普通凝胶电泳中大于10kb的DNA分子迁移速度接近，难以分离", "PFGE通过周期性改变电场方向，使DNA分子不断调整取向", "较小分子转向快、迁移快；较大分子转向困难、迁移慢", "按分子量、形状和拓扑特性分离，可有效分离10kb至10Mb的大分子DNA", "是基因组图谱和染色体分析的重要方法"], "check": {"q": "脉冲场凝胶电泳（PFGE）能够分离大分子DNA的主要原理是？", "o": ["A. 通过提高电压使所有DNA分子迁移速度一致", "B. 通过周期性改变电场方向，使不同大小DNA分子重定向速度不同而分离", "C. 通过降低凝胶浓度使大分子DNA孔径变大", "D. 通过加入溴化乙锭使DNA分子带不同电荷"], "a": "B", "e": "PFGE周期性改变电场方向，小分子转向快、迁移快，大分子转向困难、迁移慢，从而分离10 kb至10 Mb的大分子DNA。"}, "cards": [{"front": "普通凝胶电泳为何难以分离大于10kb的DNA？", "back": "大于10kb的DNA分子迁移速度接近，难以有效分辨。", "mnemonic": "太大都堵在网里，快慢差不多", "useImg": false}]}, {"i": 11, "sec": "方法总览与核酸凝胶电泳", "title": "PFGE分离完整染色体 (p13)", "notes": "脉冲场凝胶电泳采用相互正交、脉冲式施加的电场，可分离极长的DNA分子，例如完整的细菌或真菌染色体。由于大分子DNA在普通电泳中无法有效分辨，PFGE通过交替改变电场方向使长链DNA反复重定向，从而实现染色体级别的分离。该技术常用于微生物基因组分型、染色体数目与大小分析。", "page": 13, "level": "理解", "img": "assets/img/ch04/p013.jpg", "anim": null, "fig": null, "points": ["PFGE采用相互正交、脉冲式施加的电场", "可分离极长的DNA分子，如完整的细菌或真菌染色体", "通过交替改变电场方向使长链DNA反复重定向，实现染色体级别分离", "常用于微生物基因组分型、染色体数目与大小分析"], "check": {"q": "关于PFGE分离完整染色体，下列说法正确的是？", "o": ["A. 普通凝胶电泳即可有效分离完整细菌染色体，无需PFGE", "B. PFGE采用相互正交、脉冲式施加的电场，使长链DNA反复重定向从而实现染色体级分离", "C. PFGE只能分离小于10 kb的DNA片段", "D. PFGE分离依据仅为DNA的碱基组成，与分子大小无关"], "a": "B", "e": "PFGE用正交脉冲电场使长链DNA反复重定向，可分离完整细菌或真菌染色体，常用于微生物基因组分型及染色体分析。"}, "cards": [{"front": "脉冲场凝胶电泳（PFGE）的原理是什么？", "back": "周期性改变电场方向，使DNA不断调整取向：小分子转向快迁移快，大分子转向困难迁移慢，从而按分子量、形状和拓扑特性分离。", "mnemonic": "电场换方向，小DNA灵活跑得快，大DNA笨重转得慢", "useImg": false}]}, {"i": 12, "sec": "方法总览与核酸凝胶电泳", "title": "酵母染色体的脉冲场电泳实例 (p14)", "notes": "本页展示酵母染色体的脉冲场凝胶电泳结果：相同样品在10个平行泳道中电泳，经溴化乙锭染色后可见16条条带，代表大小约2.2 Mb（顶部）至0.2 Mb（底部）的染色体。该实例直观说明PFGE可分辨Mb级完整染色体，是核型分析、基因组大小估计和染色体多态性研究的有力工具。", "page": 14, "level": "理解", "img": "assets/img/ch04/p014.jpg", "anim": null, "fig": "图中10个平行泳道为相同样品的重复，条带位置一致说明分离结果可靠。从下往上条带对应分子量由小到大（0.2Mb至2.2Mb），共16条，可据此读出酵母各染色体的相对大小。", "points": ["相同样品在10个平行泳道中电泳，经溴化乙锭染色后可见16条条带", "条带代表大小约2.2 Mb（顶部）至0.2 Mb（底部）的酵母染色体", "直观说明PFGE可分辨Mb级完整染色体", "是核型分析、基因组大小估计和染色体多态性研究的有力工具"], "check": {"q": "关于酵母染色体的脉冲场凝胶电泳实例，下列描述正确的是？", "o": ["A. 10个平行泳道显示16条条带，代表0.2 Mb至2.2 Mb的染色体", "B. 凝胶中只出现1条条带，说明酵母只有一条染色体", "C. 条带代表0.2 kb至2.2 kb的短DNA片段", "D. 该结果说明普通电泳也能分辨Mb级染色体"], "a": "A", "e": "该实例中10个平行泳道经溴化乙锭染色可见16条条带，代表2.2 Mb（顶部）至0.2 Mb（底部）的酵母染色体，说明PFGE可分辨Mb级完整染色体。"}, "cards": [{"front": "PFGE可分离多大范围的DNA？有何应用？", "back": "可分离10kb至10Mb的大分子DNA；用于基因组图谱、染色体分析、微生物基因组分型、核型分析等。", "mnemonic": "PFGE管Mb级，染色体核型都能看", "useImg": false}]}, {"i": 13, "sec": "方法总览与核酸凝胶电泳", "title": "脉冲场电泳分离大分子DNA示意图 (p15)", "notes": "本页为示意图，结合前后页可知其表达脉冲场凝胶电泳分离大分子DNA的原理：电场方向周期性切换，使长链DNA分子在凝胶中反复改变迁移方向，小分子转向快而迁移快，大分子转向慢而迁移慢，从而实现Mb级DNA的分离。该图辅助说明PFGE为何能克服普通电泳对大分子DNA分辨率不足的问题。", "page": 15, "level": "理解", "img": "assets/img/ch04/p015.jpg", "anim": null, "fig": "示意图展示电场方向交替切换时，长链DNA分子在凝胶中反复改变取向的过程。观察不同长度分子重定向的难易差异，即可理解小分子迁移快、大分子迁移慢的分离机制。", "points": ["电场方向周期性切换，使长链DNA在凝胶中反复改变迁移方向", "小分子转向快而迁移快，大分子转向慢而迁移慢", "从而实现Mb级DNA的分离", "该图辅助说明PFGE为何能克服普通电泳对大分子DNA分辨率不足的问题"], "check": {"q": "脉冲场电泳分离大分子DNA示意图所表达的核心原理是？", "o": ["A. 电场方向恒定，DNA按电荷多少分离", "B. 电场方向周期性切换，小分子转向快迁移快、大分子转向慢迁移慢", "C. 凝胶孔径极大，使所有大分子自由通过", "D. DNA分子在电泳前被切成小片段后再分离"], "a": "B", "e": "示意图表明PFGE通过周期性切换电场方向，使长链DNA反复改变迁移方向，小分子转向快而迁移快、大分子转向慢而迁移慢，从而分离Mb级DNA。"}, "cards": [{"front": "酵母染色体PFGE实例说明了什么？", "back": "10个平行泳道经EB染色可见16条条带，代表0.2Mb至2.2Mb的染色体，说明PFGE可分辨Mb级完整染色体。", "mnemonic": "16条带，0.2到2.2Mb，PFGE显神通", "useImg": false}]}, {"i": 14, "sec": "方法总览与核酸凝胶电泳", "title": "RNA的电泳 (p16)", "notes": "RNA同样带负电荷，但单链RNA易形成复杂的二级、三级结构，会影响其电泳迁移率，使其迁移行为不完全取决于分子量。为消除这一变量，可用乙二醛等试剂处理RNA，使高级结构解体，处理后RNA的迁移率约与分子量成正比。因此RNA电泳前常进行变性处理，以便准确判断RNA大小和完整性。", "page": 16, "level": "掌握", "img": "assets/img/ch04/p016.jpg", "anim": null, "fig": null, "points": ["RNA同样带负电荷，但单链RNA易形成复杂二级、三级结构", "高级结构会影响电泳迁移率，使其迁移行为不完全取决于分子量", "可用乙二醛等试剂处理RNA使高级结构解体", "处理后RNA迁移率约与分子量成正比", "RNA电泳前常进行变性处理，以准确判断RNA大小和完整性"], "check": {"q": "关于RNA凝胶电泳，下列说法正确的是？", "o": ["A. RNA不带电荷，因此不能进行电泳", "B. 单链RNA的迁移率完全取决于其分子量", "C. 用乙二醛等试剂处理RNA可使其高级结构解体，迁移率约与分子量成正比", "D. RNA电泳前无需任何处理即可准确判断其大小"], "a": "C", "e": "单链RNA易形成二级、三级结构，影响迁移率；用乙二醛等变性处理使高级结构解体后，迁移率约与分子量成正比，故C正确。"}, "cards": [{"front": "RNA电泳前为何常需变性处理？", "back": "单链RNA易形成二级、三级结构影响迁移率；用乙二醛等处理使高级结构解体后，迁移率约与分子量成正比。", "mnemonic": "RNA爱折叠，变性后才能按大小排队", "useImg": false}]}, {"i": 15, "sec": "方法总览与核酸凝胶电泳", "title": "凝胶电泳的操作步骤 (p17)", "notes": "凝胶电泳的基本步骤包括：配制琼脂糖凝胶（凝胶浓度以琼脂糖质量分数gel%表示）、将凝胶放入电泳槽、加载DNA/RNA样品、通电运行电泳、最后染色观察结果。每一步都会影响分离效果，如凝胶浓度决定孔径和分离范围，上样量和电压影响条带清晰度。规范操作是获得可靠电泳结果的前提。", "page": 17, "level": "掌握", "img": "assets/img/ch04/p017.jpg", "anim": null, "fig": null, "points": ["基本步骤：配制琼脂糖凝胶（浓度以琼脂糖质量分数gel%表示）", "将凝胶放入电泳槽、加载DNA/RNA样品", "通电运行电泳，最后染色观察结果", "凝胶浓度决定孔径和分离范围，上样量和电压影响条带清晰度", "规范操作是获得可靠电泳结果的前提"], "check": {"q": "关于凝胶电泳的基本操作步骤，下列叙述正确的是？", "o": ["A. 凝胶浓度以琼脂糖质量分数gel%表示，决定孔径和分离范围", "B. 电泳时先通电运行，再加载DNA/RNA样品", "C. 染色观察应在加载样品之前完成", "D. 上样量和电压不影响条带清晰度"], "a": "A", "e": "凝胶浓度以琼脂糖质量分数gel%表示，决定孔径和分离范围；上样应在通电前，染色在电泳后进行，上样量和电压会影响条带清晰度，故A正确。"}, "cards": [{"front": "凝胶电泳的基本操作步骤有哪些？", "back": "配制琼脂糖凝胶（gel%表示浓度）、放入电泳槽、加载DNA/RNA样品、通电电泳、染色观察结果。", "mnemonic": "配胶—入槽—上样—通电—染色", "useImg": false}]}], "mcq": [{"id": "ch04_mcq_1", "mod": "模块一：方法总览与核酸凝胶电泳", "modI": 0, "q": "关于琼脂糖凝胶与聚丙烯酰胺凝胶的比较，下列叙述正确的是：", "o": ["A. 琼脂糖分辨率高，可区分相差一个碱基的DNA片段", "B. 聚丙烯酰胺分离范围宽，可分离数十kb的DNA", "C. 琼脂糖分辨率较低，但可分离几百bp至数十kb的DNA", "D. 两者分辨率相同，仅孔径不同"], "a": "C", "e": "琼脂糖分辨率较低但分离范围宽，可分离几百bp至数十kb的DNA；聚丙烯酰胺分辨率高但分离范围窄，仅适合1至几百bp。", "kp": "ch04_s0_5"}, {"id": "ch04_mcq_2", "mod": "模块一：方法总览与核酸凝胶电泳", "modI": 0, "q": "脉冲场凝胶电泳（PFGE）能够有效分离大分子DNA的主要原因是：", "o": ["A. 使用更高浓度的琼脂糖凝胶", "B. 电场方向以脉冲形式周期性改变，使DNA分子反复重定向", "C. 加入溴化乙锭使DNA带正电", "D. 将DNA先切成小片段再电泳"], "a": "B", "e": "PFGE通过周期性改变电场方向，小分子转向快、迁移快，大分子转向困难、迁移慢，从而分离10kb至10Mb的大分子DNA。", "kp": "ch04_s0_10"}, {"id": "ch04_mcq_3", "mod": "模块一：方法总览与核酸凝胶电泳", "modI": 0, "q": "DNA在凝胶电泳中向正极迁移的直接原因是：", "o": ["A. DNA分子带有正电荷", "B. DNA分子中的磷酸骨架带负电荷", "C. 凝胶基质带正电荷", "D. 荧光染料使DNA带负电"], "a": "B", "e": "DNA的磷酸骨架带负电荷，在电场中向正极迁移；凝胶网络对较长分子的阻滞更强，从而实现按大小分离。", "kp": "ch04_s0_3"}, {"id": "ch04_mcq_4", "mod": "模块一：方法总览与核酸凝胶电泳", "modI": 0, "q": "RNA电泳前常用乙二醛等试剂处理，其目的是：", "o": ["A. 使RNA带上正电荷", "B. 将RNA降解为小片段", "C. 破坏RNA的二级和三级结构，使迁移率与分子量成正比", "D. 使RNA与DNA分离"], "a": "C", "e": "单链RNA易形成高级结构而影响迁移率，乙二醛等变性试剂可消除高级结构，使RNA迁移率约与分子量成正比。", "kp": "ch04_s0_14"}, {"id": "ch04_mcq_5", "mod": "模块一：方法总览与核酸凝胶电泳", "modI": 0, "q": "在凝胶电泳中，超螺旋DNA、线性DNA和开环/切口环状DNA的迁移速度由快到慢一般为：", "o": ["A. 开环环状DNA > 线性DNA > 超螺旋DNA", "B. 线性DNA > 超螺旋DNA > 开环环状DNA", "C. 超螺旋DNA > 线性DNA > 开环环状DNA", "D. 三者迁移速度相同"], "a": "C", "e": "超螺旋DNA结构最紧凑，迁移最快；开环/切口环状DNA最松散，迁移最慢；线性DNA居中。", "kp": "ch04_s0_3"}], "judge": [{"id": "ch04_judge_1", "modI": 0, "q": "琼脂糖凝胶的分辨率高于聚丙烯酰胺凝胶，可区分仅相差一个碱基的DNA片段。", "a": "错", "e": "琼脂糖凝胶分辨率较低，但分离范围宽；聚丙烯酰胺凝胶分辨率高，可区分仅相差一个碱基的DNA片段，但分离范围窄。", "kp": "ch04_s0_8"}, {"id": "ch04_judge_2", "modI": 0, "q": "在凝胶电泳中，超螺旋DNA比开环或切口环状DNA迁移更快。", "a": "对", "e": "超螺旋DNA结构最紧凑，在凝胶网络中迁移最快；开环或切口环状DNA较松散，迁移最慢；线性DNA居中。", "kp": "ch04_s0_3"}], "fill": [{"id": "ch04_fill_1", "modI": 0, "q": "凝胶电泳中，DNA分子因磷酸骨架带________电荷，在电场中向________极迁移。", "a": "负,正", "kp": "ch04_s0_4"}, {"id": "ch04_fill_2", "modI": 0, "q": "超螺旋DNA结构最紧凑，在凝胶网络中迁移最________；开环或切口环状DNA较松散，迁移最________；线性DNA居中。", "a": "快,慢", "kp": "ch04_s0_3"}, {"id": "ch04_fill_3", "modI": 0, "q": "聚丙烯酰胺凝胶分辨率高，可分辨仅相差________个碱基对的DNA片段，但分离范围窄（约1至几百bp）。", "a": "一", "kp": "ch04_s0_8"}, {"id": "ch04_fill_4", "modI": 0, "q": "脉冲场凝胶电泳通过周期性改变________，使DNA分子在凝胶中不断调整取向，从而分离10kb至10Mb的大分子DNA。", "a": "电场方向", "kp": "ch04_s0_10"}], "short": [{"id": "ch04_short_1", "modI": 0, "q": "简述凝胶电泳分离DNA片段的基本原理，并说明琼脂糖与聚丙烯酰胺凝胶在分辨率和分离范围上的差异。", "a": "1. 原理：DNA因磷酸骨架带负电荷，在电场中向正极迁移；凝胶基质形成多孔网络，较长的分子更容易被网络捕获而移动较慢，较短的分子移动较快，从而实现按大小分离。2. 琼脂糖：分辨率较低，但分离范围宽，可分离几百bp至数十kb的DNA，适合常规DNA片段分析。3. 聚丙烯酰胺：分辨率高，可区分仅相差一个碱基的DNA片段，但分离范围窄（约1至几百bp），适合DNA测序、PCR产物精细分析和蛋白质电泳。4. 实验设计应根据目标片段大小和所需分辨率选择凝胶种类与浓度。", "kp": "ch04_s0_5"}], "calc": [{"id": "ch04_calc_1", "modI": 0, "q": "论述凝胶电泳中DNA拓扑构象对迁移率的影响，并说明该原理在质粒质量分析中的应用。", "a": "1. 超螺旋DNA结构最紧凑，在凝胶网络中迁移最快。2. 开环或切口环状DNA较松散，迁移最慢。3. 线性DNA迁移速度居中。4. 因此电泳不仅可分离不同大小的DNA，还可用于检测质粒DNA的超螺旋程度和拓扑构象变化。5. 应用：质粒质量分析中，可通过电泳条带判断质粒是否以超螺旋形式存在、是否存在开环或线性化降解产物，是质粒质量分析的常用方法。", "steps": "要点：三种构象的紧凑程度→迁移速度差异→电泳可检测拓扑构象变化→质粒质量分析应用。", "kp": "ch04_s0_3"}, {"id": "ch04_calc_2", "modI": 0, "q": "论述脉冲场凝胶电泳（PFGE）为何能分离普通凝胶电泳无法分辨的大分子DNA，并举例说明其应用。", "a": "1. 普通凝胶电泳中，大于10kb的DNA分子迁移速度接近，难以分离。2. PFGE通过周期性改变电场方向，使DNA分子在凝胶中不断调整取向。3. 较小的分子转向快、迁移快；较大的分子转向困难、迁移慢，从而按分子量、形状和拓扑特性分离。4. PFGE可有效分离10kb至10Mb的大分子DNA。5. 应用举例：分离完整的细菌或真菌染色体；酵母染色体PFGE可见16条条带，代表0.2Mb至2.2Mb的染色体；用于微生物基因组分型、染色体数目与大小分析、核型分析、基因组大小估计和染色体多态性研究。", "steps": "要点：普通电泳对大分子DNA分辨率不足→PFGE交替改变电场方向使长链DNA反复重定向→小分子转向快迁移快、大分子转向慢迁移慢→可分离Mb级DNA→酵母染色体和微生物分型等应用。", "kp": "ch04_s0_10"}], "term": [{"id": "ch04_term_1", "modI": 0, "term": "Gel Electrophoresis", "def": "在电场作用下使DNA/RNA或蛋白质通过凝胶基质，按分子大小（并受电荷、形状、拓扑性质等影响）进行分离的技术；分离后需用荧光染料（如EB）染色显示；是核酸分析最基础、最常用的手段，可判断片段大小、数量及纯度。", "kp": "ch04_s0_6"}, {"id": "ch04_term_2", "modI": 0, "term": "Agarose Gel", "def": "由琼脂糖形成的较大孔径多孔网络，分辨率低于聚丙烯酰胺，但分离范围宽，可分离几百bp至数十kb的DNA；浓度越高孔径越小，适合较小片段；制备简便，是常规DNA电泳最常用的基质。", "kp": "ch04_s0_6"}, {"id": "ch04_term_3", "modI": 0, "term": "Polyacrylamide Gel", "def": "由丙烯酰胺与交联剂聚合形成孔径较小且可精确调控的三维网络；分辨率高，可分辨仅相差一个碱基对的DNA片段，但分离范围窄（约1至几百bp）；广泛用于DNA测序、PCR产物精细分析及蛋白质单向/双向电泳。", "kp": "ch04_s0_6"}, {"id": "ch04_term_4", "modI": 0, "term": "Pulsed-Field Gel Electrophoresis (PFGE)", "def": "通过周期性改变电场方向，使DNA分子在凝胶中不断调整取向：小分子转向快、迁移快，大分子转向困难、迁移慢，从而按分子量、形状和拓扑特性分离；可有效分离10kb至10Mb的大分子DNA，是基因组图谱和染色体分析的重要方法。", "kp": "ch04_s0_10"}]}, {"i": 1, "name": "模块二：蛋白质电泳与层析", "slides": [{"i": 0, "sec": "模块二：蛋白质电泳与层析", "title": "蛋白质凝胶电泳概述 (p18)", "notes": "蛋白质凝胶电泳是分离和鉴定蛋白质的核心技术。常用SDS-PAGE，SDS使蛋白质变性并带上均匀负电荷，因此迁移率主要取决于分子量；非变性电泳则保留蛋白质天然构象与活性，迁移率受电荷、形状和大小共同影响。电泳后可进行染色或转膜检测，是蛋白质纯度分析、分子量测定及后续免疫检测的基础。", "page": 18, "level": "掌握", "img": "assets/img/ch04/p018.jpg", "anim": null, "fig": null, "points": ["SDS-PAGE中SDS使蛋白质变性并带均匀负电荷，迁移率主要取决于分子量", "非变性电泳保留天然构象与活性，迁移率受电荷、形状和大小共同影响", "电泳后可染色或转膜检测，用于纯度分析、分子量测定及免疫检测", "蛋白质凝胶电泳是分离和鉴定蛋白质的核心技术"], "check": {"q": "关于SDS-PAGE，下列叙述正确的是？", "o": ["A. SDS使蛋白质带上均匀正电荷", "B. 蛋白质迁移率主要取决于其天然构象", "C. SDS使蛋白质变性并带均匀负电荷，迁移率主要取决于分子量", "D. 非变性电泳中迁移率仅由分子量决定"], "a": "C", "e": "SDS使蛋白质变性并带上均匀负电荷，因此SDS-PAGE中迁移率主要取决于分子量；非变性电泳保留天然构象，迁移率受电荷、形状和大小共同影响。"}, "cards": [{"front": "SDS-PAGE中蛋白质的迁移率主要取决于什么？为什么？", "back": "主要取决于分子量。SDS使蛋白质变性并带上均匀负电荷，消除了电荷和形状差异的影响。", "mnemonic": "SDS=统一负电荷外衣，只看个头大小", "useImg": false}]}, {"i": 1, "sec": "模块二：蛋白质电泳与层析", "title": "蛋白质电泳分离示意图 (p19)", "notes": "本页为示意图，展示电泳分离蛋白质的基本原理与装置：在电场作用下，带电荷的蛋白质在凝胶中向相反电极迁移，因分子量、电荷和形状差异而被分离成不同条带。凝胶的分子筛效应使小分子蛋白质迁移较快，大分子受阻。该图直观说明了电泳作为蛋白质分析首要分离步骤的依据，为后续Western blotting和层析纯化奠定基础。", "page": 19, "level": "理解", "img": "assets/img/ch04/p019.jpg", "anim": null, "fig": "图示电泳装置与分离原理：凝胶置于电场中，蛋白质因电荷向对应电极移动，小分子穿过凝胶孔隙较快，大分子受阻，最终形成按大小/电荷/形状分布的条带。", "points": ["电场作用下蛋白质在凝胶中向相反电极迁移", "依据分子量、电荷和形状差异分离成不同条带", "凝胶分子筛效应使小分子迁移快，大分子受阻", "电泳是蛋白质分析首要分离步骤，为Western blotting和层析奠定基础"], "check": {"q": "电泳分离蛋白质时，凝胶分子筛效应表现为？", "o": ["A. 大分子蛋白质迁移较快", "B. 小分子蛋白质迁移较快，大分子受阻", "C. 所有蛋白质迁移速度相同", "D. 迁移速度只取决于所带电荷"], "a": "B", "e": "凝胶的分子筛效应使小分子蛋白质迁移较快，大分子受阻，从而按分子量等差异分离成条带。"}, "cards": [{"front": "非变性电泳与SDS-PAGE的关键区别是什么？", "back": "非变性电泳保留蛋白质天然构象与活性，迁移率受电荷、形状和大小共同影响；SDS-PAGE则变性并统一电荷，仅按分子量分离。", "mnemonic": "非变性=穿便装（保留本性），SDS=穿制服（统一标准）", "useImg": false}]}, {"i": 2, "sec": "模块二：蛋白质电泳与层析", "title": "Western Blotting 免疫检测 (p20)", "notes": "Western blotting（蛋白质印迹）利用抗体特异性识别电泳分离后转移到膜上的目标蛋白，实现定性和半定量检测。基本流程包括：SDS-PAGE分离、转膜（硝酸纤维素或PVDF膜）、封闭、一抗孵育、酶标二抗孵育及显色/发光检测。该方法灵敏度高、特异性强，广泛用于蛋白质表达验证、翻译后修饰分析及疾病标志物检测，是分子生物学中不可或缺的蛋白质分析技术。", "page": 20, "level": "掌握", "img": "assets/img/ch04/p020.jpg", "anim": null, "fig": null, "points": ["Western blotting利用抗体特异性识别膜上目标蛋白，实现定性和半定量检测", "基本流程：SDS-PAGE分离→转膜→封闭→一抗→酶标二抗→显色/发光检测", "转膜常用硝酸纤维素或PVDF膜", "灵敏度高、特异性强，用于表达验证、翻译后修饰分析及疾病标志物检测"], "check": {"q": "Western blotting的基本流程中，转膜之后紧接着的步骤通常是？", "o": ["A. SDS-PAGE分离", "B. 封闭", "C. 一抗孵育", "D. 显色/发光检测"], "a": "B", "e": "流程为SDS-PAGE分离、转膜、封闭、一抗孵育、酶标二抗孵育及显色/发光检测，转膜后先封闭。"}, "cards": [{"front": "Western blotting的基本流程是什么？", "back": "SDS-PAGE分离→转膜（硝酸纤维素或PVDF膜）→封闭→一抗孵育→酶标二抗孵育→显色/发光检测。", "mnemonic": "分-转-封-一-二-显", "useImg": false}]}, {"i": 3, "sec": "模块二：蛋白质电泳与层析", "title": "离子交换层析原理与介质 (p21)", "notes": "离子交换层析根据物质所带电荷差异进行分离。带正电荷的DEAE-Sephadex（交联葡聚糖）作为阴离子交换剂结合带负电的蛋白质；带负电荷的磷酸纤维素作为阳离子交换剂结合带正电的蛋白质。通过改变pH或盐浓度梯度洗脱，不同电荷性质的蛋白质被依次洗脱分离。该法分辨率高、载量大，常用于蛋白质粗提后的精细纯化，图示为两种酶形式被分离的实例。", "page": 21, "level": "掌握", "img": "assets/img/ch04/p021.jpg", "anim": null, "fig": "图示两种酶形式被分离的层析实例：横轴为洗脱体积，纵轴为蛋白质浓度/酶活性，不同电荷的蛋白质在不同盐浓度下依次形成洗脱峰。", "points": ["离子交换层析根据物质所带电荷差异分离", "DEAE-Sephadex为阴离子交换剂，结合带负电蛋白质；磷酸纤维素为阳离子交换剂，结合带正电蛋白质", "通过改变pH或盐浓度梯度洗脱，不同电荷性质蛋白质依次洗脱", "分辨率高、载量大，常用于粗提后精细纯化"], "check": {"q": "关于离子交换层析，下列叙述正确的是？", "o": ["A. DEAE-Sephadex是阳离子交换剂，结合带正电蛋白质", "B. 磷酸纤维素是阴离子交换剂，结合带负电蛋白质", "C. DEAE-Sephadex作为阴离子交换剂结合带负电的蛋白质", "D. 离子交换层析依据分子大小分离蛋白质"], "a": "C", "e": "DEAE-Sephadex为阴离子交换剂，结合带负电的蛋白质；磷酸纤维素为阳离子交换剂，结合带正电的蛋白质。"}, "cards": [{"front": "离子交换层析的分离依据是什么？DEAE-Sephadex和磷酸纤维素分别结合什么电荷的蛋白质？", "back": "依据电荷差异分离。DEAE-Sephadex为阴离子交换剂，结合带负电的蛋白质；磷酸纤维素为阳离子交换剂，结合带正电的蛋白质。", "mnemonic": "DEAE带正电抓负蛋白，磷酸纤维素带负电抓正蛋白——异性相吸", "useImg": false}]}, {"i": 4, "sec": "模块二：蛋白质电泳与层析", "title": "应用实例：真核生物RNA聚合酶的多重形式 (p22)", "notes": "以海胆胚胎为材料，经DEAE-Sephadex离子交换层析分离真核生物RNA聚合酶。绿色曲线代表蛋白质含量，红色峰代表RNA聚合酶活性，结果显示多个活性峰，提示存在RNA聚合酶I、II、III等多种形式（具体峰与酶的对应以原图注为准）；植物中还存在RNA聚合酶IV和V。该实例说明离子交换层析能有效分离功能相关但电荷性质不同的同工酶，为研究真核转录机制及酶的多型性提供了关键实验证据。", "page": 22, "level": "理解", "img": "assets/img/ch04/p022.jpg", "anim": null, "fig": "图示DEAE-Sephadex层析分离RNA聚合酶的结果：绿色曲线为蛋白质含量，红色峰为酶活性，可见多个活性峰提示存在多种RNA聚合酶形式（具体对应以图注为准）。", "points": ["以海胆胚胎为材料，经DEAE-Sephadex离子交换层析分离真核RNA聚合酶", "绿色曲线代表蛋白质含量，红色峰代表RNA聚合酶活性", "多个活性峰对应RNA聚合酶I、II、III；植物中还有IV和V", "说明离子交换层析能有效分离功能相关但电荷性质不同的同工酶"], "check": {"q": "海胆胚胎RNA聚合酶经DEAE-Sephadex层析出现多个活性峰，说明？", "o": ["A. RNA聚合酶只有一种形式", "B. 离子交换层析能分离电荷性质不同的同工酶", "C. 红色峰代表蛋白质含量", "D. 植物中不存在RNA聚合酶IV和V"], "a": "B", "e": "多个活性峰提示存在RNA聚合酶I、II、III等多种形式，说明离子交换层析可有效分离功能相关但电荷性质不同的同工酶。"}, "cards": [{"front": "凝胶过滤层析中，大分子和小分子谁先洗脱？为什么？", "back": "大分子先洗脱。大分子被排阻在凝胶珠外，路径短；小分子进入珠内孔隙，路径延长，洗脱较慢。", "mnemonic": "大个子走大路（珠外捷径），小个子钻小巷（珠内孔隙）", "useImg": false}]}, {"i": 5, "sec": "模块二：蛋白质电泳与层析", "title": "凝胶过滤层析原理 (p23)", "notes": "凝胶过滤层析（分子排阻层析）依据分子大小分离物质。层析柱填充多孔凝胶珠，小分子可进入珠内孔隙而路径延长、洗脱较慢；大分子被排阻在珠外，路径短、先被洗脱。因此蛋白质按分子量从大到小依次流出。该法条件温和，不依赖电荷，常用于蛋白质脱盐、缓冲液交换及分子量估算，也可与离子交换、亲和层析组合实现多步纯化。", "page": 23, "level": "掌握", "img": "assets/img/ch04/p023.jpg", "anim": null, "fig": null, "points": ["凝胶过滤层析（分子排阻层析）依据分子大小分离", "小分子进入凝胶珠孔隙，路径延长、洗脱慢；大分子被排阻，路径短、先洗脱", "蛋白质按分子量从大到小依次流出", "条件温和、不依赖电荷，用于脱盐、缓冲液交换、分子量估算及多步纯化组合"], "check": {"q": "凝胶过滤层析中，蛋白质的洗脱顺序是？", "o": ["A. 按分子量从小到大依次流出", "B. 按分子量从大到小依次流出", "C. 按所带电荷多少依次流出", "D. 所有蛋白质同时流出"], "a": "B", "e": "大分子被排阻在凝胶珠外，路径短、先洗脱；小分子进入孔隙路径长、洗脱慢，故按分子量从大到小流出。"}, "cards": [{"front": "亲和层析的原理是什么？举一个His标签纯化的例子。", "back": "利用生物分子间强而特异的亲和力：配体固定于基质，目标蛋白选择性结合，杂质洗去后改变条件洗脱。His标签与Ni2+高亲和结合，可用镍亲和层析一步纯化融合蛋白。", "mnemonic": "锁匙配对——His标签是钥匙，Ni2+是锁", "useImg": false}]}, {"i": 6, "sec": "模块二：蛋白质电泳与层析", "title": "亲和层析原理与应用 (p24)", "notes": "亲和层析利用生物分子间强而特异的亲和力进行纯化。将配体（如抗体、酶底物类似物、镍离子）固定于基质，目标蛋白选择性结合，杂质被洗去，再通过改变条件洗脱目标蛋白。例如融合蛋白中的寡聚组氨酸标签与Ni2+高亲和结合，可用镍亲和层析一步纯化。该法选择性极高、步骤简便，广泛用于重组蛋白纯化，图示了蛋白-抗体、酶-底物类似物及His标签-Ni2+等典型亲和体系。", "page": 24, "level": "掌握", "img": "assets/img/ch04/p024.jpg", "anim": null, "fig": "图示典型亲和体系：蛋白-抗体、酶-底物类似物及His标签-Ni2+，展示配体固定于基质后选择性结合目标蛋白，再洗脱纯化的过程。", "points": ["亲和层析利用生物分子间强而特异的亲和力进行纯化", "配体（抗体、酶底物类似物、镍离子等）固定于基质，目标蛋白选择性结合", "杂质洗去后，改变条件洗脱目标蛋白", "His标签与Ni2+高亲和结合，可用镍亲和层析一步纯化重组蛋白", "选择性极高、步骤简便，广泛用于重组蛋白纯化"], "check": {"q": "利用镍亲和层析一步纯化融合蛋白，依据的是？", "o": ["A. 寡聚组氨酸标签与Ni2+的高亲和结合", "B. 蛋白质所带电荷差异", "C. 蛋白质分子大小差异", "D. 蛋白质的疏水性差异"], "a": "A", "e": "融合蛋白中的寡聚组氨酸标签与Ni2+高亲和结合，杂质被洗去后改变条件洗脱目标蛋白，实现一步纯化。"}, "cards": [{"front": "海胆胚胎RNA聚合酶离子交换层析实验说明了什么？真核生物有哪些RNA聚合酶？", "back": "说明离子交换层析能有效分离电荷性质不同的同工酶。真核生物有RNA聚合酶I、II、III，植物中还有IV和V。", "mnemonic": "三峰见三酶，植物多两型（IV、V）", "useImg": false}]}], "mcq": [{"id": "ch04_mcq_6", "mod": "模块二：蛋白质电泳与层析", "modI": 1, "q": "在SDS-PAGE中，蛋白质的迁移率主要取决于下列哪一因素？", "o": ["A. 蛋白质的等电点", "B. 蛋白质的分子量", "C. 蛋白质的疏水性", "D. 蛋白质的二级结构"], "a": "B", "e": "SDS使蛋白质变性并带上均匀负电荷，消除了电荷差异，因此迁移率主要与分子量相关，分子量越小迁移越快。", "kp": "ch04_s1_0"}, {"id": "ch04_mcq_7", "mod": "模块二：蛋白质电泳与层析", "modI": 1, "q": "Western blotting中，一抗的作用是：", "o": ["A. 将蛋白质从凝胶转移到膜上", "B. 封闭膜上的非特异性结合位点", "C. 特异性识别并结合目标蛋白", "D. 催化显色反应"], "a": "C", "e": "一抗特异性识别目标蛋白，二抗携带酶或荧光基团用于检测；转膜、封闭和显色分别由其他步骤或试剂完成。", "kp": "ch04_s1_2"}, {"id": "ch04_mcq_8", "mod": "模块二：蛋白质电泳与层析", "modI": 1, "q": "关于DEAE-Sephadex离子交换层析，下列说法正确的是：", "o": ["A. 它带负电荷，结合带正电的蛋白质", "B. 它带正电荷，结合带负电的蛋白质", "C. 它按分子大小分离蛋白质", "D. 它利用抗原抗体亲和力纯化蛋白质"], "a": "B", "e": "DEAE-Sephadex为阴离子交换剂，带正电荷，可结合带负电荷的蛋白质；按大小分离是凝胶过滤，亲和纯化是亲和层析。", "kp": "ch04_s1_3"}, {"id": "ch04_mcq_9", "mod": "模块二：蛋白质电泳与层析", "modI": 1, "q": "凝胶过滤层析中，最先被洗脱出来的是：", "o": ["A. 分子量最大的蛋白质", "B. 分子量最小的蛋白质", "C. 带正电荷最多的蛋白质", "D. 疏水性最强的蛋白质"], "a": "A", "e": "大分子不能进入凝胶珠孔隙，被排阻在珠外，路径短，因此最先洗脱；小分子进入孔隙，路径长，洗脱较慢。", "kp": "ch04_s1_5"}, {"id": "ch04_mcq_10", "mod": "模块二：蛋白质电泳与层析", "modI": 1, "q": "镍亲和层析纯化融合蛋白所依据的原理是：", "o": ["A. 寡聚组氨酸标签与Ni2+的高亲和结合", "B. 蛋白质与Ni2+的离子交换作用", "C. 蛋白质分子大小差异", "D. 蛋白质等电点差异"], "a": "A", "e": "融合蛋白中的寡聚组氨酸标签（His-tag）与固定化Ni2+形成高亲和配位结合，从而实现特异性纯化，属于亲和层析。", "kp": "ch04_s1_6"}], "judge": [{"id": "ch04_judge_3", "modI": 1, "q": "SDS-PAGE中蛋白质的迁移率主要取决于其天然电荷和形状。", "a": "错", "e": "SDS使蛋白质变性并带上均匀负电荷，因此迁移率主要取决于分子量；非变性电泳才保留天然构象，迁移率受电荷、形状和大小共同影响。", "kp": "ch04_s1_0"}, {"id": "ch04_judge_4", "modI": 1, "q": "凝胶过滤层析中，大分子被排阻在凝胶珠外，路径短，先被洗脱。", "a": "对", "e": "小分子可进入珠内孔隙而路径延长、洗脱较慢；大分子被排阻在珠外，路径短、先被洗脱，因此蛋白质按分子量从大到小依次流出。", "kp": "ch04_s1_5"}, {"id": "ch04_judge_5", "modI": 1, "q": "亲和层析利用生物分子间强而特异的亲和力进行纯化，如His标签与Ni2+高亲和结合可一步纯化融合蛋白。", "a": "对", "e": "亲和层析将配体固定于基质，目标蛋白选择性结合，杂质被洗去后改变条件洗脱目标蛋白；His标签与Ni2+高亲和结合是典型亲和体系，选择性极高、步骤简便。", "kp": "ch04_s1_6"}], "fill": [{"id": "ch04_fill_5", "modI": 1, "q": "SDS-PAGE中，SDS使蛋白质变性并带上均匀________电荷，因此迁移率主要取决于________。", "a": "负,分子量", "kp": "ch04_s1_0"}, {"id": "ch04_fill_6", "modI": 1, "q": "凝胶过滤层析中，小分子可进入凝胶珠孔隙而路径延长、洗脱较________；大分子被排阻在珠外、先被洗脱，因此蛋白质按分子量从________到________依次流出。", "a": "慢,大,小", "kp": "ch04_s1_5"}], "short": [{"id": "ch04_short_2", "modI": 1, "q": "简述Western blotting的基本流程及其主要应用。", "a": "1. 基本流程：SDS-PAGE分离蛋白质→转膜（硝酸纤维素或PVDF膜）→封闭→一抗孵育→酶标二抗孵育→显色/发光检测。2. 原理：利用抗体特异性识别转移到膜上的目标蛋白，实现定性和半定量检测。3. 特点：灵敏度高、特异性强。4. 应用：蛋白质表达验证、翻译后修饰分析及疾病标志物检测，是分子生物学中不可或缺的蛋白质分析技术。", "kp": "ch04_s1_2"}], "calc": [], "term": [{"id": "ch04_term_5", "modI": 1, "term": "SDS-PAGE", "def": "十二烷基硫酸钠-聚丙烯酰胺凝胶电泳；SDS使蛋白质变性并带上均匀负电荷，因此迁移率主要取决于分子量；是蛋白质纯度分析、分子量测定及Western blotting前分离的基础技术。", "kp": "ch04_s1_0"}, {"id": "ch04_term_6", "modI": 1, "term": "Western Blotting", "def": "蛋白质印迹；利用抗体特异性识别电泳分离后转移到膜（硝酸纤维素或PVDF膜）上的目标蛋白，实现定性和半定量检测；流程包括SDS-PAGE分离、转膜、封闭、一抗孵育、酶标二抗孵育及显色/发光检测；灵敏度高、特异性强。", "kp": "ch04_s1_2"}, {"id": "ch04_term_7", "modI": 1, "term": "Ion Exchange Chromatography", "def": "根据物质所带电荷差异进行分离的层析方法；带正电的DEAE-Sephadex作为阴离子交换剂结合带负电蛋白质，磷酸纤维素作为阳离子交换剂结合带正电蛋白质；通过改变pH或盐浓度梯度洗脱，分辨率高、载量大，常用于蛋白质精细纯化。", "kp": "ch04_s1_2"}, {"id": "ch04_term_8", "modI": 1, "term": "Gel Filtration Chromatography", "def": "凝胶过滤层析（分子排阻层析）；依据分子大小分离物质，小分子可进入凝胶珠孔隙而路径延长、洗脱较慢，大分子被排阻在珠外、先被洗脱；蛋白质按分子量从大到小依次流出；条件温和，常用于脱盐、缓冲液交换及分子量估算。", "kp": "ch04_s1_2"}, {"id": "ch04_term_9", "modI": 1, "term": "Affinity Chromatography", "def": "利用生物分子间强而特异的亲和力进行纯化；将配体（抗体、酶底物类似物、镍离子等）固定于基质，目标蛋白选择性结合，杂质被洗去后改变条件洗脱目标蛋白；如His标签与Ni2+高亲和结合可一步纯化融合蛋白；选择性极高、步骤简便。", "kp": "ch04_s1_2"}]}, {"i": 2, "name": "模块三：分子杂交（探针·Southern/Northern·FISH）", "slides": [{"i": 0, "sec": "分子杂交", "title": "分子杂交的定义(p25)", "notes": "分子杂交是指来自不同来源的两条互补单链核酸，在合适的离子强度和温度条件下，通过碱基互补配对结合形成双链的过程。该定义强调了杂交的两个关键条件：离子强度影响静电屏蔽与链间排斥，温度影响分子热运动与配对稳定性；同时也说明杂交的本质是序列特异性识别，是后续探针检测、印迹杂交和原位杂交技术的共同理论基础。", "page": 25, "level": "掌握", "img": "assets/img/ch04/p025.jpg", "anim": null, "fig": null, "points": ["分子杂交定义：不同来源的两条互补单链核酸在合适离子强度和温度下碱基互补配对形成双链", "关键条件：离子强度影响静电屏蔽与链间排斥，温度影响热运动与配对稳定性", "本质是序列特异性识别，是探针检测、印迹杂交和原位杂交的共同理论基础"], "check": {"q": "根据分子杂交的定义，下列哪项是杂交顺利进行的关键条件？", "o": ["A. 合适的离子强度和温度", "B. 高浓度SDS和高温", "C. 强酸强碱环境", "D. 高浓度有机溶剂"], "a": "A", "e": "定义强调在合适的离子强度和温度条件下，两条互补单链核酸通过碱基互补配对形成双链。"}, "cards": [{"front": "什么是分子杂交？", "back": "来自不同来源的两条互补单链核酸，在合适离子强度和温度下通过碱基互补配对形成双链的过程。", "mnemonic": "两条单链，条件合适，互补配对成双链", "useImg": false}, {"front": "Southern、Northern、原位杂交三者如何比较？", "back": "Southern（DNA印迹）用于基因组DNA、重组质粒和噬菌体DNA的特异性鉴定；Northern（RNA印迹）用于RNA定性定量分析以检测基因活性；原位杂交无需提取核酸，原位观察DNA序列在染色体上的定位，保留空间位置信息。", "mnemonic": "Southern鉴DNA，Northern测RNA，原位保位置", "useImg": false}]}, {"i": 1, "sec": "分子杂交", "title": "杂交探针可鉴定电泳分离的DNA和RNA(p26)", "notes": "本页标题点明杂交探针的核心用途：在电泳按大小分离核酸之后，用已知序列的标记探针与膜上核酸进行杂交，从而在众多片段中特异性地识别目标DNA或RNA。其原理是探针与目标序列互补配对，信号只出现在含目标序列的条带位置，因此杂交把“分离”与“特异识别”结合起来，是Southern、Northern等印迹技术的共同检测环节。", "page": 26, "level": "掌握", "img": "assets/img/ch04/p026.jpg", "anim": null, "fig": null, "points": ["杂交探针用于电泳分离后特异识别目标DNA或RNA", "原理：探针与目标序列互补配对，信号只出现在含目标序列的条带位置", "把“分离”与“特异识别”结合，是Southern、Northern等印迹技术的共同检测环节"], "check": {"q": "关于杂交探针在电泳分离后检测核酸的作用，下列说法正确的是？", "o": ["A. 探针可改变核酸片段在凝胶中的迁移率", "B. 探针与目标序列互补配对，信号只出现在含目标序列的条带位置", "C. 探针只能检测RNA，不能检测DNA", "D. 探针杂交前必须先对核酸进行PCR扩增"], "a": "B", "e": "探针与目标序列互补配对，信号只出现在含目标序列的条带位置，实现特异性识别。"}, "cards": [{"front": "分子杂交的两个关键条件是什么？各影响什么？", "back": "离子强度（影响静电屏蔽与链间排斥）和温度（影响分子热运动与配对稳定性）。", "mnemonic": "离子管排斥，温度管稳定", "useImg": false}]}, {"i": 2, "sec": "分子杂交", "title": "探针的标记与种类(p27)", "notes": "探针是已知序列的多聚核苷酸链，需先用放射性同位素或荧光素、生物素、地高辛等非放射性物质标记末端或全链，长度一般约10–50 bp。常见种类包括：cDNA探针（与mRNA互补、不含内含子）、RNA探针（杂交信号强但易降解）和寡聚核苷酸探针（可按需合成，常用于检测突变）。探针的标记与选择直接决定杂交的灵敏度、特异性和检测方式。", "page": 27, "level": "掌握", "img": "assets/img/ch04/p027.jpg", "anim": null, "fig": null, "points": ["探针是已知序列的多聚核苷酸链，需用放射性同位素或非放射性物质标记", "长度一般约10–50 bp，可标记末端或全链", "常见种类：cDNA探针（与mRNA互补、不含内含子）、RNA探针（信号强但易降解）、寡聚核苷酸探针（可合成、常用于检测突变）", "探针标记与选择决定杂交灵敏度、特异性和检测方式"], "check": {"q": "下列关于探针的叙述，错误的是？", "o": ["A. cDNA探针与mRNA互补且不含内含子", "B. RNA探针杂交信号强但易降解", "C. 寡聚核苷酸探针可按需合成，常用于检测突变", "D. 探针长度一般约1000–2000 bp"], "a": "D", "e": "探针长度一般约10–50 bp，而非1000–2000 bp。"}, "cards": [{"front": "杂交探针在电泳分离后的核心用途是什么？", "back": "用已知序列的标记探针与膜上核酸杂交，在众多片段中特异性识别目标DNA或RNA，信号只出现在含目标序列的条带位置。", "mnemonic": "分离靠电泳，识别靠探针", "useImg": false}]}, {"i": 3, "sec": "分子杂交", "title": "探针标记物与检测方式(p28)", "notes": "本页比较四类标记：放射性标记（如³²P）通过X光胶片曝光自显影检测，灵敏度高但有放射性风险；地高辛标记用抗DIG抗体结合酶促显色或化学发光检测，是常用的非放射性方法；生物素标记利用生物素与链霉亲和素的高亲和力，用streptavidin-HRP/AP检测；荧光标记（如Cy3、Cy5、FAM）可直接观察荧光信号，常用于原位杂交和芯片。选择标记需权衡灵敏度、安全性与检测设备。", "page": 28, "level": "掌握", "img": "assets/img/ch04/p028.jpg", "anim": null, "fig": null, "points": ["放射性标记（如³²P）：X光胶片自显影检测，灵敏度高但有放射性风险", "地高辛标记：抗DIG抗体结合酶促显色或化学发光，常用非放射性方法", "生物素标记：利用生物素与链霉亲和素高亲和力，用streptavidin-HRP/AP检测", "荧光标记（Cy3、Cy5、FAM）：直接观察荧光信号，常用于原位杂交和芯片", "选择标记需权衡灵敏度、安全性与检测设备"], "check": {"q": "下列探针标记物与检测方式的对应关系，错误的是？", "o": ["A. 放射性标记（如³²P）——X光胶片曝光自显影", "B. 地高辛标记——抗DIG抗体结合酶促显色或化学发光", "C. 生物素标记——利用生物素与链霉亲和素的高亲和力检测", "D. 荧光标记——必须通过X光胶片曝光检测"], "a": "D", "e": "荧光标记（如Cy3、Cy5、FAM）可直接观察荧光信号，不需要X光胶片曝光。"}, "cards": [{"front": "探针是什么？长度一般多少？", "back": "已知序列的多聚核苷酸链，需用放射性同位素或非放射性物质标记，长度一般约10–50 bp。", "mnemonic": "已知序列短链，10到50碱基", "useImg": false}]}, {"i": 4, "sec": "分子杂交", "title": "探针标记的三种方式(p29)", "notes": "探针标记主要有三种方式：一是在人工合成短DNA时直接加入荧光或其他标记；二是在PCR等DNA合成过程中掺入带标记的核苷酸，使标记进入新合成链；三是在已制备好的DNA末端加上标记。前两种属于链内标记，可控制标记密度；末端标记对序列影响小、操作简便。不同标记方式适用于不同探针类型和检测目的，是杂交实验设计的重要环节。", "page": 29, "level": "理解", "img": "assets/img/ch04/p029.jpg", "anim": null, "fig": null, "points": ["方式一：人工合成短DNA时直接加入荧光或其他标记", "方式二：PCR等DNA合成过程中掺入带标记核苷酸，使标记进入新合成链", "方式三：在已制备好的DNA末端加上标记", "前两种属链内标记可控制标记密度；末端标记对序列影响小、操作简便"], "check": {"q": "关于探针标记的三种方式，下列叙述正确的是？", "o": ["A. 三种方式均属于末端标记", "B. 人工合成短DNA时直接加入标记和在PCR中掺入标记核苷酸均属于链内标记", "C. 末端标记会显著改变探针序列", "D. 已制备好的DNA不能进行末端标记"], "a": "B", "e": "前两种（合成时加入标记、PCR掺入标记核苷酸）属于链内标记，末端标记对序列影响小。"}, "cards": [{"front": "常见探针有哪三种？各自特点是什么？", "back": "cDNA探针（与mRNA互补、不含内含子）；RNA探针（杂交信号强但易降解）；寡聚核苷酸探针（可按需合成，常用于检测突变）。", "mnemonic": "cDNA无内含子，RNA强但易降解，寡核苷酸测突变", "useImg": false}]}, {"i": 5, "sec": "Southern印迹", "title": "Southern印迹杂交及其命名(p30)", "notes": "Southern blot hybridization由Edwin Southern发明并以他命名，是检测DNA片段的标准印迹杂交技术。其基本思路是：先用电泳按大小分离DNA片段，再将DNA变性并转移到固相膜上，最后用标记探针杂交检测目标序列。该技术把凝胶电泳的分辨能力与核酸杂交的特异性结合起来，可用于基因组DNA、重组质粒和噬菌体DNA的特异性鉴定。", "page": 30, "level": "掌握", "img": "assets/img/ch04/p030.jpg", "anim": null, "fig": null, "points": ["Southern blot hybridization由Edwin Southern发明并以他命名", "基本思路：电泳分离DNA→变性→转膜→标记探针杂交检测目标序列", "结合凝胶电泳分辨能力与核酸杂交特异性", "用于基因组DNA、重组质粒和噬菌体DNA的特异性鉴定"], "check": {"q": "关于Southern印迹杂交，下列说法正确的是？", "o": ["A. 由Edwin Southern发明并以他命名，用于检测DNA片段", "B. 主要用于检测RNA片段", "C. 不需要电泳分离，直接杂交", "D. 杂交前不需要将DNA变性为单链"], "a": "A", "e": "Southern blot由Edwin Southern发明并命名，是检测DNA片段的标准印迹杂交技术。"}, "cards": [{"front": "四类探针标记物及检测方式分别是什么？", "back": "放射性标记（如³²P，X光胶片自显影，灵敏度高但有辐射风险）；地高辛（抗DIG抗体酶促显色或化学发光）；生物素（链霉亲和素-HRP/AP检测）；荧光（Cy3、Cy5、FAM，直接观察，常用于原位杂交和芯片）。", "mnemonic": "放射自显影，DIG显色发光，生物素亲和素，荧光直接看", "useImg": false}]}, {"i": 6, "sec": "Southern印迹", "title": "Southern印迹的操作流程(p31)", "notes": "流程为：琼脂糖凝胶电泳分离DNA片段；碱性溶液处理使DNA变性为单链；将单链DNA从凝胶转移到硝酸纤维膜上，可用毛细扩散（缓冲液流过凝胶带动DNA转移）或电场转移；转移后膜上条带不可见，需用非特异性DNA或蛋白质封闭，再加入标记探针孵育杂交；最后通过放射自显影或磷光成像检测阳性条带。变性、转膜、封闭和杂交是保证特异性与低背景的关键步骤。", "page": 31, "level": "掌握", "img": "assets/img/ch04/p031.jpg", "anim": null, "fig": null, "points": ["流程：琼脂糖凝胶电泳分离DNA片段", "碱性溶液处理使DNA变性为单链", "转膜：毛细扩散（缓冲液带动DNA转移）或电场转移至硝酸纤维膜", "封闭后用标记探针孵育杂交，放射自显影或磷光成像检测阳性条带", "变性、转膜、封闭和杂交是保证特异性与低背景的关键步骤"], "check": {"q": "Southern印迹操作流程中，将单链DNA从凝胶转移到硝酸纤维膜可采用的方式是？", "o": ["A. 只能采用毛细扩散转移", "B. 只能采用电场转移", "C. 毛细扩散（缓冲液流过凝胶带动DNA转移）或电场转移", "D. 只能采用真空干燥转移"], "a": "C", "e": "转移单链DNA可用毛细扩散或电场转移两种方式。"}, "cards": [{"front": "探针标记的三种方式是什么？", "back": "①人工合成短DNA时直接加入标记；②PCR等DNA合成中掺入带标记核苷酸；③已制备DNA末端加标记。前两种为链内标记，末端标记对序列影响小、操作简便。", "mnemonic": "合成加、掺入加、末端加", "useImg": false}]}, {"i": 7, "sec": "Southern印迹", "title": "Southern印迹的命名与原理(p32)", "notes": "本页再次强调Southern blot hybridization以发明者Edwin Southern命名（注：PPT p32原文写作 Edward Southern，系笔误，正确为 Edwin Southern），并概括其原理：DNA经限制性内切酶切割、电泳分离、变性转膜后，与标记探针进行互补杂交，只有含目标序列的片段才产生信号。该技术是分子生物学中DNA定性和半定量分析的基础方法，也是后续DNA指纹分析和基因鉴定等应用的技术原型。", "page": 32, "level": "理解", "img": "assets/img/ch04/p032.jpg", "anim": null, "fig": null, "points": ["Southern blot以发明者Edwin Southern命名", "原理：限制性内切酶切割→电泳分离→变性转膜→与标记探针互补杂交，仅含目标序列的片段产生信号", "是DNA定性和半定量分析的基础方法", "是DNA指纹分析和基因鉴定等应用的技术原型"], "check": {"q": "关于Southern印迹杂交，下列叙述正确的是？", "o": ["A. 以发明者Edwin Southern命名，用于DNA的定性和半定量分析", "B. 以发明者Northern命名，用于RNA分析", "C. 直接将未酶切的DNA点样于膜上杂交", "D. 探针与目标片段通过共价交联产生信号"], "a": "A", "e": "Southern blot以发明者Edwin Southern命名，DNA经酶切、电泳、变性转膜后与标记探针互补杂交，是DNA定性和半定量分析的基础方法。"}, "cards": [{"front": "Southern印迹杂交由谁发明？基本思路是什么？", "back": "由Edwin Southern发明并以他命名。思路：电泳按大小分离DNA→变性并转移到固相膜→标记探针杂交检测目标序列。", "mnemonic": "Southern做DNA，电泳-变性-转膜-杂交", "useImg": false}]}, {"i": 8, "sec": "Southern印迹", "title": "DNA指纹技术及其法医学应用(p33)", "notes": "DNA指纹技术利用人α-珠蛋白基因（α-globin gene）及基因组其他位置存在的微卫星序列（minisatellite）。（注：PPT原文作“人血清a-球蛋白基因”，α-珠蛋白位于红细胞血红蛋白中，不在血清，PPT表述有误。）每个个体重复序列的模式不同，两个模式完全相同的个体几乎不存在，故称DNA指纹。限制性内切酶HaeIII只在微卫星序列两侧切割而非内部，经电泳、转膜后与含微卫星序列的放射性DNA探针杂交，用X光胶片检测，可得到个体特异的条带图谱，用于法医学鉴别。", "page": 33, "level": "掌握", "img": "assets/img/ch04/p033.jpg", "anim": null, "fig": null, "points": ["DNA指纹利用人α-珠蛋白基因及基因组其他位置的微卫星（minisatellite）序列", "每个个体重复序列模式不同，两个模式完全相同的个体几乎不存在", "HaeIII只在微卫星序列两侧切割而非内部", "经电泳、转膜后与含微卫星序列的放射性探针杂交，X光胶片检测得到个体特异条带图谱", "用于法医学鉴别"], "check": {"q": "DNA指纹技术中，限制性内切酶HaeIII的作用特点是？", "o": ["A. 在微卫星序列内部切割", "B. 只在微卫星序列两侧切割", "C. 随机切割整个基因组", "D. 只切割α-球蛋白基因编码区"], "a": "B", "e": "HaeIII只在微卫星序列两侧切割而非内部，使含不同重复次数的片段长度产生多态，经电泳转膜后与微卫星探针杂交得到个体特异图谱。"}, "cards": [{"front": "Southern印迹的完整操作流程是什么？", "back": "琼脂糖凝胶电泳分离DNA→碱性溶液变性为单链→转膜（毛细扩散或电场转移）→封闭→标记探针杂交→放射自显影或磷光成像检测阳性条带。", "mnemonic": "电泳、变性、转膜、封闭、杂交、显影", "useImg": false}]}, {"i": 9, "sec": "Southern印迹", "title": "DNA指纹图谱示意图(p34)", "notes": "本页为示意图，结合前后页可理解为：不同个体基因组DNA经HaeIII酶切后，因微卫星重复次数不同而形成长度多态的片段；电泳分离并转膜后，用微卫星探针杂交，自显影得到由多条条带组成的个体特异图谱。条带组合的差异直观体现个体间重复序列模式的不同，说明DNA指纹可用于身份鉴定和亲子鉴定，其基础是限制性片段长度多态性与杂交特异性。", "page": 34, "level": "理解", "img": "assets/img/ch04/p034.jpg", "anim": null, "fig": "看图中不同个体泳道的条带组合：每条带对应一个微卫星重复次数不同的片段，比较泳道间条带的数目和位置差异，即可直观看出个体特异的图谱。", "points": ["不同个体基因组DNA经HaeIII酶切后因微卫星重复次数不同形成长度多态片段", "电泳分离并转膜后用微卫星探针杂交，自显影得到多条条带组成的个体特异图谱", "条带组合差异体现个体间重复序列模式不同，可用于身份鉴定和亲子鉴定", "基础是限制性片段长度多态性与杂交特异性"], "check": {"q": "DNA指纹图谱中个体间条带差异的根本原因是？", "o": ["A. 探针序列在不同个体中完全不同", "B. 微卫星重复次数不同导致限制性片段长度多态", "C. 电泳缓冲液浓度不同", "D. 转膜时DNA变性程度不同"], "a": "B", "e": "不同个体微卫星重复次数不同，HaeIII酶切后形成长度多态的片段，电泳分离并用微卫星探针杂交后呈现个体特异的条带组合。"}, "cards": [{"front": "Southern印迹中变性、转膜、封闭、杂交各起什么作用？", "back": "变性使DNA成单链便于探针配对；转膜把片段固定到固相膜；封闭用非特异性DNA或蛋白质降低背景；杂交实现探针与目标序列特异结合。", "mnemonic": "变性开链，转膜固定，封闭降背景，杂交定目标", "useImg": false}]}, {"i": 10, "sec": "Northern印迹", "title": "Northern印迹杂交及基因转录活性检测(p35)", "notes": "Northern blotting与Southern blotting类似，只是电泳分离的对象由DNA换为RNA，转膜后与标记探针杂交检测特定RNA，条带强度反映该RNA的相对含量。若想知道某基因在各组织器官中的转录活性，可收集不同组织样本、提取RNA、电泳、转膜、探针杂交、X光胶片检测，观察条带大小和强度。该技术是RNA定性和定量分析、研究基因表达调控的经典方法。", "page": 35, "level": "掌握", "img": "assets/img/ch04/p035.jpg", "anim": null, "fig": null, "points": ["Northern blotting与Southern类似，但电泳分离对象为RNA", "转膜后与标记探针杂交检测特定RNA，条带强度反映该RNA的相对含量", "检测基因转录活性：收集不同组织样本→提取RNA→电泳→转膜→探针杂交→X光胶片检测，观察条带大小和强度", "是RNA定性和定量分析、研究基因表达调控的经典方法"], "check": {"q": "Northern印迹杂交与Southern印迹杂交的主要区别是？", "o": ["A. 电泳分离的对象由DNA换为RNA", "B. 不使用探针杂交", "C. 不需要转膜", "D. 只能检测DNA含量"], "a": "A", "e": "Northern blotting与Southern类似，但分离对象为RNA，杂交后条带强度反映特定RNA的相对含量，用于基因转录活性分析。"}, "cards": [{"front": "DNA指纹技术的原理是什么？", "back": "利用基因组中微卫星（minisatellite）重复序列，每个个体重复模式不同。HaeIII只在微卫星两侧切割，电泳转膜后用微卫星放射性探针杂交，得到个体特异条带图谱，用于法医学鉴别。", "mnemonic": "微卫星重复人人不同，HaeIII切两侧，探针显个体图谱", "useImg": false}]}, {"i": 11, "sec": "FISH", "title": "荧光原位杂交检测染色体结构(p36)", "notes": "荧光原位杂交（FISH）用甲酰胺联合加热使固定细胞中的双链DNA变性，再加入标记DNA探针杂交，通过荧光成像直接观察探针在染色体上的位置。固定常用4%多聚甲醛（PFA）以保持细胞和染色体形态。FISH无需提取核酸，能在原位保留目标核酸的空间位置信息，因此特别适合DNA序列在染色体上的定位分析和细胞核内染色质结构研究。", "page": 36, "level": "掌握", "img": "assets/img/ch04/p036.jpg", "anim": null, "fig": "看图中操作顺序：固定细胞内的双链DNA→甲酰胺/加热变性为单链→加入标记DNA探针杂交→荧光成像；信号点即目标序列在染色体上的位置。", "points": [], "check": {"q": "关于荧光原位杂交（FISH），下列叙述正确的是？", "o": ["A. 必须先将核酸提取纯化后再杂交", "B. 用甲酰胺联合加热使固定细胞中双链DNA变性后与标记探针杂交", "C. 固定细胞常用乙醇以保持染色体形态", "D. 无法保留目标核酸的空间位置信息"], "a": "B", "e": "FISH用甲酰胺联合加热使固定细胞中双链DNA变性，再加入标记DNA探针杂交，荧光成像直接观察探针在染色体上的位置；固定常用4%多聚甲醛。"}, "cards": [{"front": "Northern印迹与Southern印迹的主要区别是什么？", "back": "Northern电泳分离对象是RNA而非DNA，转膜后与标记探针杂交检测特定RNA，条带强度反映RNA相对含量，用于基因转录活性与表达调控研究。", "mnemonic": "Southern看DNA，Northern看RNA", "useImg": false}]}, {"i": 12, "sec": "FISH", "title": "染色体涂染与间期核染色质组织(p37)", "notes": "本页展示染色体涂染（chromosome painting）：用不同荧光标记的探针分别标记1号染色体（红色）和9号染色体（绿色），在间期细胞核中显示各染色体所占的“领地”。结果表明间期核内染色质并非随机分布，而是各染色体占据相对独立的区域，这种空间组织与基因表达调控和核内功能分区有关。FISH因此成为研究染色质三维组织的重要工具。", "page": 37, "level": "理解", "img": "assets/img/ch04/p037.jpg", "anim": null, "fig": "看间期细胞核内红色与绿色荧光区域：红、绿分别代表1号和9号染色体，二者各占相对独立的“领地”而不混杂，说明染色质在核内呈非随机空间组织。", "points": ["染色体涂染：用不同荧光标记探针分别标记1号染色体（红色）和9号染色体（绿色）", "间期细胞核中显示各染色体所占的“领地”", "间期核内染色质并非随机分布，各染色体占据相对独立区域", "空间组织与基因表达调控和核内功能分区有关，FISH是研究染色质三维组织的重要工具"], "check": {"q": "染色体涂染实验（1号染色体红色、9号染色体绿色标记）在间期核中显示的结果说明？", "o": ["A. 间期核内染色质随机分布", "B. 各染色体在间期核内占据相对独立的区域（领地）", "C. 只有1号和9号染色体存在于间期核", "D. 荧光标记会改变染色体的空间位置"], "a": "B", "e": "染色体涂染显示间期核内各染色体占据相对独立的“领地”，染色质并非随机分布，这种空间组织与基因表达调控和核内功能分区有关。"}, "cards": [{"front": "如何用Northern印迹检测某基因在各组织中的转录活性？", "back": "收集不同组织样本→提取RNA→电泳→转膜→探针杂交→X光胶片检测，观察条带大小和强度。", "mnemonic": "多组织提RNA，电泳转膜杂交看条带", "useImg": false}]}, {"i": 13, "sec": "FISH", "title": "染色质三维组织与转录活性的基因组尺度成像(p38)", "notes": "本页标题指向基因组尺度的成像研究：结合FISH、荧光标记和显微成像，在全基因组水平同时观察染色质的三维空间组织及其转录活性。这类方法可揭示染色体领地、染色质环和转录工厂等结构特征，把序列定位信息与功能状态联系起来，说明原位杂交技术已从单基因定位发展到多靶标、高通量的基因组尺度成像分析。", "page": 38, "level": "了解", "img": "assets/img/ch04/p038.jpg", "anim": null, "fig": null, "points": ["结合FISH、荧光标记和显微成像，在全基因组水平同时观察染色质三维空间组织及转录活性", "可揭示染色体领地、染色质环和转录工厂等结构特征", "把序列定位信息与功能状态联系起来", "原位杂交已从单基因定位发展到多靶标、高通量的基因组尺度成像分析"], "check": {"q": "基因组尺度成像研究染色质三维组织与转录活性的意义在于？", "o": ["A. 只能定位单个基因，无法多靶标分析", "B. 把序列定位信息与功能状态联系起来，可揭示染色体领地、染色质环和转录工厂等特征", "C. 完全替代测序技术", "D. 仅能在分裂期染色体上进行"], "a": "B", "e": "结合FISH、荧光标记和显微成像，可在全基因组水平同时观察染色质三维组织及转录活性，把序列定位与功能状态联系，实现多靶标、高通量的基因组尺度成像分析。"}, "cards": [{"front": "FISH的基本原理和固定方法是什么？", "back": "用甲酰胺联合加热使固定细胞中双链DNA变性，加入标记DNA探针杂交，荧光成像观察探针在染色体上的位置。固定常用4%多聚甲醛（PFA）保持形态。", "mnemonic": "甲酰胺加热变性，荧光探针原位看位置", "useImg": false}]}, {"i": 14, "sec": "核酸杂交技术", "title": "三类核酸杂交技术的比较与总结(p39)", "notes": "本页总结三类技术：DNA印迹（Southern blotting）用于基因组DNA、重组质粒和噬菌体DNA的特异性鉴定；RNA印迹（Northern blotting）与Southern类似但电泳对象为RNA，用于RNA定性定量分析以检测基因活性；原位杂交（in situ hybridization）无需核酸提取，在原位观察DNA序列在染色体上的定位，强调保留目标核酸的空间位置信息。三者共同构成核酸杂交技术体系。", "page": 39, "level": "掌握", "img": "assets/img/ch04/p039.jpg", "anim": null, "fig": null, "points": ["DNA印迹（Southern blotting）：用于基因组DNA、重组质粒和噬菌体DNA的特异性鉴定", "RNA印迹（Northern blotting）：电泳对象为RNA，用于RNA定性定量分析以检测基因活性", "原位杂交（in situ hybridization）：无需核酸提取，原位观察DNA序列在染色体上的定位，保留空间位置信息", "三者共同构成核酸杂交技术体系"], "check": {"q": "关于三类核酸杂交技术的应用，下列叙述正确的是？", "o": ["A. Southern blotting主要用于RNA的定性和定量分析", "B. Northern blotting可用于检测基因活性，对RNA进行定性和定量分析", "C. 原位杂交必须先从细胞中提取核酸再进行杂交", "D. 原位杂交不能保留目标核酸的空间位置信息"], "a": "B", "e": "Northern blotting以RNA为电泳对象，用于RNA定性定量分析以检测基因活性；Southern用于DNA鉴定，原位杂交无需核酸提取并保留空间位置信息。"}, "cards": [{"front": "FISH相比印迹杂交的独特优势是什么？", "back": "无需提取核酸，能在原位保留目标核酸的空间位置信息，适合DNA序列在染色体上的定位分析和细胞核内染色质结构研究。", "mnemonic": "不提取，保位置，看原位", "useImg": false}]}, {"i": 15, "sec": "核酸杂交技术", "title": "核酸杂交技术综合示意图(p40)", "notes": "本页为综合示意图，结合前后页可理解为：从核酸样品出发，经电泳分离、变性转膜、标记探针杂交和信号检测完成印迹杂交；或不经提取，直接对固定细胞/染色体变性后进行原位杂交并荧光成像。图示把Southern、Northern和FISH统一到“互补配对—特异识别—信号检测”的框架下，突出不同技术在选择样品、转膜与否及空间信息保留上的差异。", "page": 40, "level": "理解", "img": "assets/img/ch04/p040.jpg", "anim": null, "fig": "看图中两条并行路线：上方为印迹杂交（电泳→转膜→杂交→检测），下方为原位杂交（固定细胞→变性→杂交→荧光成像），对比可见二者在转膜与空间信息保留上的差别。", "points": ["印迹杂交路线：核酸样品→电泳分离→变性转膜→标记探针杂交→信号检测", "原位杂交路线：不经提取，直接对固定细胞/染色体变性后杂交并荧光成像", "统一框架：互补配对—特异识别—信号检测", "差异在于样品选择、是否转膜及是否保留空间信息"], "check": {"q": "根据核酸杂交技术综合示意图，下列哪项最能概括Southern、Northern和FISH的共同框架？", "o": ["A. 均需先提取核酸再电泳转膜", "B. 均依赖互补配对—特异识别—信号检测", "C. 均能保留目标核酸在细胞内的空间位置", "D. 均以RNA为检测对象"], "a": "B", "e": "图示把三类技术统一到“互补配对—特异识别—信号检测”的框架下，差异在于样品选择、是否转膜及是否保留空间信息。"}, "cards": [{"front": "染色体涂染实验说明了间期核染色质的什么组织特征？", "back": "用不同荧光探针标记不同染色体，在间期核中显示各染色体占据相对独立的“领地”，说明染色质并非随机分布，其空间组织与基因表达调控和核内功能分区有关。", "mnemonic": "各有领地，非随机分布", "useImg": false}]}], "mcq": [{"id": "ch04_mcq_11", "mod": "模块三：分子杂交（探针·Southern/Northern·FISH）", "modI": 2, "q": "下列关于核酸分子杂交的叙述，正确的是：", "o": ["A. 杂交是两条同源双链DNA之间通过共价键结合的过程", "B. 杂交是互补单链核酸在合适离子强度和温度下通过碱基配对结合的过程", "C. 杂交只能在放射性标记条件下发生", "D. 杂交过程中探针必须与目标序列完全相同才能结合"], "a": "B", "e": "分子杂交的本质是互补单链核酸在合适离子强度和温度下通过碱基互补配对形成双链，不涉及共价键，也不依赖标记类型；探针与目标序列互补即可，无需完全相同。", "kp": "ch04_s2_0"}, {"id": "ch04_mcq_12", "mod": "模块三：分子杂交（探针·Southern/Northern·FISH）", "modI": 2, "q": "Southern blot hybridization 的基本流程是：", "o": ["A. 提取RNA→电泳→转膜→探针杂交→检测", "B. DNA酶切→电泳→变性→转膜→封闭→探针杂交→检测", "C. 固定细胞→变性→探针杂交→荧光成像", "D. PCR扩增→直接测序→比对"], "a": "B", "e": "Southern印迹检测DNA：先酶切和电泳分离，碱性变性后转膜，封闭后与标记探针杂交并检测。A为Northern印迹，C为FISH，D不是杂交检测流程。", "kp": "ch04_s2_5"}, {"id": "ch04_mcq_13", "mod": "模块三：分子杂交（探针·Southern/Northern·FISH）", "modI": 2, "q": "关于探针标记物与检测方式，下列配对错误的是：", "o": ["A. ³²P——X光胶片自显影", "B. 地高辛——抗DIG抗体结合酶促显色或化学发光", "C. 生物素——利用生物素与链霉亲和素的高亲和力检测", "D. Cy3——必须通过抗Cy3抗体酶促显色检测"], "a": "D", "e": "Cy3、Cy5、FAM等为荧光标记，可直接进行荧光检测，不需要抗体酶促显色；A、B、C的配对均正确。", "kp": "ch04_s2_3"}, {"id": "ch04_mcq_14", "mod": "模块三：分子杂交（探针·Southern/Northern·FISH）", "modI": 2, "q": "Northern blotting 与 Southern blotting 的主要区别是：", "o": ["A. Northern检测RNA，条带强度反映特定RNA的相对量", "B. Northern不需要电泳分离", "C. Northern不使用探针杂交", "D. Northern只能检测DNA突变"], "a": "A", "e": "Northern印迹与Southern流程类似，但分离和检测对象是RNA，杂交条带强度反映特定RNA的相对含量，用于基因转录活性分析；它仍需电泳、转膜和探针杂交。", "kp": "ch04_s2_10"}, {"id": "ch04_mcq_15", "mod": "模块三：分子杂交（探针·Southern/Northern·FISH）", "modI": 2, "q": "荧光原位杂交（FISH）的主要特点是：", "o": ["A. 必须先把DNA提取出来再电泳转膜", "B. 无需核酸提取，可在固定细胞中原位保留目标核酸的空间位置信息", "C. 只能用于检测RNA含量", "D. 探针不需要标记"], "a": "B", "e": "FISH对固定细胞中的DNA变性后直接与标记探针杂交并荧光成像，无需提取核酸，能保留目标序列在染色体或细胞核中的空间位置，常用于染色体定位和染色质三维组织研究。", "kp": "ch04_s2_11"}], "judge": [{"id": "ch04_judge_6", "modI": 2, "q": "Southern blotting以发明者Edwin Southern命名，用于检测RNA。", "a": "错", "e": "Southern blotting用于检测DNA；检测RNA的印迹杂交称为Northern blotting。", "kp": "ch04_s2_7"}, {"id": "ch04_judge_7", "modI": 2, "q": "FISH无需提取核酸，能在原位保留目标核酸的空间位置信息。", "a": "对", "e": "FISH用甲酰胺联合加热使固定细胞中双链DNA变性，加入标记探针杂交后荧光成像，无需提取核酸，特别适合DNA序列在染色体上的定位分析和染色质三维组织研究。", "kp": "ch04_s2_11"}], "fill": [{"id": "ch04_fill_7", "modI": 2, "q": "Southern印迹流程中，碱性溶液处理使DNA变性为________链，再将单链DNA从凝胶转移到________膜上。", "a": "单,硝酸纤维", "kp": "ch04_s2_6"}], "short": [{"id": "ch04_short_3", "modI": 2, "q": "简述Southern印迹杂交的操作流程，并说明变性、转膜、封闭和杂交各步骤的作用。", "a": "1. 流程：琼脂糖凝胶电泳分离DNA片段→碱性溶液处理使DNA变性为单链→将单链DNA从凝胶转移到硝酸纤维膜上（毛细扩散或电场转移）→用非特异性DNA或蛋白质封闭→加入标记探针孵育杂交→放射自显影或磷光成像检测阳性条带。2. 变性：使双链DNA解为单链，便于探针互补配对。3. 转膜：将凝胶中分离的DNA固定到固相膜上，便于后续杂交检测。4. 封闭：减少探针非特异性结合，降低背景。5. 杂交：标记探针与目标序列互补配对，只有含目标序列的片段才产生信号，保证特异性。", "kp": "ch04_s2_6"}], "calc": [], "term": [{"id": "ch04_term_10", "modI": 2, "term": "Southern Blot Hybridization", "def": "由Edwin Southern发明并以他命名的DNA印迹杂交技术；先电泳按大小分离DNA片段，再变性并转移到固相膜上，最后用标记探针杂交检测目标序列；把凝胶电泳的分辨能力与核酸杂交的特异性结合，用于基因组DNA、重组质粒和噬菌体DNA的特异性鉴定。", "kp": "ch04_s2_5"}, {"id": "ch04_term_11", "modI": 2, "term": "Northern Blotting", "def": "与Southern blotting类似但电泳分离对象为RNA的印迹杂交技术；转膜后与标记探针杂交检测特定RNA，条带强度反映该RNA的相对含量；用于RNA定性和定量分析、研究基因表达调控，是检测基因转录活性的经典方法。", "kp": "ch04_s2_10"}, {"id": "ch04_term_12", "modI": 2, "term": "Fluorescence in situ Hybridization (FISH)", "def": "荧光原位杂交；用甲酰胺联合加热使固定细胞中的双链DNA变性，加入标记DNA探针杂交，通过荧光成像直接观察探针在染色体上的位置；无需提取核酸，保留目标核酸的空间位置信息，适合DNA序列在染色体上的定位分析和染色质三维组织研究。", "kp": "ch04_s2_14"}]}, {"i": 3, "name": "模块四：PCR与衍生技术", "slides": [{"i": 0, "sec": "模块四：PCR与衍生技术", "title": "PCR的特点 (p41)", "notes": "PCR（聚合酶链式反应）是一种体外酶促合成特定DNA片段的技术，具有三大特点：特异性，通过引物设计选择性扩增目标DNA片段；高效扩增，能在短时间内将少量模板DNA扩增至数百万倍；快速便捷，整个反应通常在数小时内完成。这些特点使PCR成为分子生物学中最基础且应用最广泛的技术之一，为基因克隆、测序、诊断等提供了强有力的工具。", "page": 41, "level": "掌握", "img": "assets/img/ch04/p041.jpg", "anim": null, "fig": null, "points": ["特异性：引物设计选择性扩增目标DNA片段", "高效扩增：短时间内将少量模板DNA扩增至数百万倍", "快速便捷：整个反应通常数小时内完成", "PCR是分子生物学最基础、应用最广泛的技术之一"], "check": {"q": "关于PCR的特点，下列哪项描述是正确的？", "o": ["A. 通过引物设计选择性扩增目标DNA片段，具有特异性", "B. 只能将模板DNA扩增数十倍，效率较低", "C. 整个反应通常需要数天才能完成", "D. PCR只能用于基因测序，不能用于基因克隆"], "a": "A", "e": "PCR具有特异性（引物选择性扩增目标片段）、高效扩增（可扩增至数百万倍）和快速便捷（数小时内完成）三大特点，应用广泛。"}, "cards": [{"front": "PCR的三大特点是什么？", "back": "特异性、高效扩增、快速便捷。", "mnemonic": "特高快", "useImg": false}, {"front": "锚定PCR的原理是什么？克服了反向PCR的什么局限？", "back": "cDNA 3'端加poly(dG)尾作锚定序列，用poly(dC)锚定引物结合已知序列特异性引物扩增未知序列；克服了反向PCR对限制性酶切位点的依赖。", "mnemonic": "加尾锚定，不靠酶切", "useImg": false}]}, {"i": 1, "sec": "模块四：PCR与衍生技术", "title": "PCR原理 (p42)", "notes": "PCR的基本原理是在体外模拟DNA复制过程，利用热稳定DNA聚合酶（如Taq聚合酶）和高保真酶，在引物引导下，通过三种不同温度的循环（变性约95℃、退火约50℃、延伸约72℃）实现目标DNA片段的指数扩增。反应体系包括模板DNA、引物、dNTP、缓冲液和聚合酶。PCR可用于产生用于克隆的DNA片段或复制选定DNA区域，是分子克隆和基因分析的核心技术。", "page": 42, "level": "掌握", "img": "assets/img/ch04/p042.jpg", "anim": null, "fig": null, "points": ["体外模拟DNA复制，依赖热稳定DNA聚合酶（Taq酶/高保真酶）", "三温度循环：变性约95℃、退火约50℃、延伸约72℃", "反应体系：模板DNA、引物、dNTP、缓冲液、聚合酶", "产物呈指数扩增，用于克隆片段或复制选定区域"], "check": {"q": "PCR反应中，引物与模板互补序列结合（退火）的温度约为多少？", "o": ["A. 约95℃", "B. 约72℃", "C. 约50℃", "D. 约37℃"], "a": "C", "e": "PCR通过三种温度循环：变性约95℃、退火约50℃、延伸约72℃。"}, "cards": [{"front": "PCR的基本原理是什么？", "back": "体外模拟DNA复制，利用热稳定DNA聚合酶和引物，通过变性、退火、延伸三种温度循环实现目标DNA指数扩增。", "mnemonic": "变退延，指数翻", "useImg": false}, {"front": "原位PCR的特点和应用是什么？", "back": "在组织切片或细胞涂片上直接进行PCR扩增；结合PCR高灵敏度和原位杂交定位能力，可精确定位细胞中微量DNA/RNA。", "mnemonic": "原位扩增，定位检测", "useImg": false}]}, {"i": 2, "sec": "模块四：PCR与衍生技术", "title": "PCR循环示意图 (p43)", "notes": "该示意图展示了PCR的三个基本步骤：变性（Denaturation），高温（约95℃）使双链DNA氢键断裂，解链为单链模板；退火（Annealing），降温（约50-60℃）使引物与模板上的互补序列特异性结合；延伸（Extension），在72℃左右，热稳定DNA聚合酶从引物3'端开始，沿模板合成互补链。每个循环使目标DNA片段数量翻倍，经过25-35个循环可实现指数级扩增。", "page": 43, "level": "掌握", "img": "assets/img/ch04/p043.jpg", "anim": null, "fig": "按图从上到下看三个步骤：先高温解链（变性），再降温让引物结合（退火），最后升温由聚合酶延伸；箭头循环表示每轮产物翻倍。", "points": ["变性：约95℃使双链DNA氢键断裂成单链模板", "退火：降温约50-60℃使引物与模板互补序列特异性结合", "延伸：约72℃聚合酶从引物3'端沿模板合成互补链", "每循环目标片段翻倍，25-35个循环实现指数扩增"], "check": {"q": "在PCR循环的延伸步骤中，热稳定DNA聚合酶从引物的哪个末端开始合成互补链？", "o": ["A. 引物的5'端", "B. 引物的3'端", "C. 模板的5'端", "D. 模板的3'端"], "a": "B", "e": "延伸时热稳定DNA聚合酶从引物3'端开始，沿模板合成互补链，温度约72℃。"}, "cards": [{"front": "PCR反应体系包括哪些成分？", "back": "模板DNA、一对引物、dNTP、缓冲液、热稳定DNA聚合酶（如Taq）。", "mnemonic": "模引底缓酶", "useImg": false}, {"front": "不对称PCR的原理和用途是什么？", "back": "采用不等量引物（限制性引物浓度低），限制性引物耗尽后只有非限制性引物参与反应，产生大量单链DNA；用于制备测序模板和杂交探针。", "mnemonic": "一多一少，单链到手", "useImg": false}]}, {"i": 3, "sec": "模块四：PCR与衍生技术", "title": "PCR扩增曲线示意图 (p44)", "notes": "该图展示了PCR扩增过程中DNA产物量随循环数变化的曲线。初期为指数增长期，产物量呈指数增加；随后由于引物和dNTP消耗、聚合酶活性下降等因素，进入线性增长期；最后达到平台期，产物量不再显著增加。指数增长期是定量分析的关键阶段，实时荧光定量PCR正是利用此阶段荧光信号与起始模板量的线性关系进行定量。", "page": 44, "level": "理解", "img": "assets/img/ch04/p044.jpg", "anim": null, "fig": "横轴为循环数、纵轴为产物量（荧光信号）；曲线先陡峭上升（指数期），后变缓（线性期），最后走平（平台期），定量取指数期。", "points": ["扩增曲线分三期：指数增长期、线性增长期、平台期", "平台期成因：引物/dNTP消耗、聚合酶活性下降", "指数增长期是定量分析的关键阶段", "实时荧光定量PCR利用指数期荧光信号与起始模板量的线性关系定量"], "check": {"q": "实时荧光定量PCR进行定量分析时，利用的是扩增曲线的哪个阶段？", "o": ["A. 平台期", "B. 线性增长期", "C. 指数增长期", "D. 任何阶段均可"], "a": "C", "e": "指数增长期荧光信号与起始模板量存在线性关系，是定量分析的关键阶段。"}, "cards": [{"front": "PCR三个基本步骤及其温度是什么？", "back": "变性约95℃解链；退火约50-60℃引物结合；延伸约72℃聚合酶合成互补链。", "mnemonic": "95变、50退、72延", "useImg": false}]}, {"i": 4, "sec": "模块四：PCR与衍生技术", "title": "PCR工作流程 (p45)", "notes": "PCR工作流程包括：反应体系配制（模板DNA、一对引物、dNTP、Taq聚合酶、缓冲液）、设置热循环程序（预变性、变性、退火、延伸、终延伸）、循环扩增（通常25-35个循环）、产物检测（琼脂糖凝胶电泳）。每一步的温度和时间需根据引物Tm值、扩增片段长度等因素优化。PCR工作流程的标准化是实验成功的关键，也是后续衍生技术（如RT-PCR、qPCR）的基础。", "page": 45, "level": "掌握", "img": "assets/img/ch04/p045.jpg", "anim": null, "fig": "按图看PCR流程：反应体系配制→热循环（预变性→变性→退火→延伸→终延伸）→产物检测；注意图中温度与时间标注。", "points": [], "check": {"q": "PCR工作流程中，产物检测通常采用的方法是？", "o": ["A. 琼脂糖凝胶电泳", "B. 质谱分析", "C. 核磁共振", "D. 电子显微镜观察"], "a": "A", "e": "PCR工作流程包括体系配制、热循环程序设置、循环扩增和产物检测，产物检测通常用琼脂糖凝胶电泳。"}, "cards": [{"front": "PCR通常进行多少个循环？每个循环的效果是什么？", "back": "25-35个循环；每个循环使目标DNA片段数量翻倍，实现指数级扩增。", "mnemonic": "二十五到三十五，循环一次翻一倍", "useImg": false}]}, {"i": 5, "sec": "模块四：PCR与衍生技术", "title": "PCR类型 (p46)", "notes": "PCR技术衍生出多种类型以适应不同研究需求：逆转录PCR（RT-PCR）用于获取cDNA和检测基因表达水平；荧光定量PCR（qPCR）用于精确定量基因表达水平；反向PCR用于扩增已知序列两侧的未知序列；锚定PCR（单侧PCR）用于检测已知序列一侧的未知序列；原位PCR用于组织细胞中微量DNA/RNA的定位检测；不对称PCR用于制备单链DNA。这些衍生技术极大地拓展了PCR的应用范围。", "page": 46, "level": "掌握", "img": "assets/img/ch04/p046.jpg", "anim": null, "fig": null, "points": ["RT-PCR：获取cDNA、检测基因表达水平", "qPCR：精确定量基因表达水平", "反向PCR：扩增已知序列两侧的未知序列", "锚定PCR（单侧PCR）：检测已知序列一侧的未知序列", "原位PCR定位检测；不对称PCR制备单链DNA"], "check": {"q": "用于扩增已知序列两侧未知序列的PCR类型是？", "o": ["A. 逆转录PCR（RT-PCR）", "B. 反向PCR", "C. 原位PCR", "D. 不对称PCR"], "a": "B", "e": "反向PCR用于扩增已知序列两侧的未知序列；锚定PCR用于检测已知序列一侧的未知序列。"}, "cards": [{"front": "PCR扩增曲线分为哪几个阶段？", "back": "指数增长期、线性增长期、平台期。", "mnemonic": "指线平", "useImg": false}]}, {"i": 6, "sec": "模块四：PCR与衍生技术", "title": "RT-PCR原理 (p47)", "notes": "RT-PCR（逆转录PCR）是一种半定量检测基因mRNA表达水平的方法。其步骤包括：提取组织或细胞总RNA；以mRNA为模板，利用Oligo(dT)、随机引物或基因特异性引物，在逆转录酶作用下合成cDNA；再以cDNA为模板进行PCR扩增，获得目的基因或检测基因表达。RT-PCR将RNA信息转化为DNA信息，是研究基因转录水平的重要工具，广泛应用于基因表达分析、cDNA克隆等。", "page": 47, "level": "掌握", "img": "assets/img/ch04/p047.jpg", "anim": null, "fig": null, "points": ["RT-PCR为半定量检测基因mRNA表达水平的方法", "步骤：提取总RNA→逆转录合成cDNA→以cDNA为模板PCR扩增", "逆转录引物可用Oligo(dT)、随机引物或基因特异性引物", "将RNA信息转化为DNA信息，用于基因表达分析、cDNA克隆"], "check": {"q": "RT-PCR合成cDNA时，以什么为模板？", "o": ["A. 基因组DNA", "B. mRNA", "C. 质粒DNA", "D. 单链DNA"], "a": "B", "e": "RT-PCR以mRNA为模板，在逆转录酶作用下合成cDNA，再进行PCR扩增，用于检测基因表达水平。"}, "cards": [{"front": "PCR扩增曲线中哪个阶段是定量分析的关键？为什么？", "back": "指数增长期；此阶段荧光信号与起始模板量呈线性关系，是qPCR定量的基础。", "mnemonic": "指数期定量的黄金期", "useImg": false}]}, {"i": 7, "sec": "模块四：PCR与衍生技术", "title": "逆转录引物类型 (p48)", "notes": "RT-PCR中常用的逆转录引物有三种：①Oligo(dT)引物，识别mRNA的Poly(A)尾，优先逆转录带Poly(A)的真核mRNA，适合常规mRNA分析，不适用于无Poly(A)尾的RNA；②随机引物，在RNA多个位置启动逆转录，不依赖Poly(A)尾，适用于多种RNA及部分降解的RNA，但cDNA可能来自rRNA等非mRNA；③基因特异性引物，只逆转录目标RNA，目标性强但通量低。实际实验中常将Oligo(dT)与随机引物混合使用，兼顾选择性和覆盖度。", "page": 48, "level": "理解", "img": "assets/img/ch04/p048.jpg", "anim": null, "fig": null, "points": ["Oligo(dT)引物：识别mRNA Poly(A)尾，适合常规真核mRNA，不适用无Poly(A)尾RNA", "随机引物：多位点启动，不依赖Poly(A)尾，适用多种及部分降解RNA，但可能混入rRNA来源cDNA", "基因特异性引物：只逆转录目标RNA，目标性强但通量低", "实际实验需根据RNA类型和目的选择引物"], "check": {"q": "关于RT-PCR中逆转录引物的描述，下列哪项正确？", "o": ["A. Oligo(dT)引物识别mRNA的Poly(A)尾，适用于无Poly(A)尾的RNA", "B. 随机引物在RNA多个位置启动逆转录，适用于部分降解的RNA", "C. 基因特异性引物通量高，适合同时逆转录多种RNA", "D. 实际实验中常单独使用随机引物以保证选择性"], "a": "B", "e": "随机引物不依赖Poly(A)尾，可在RNA多个位置启动逆转录，适用于多种RNA及部分降解的RNA；Oligo(dT)不适用于无Poly(A)尾的RNA，基因特异性引物通量低，实际常将Oligo(dT)与随机引物混合使用。"}, "cards": [{"front": "PCR工作流程包括哪几个主要步骤？", "back": "反应体系配制、设置热循环程序、循环扩增、产物检测（琼脂糖凝胶电泳）。", "mnemonic": "配程扩检", "useImg": false}]}, {"i": 8, "sec": "模块四：PCR与衍生技术", "title": "内参基因的作用 (p49)", "notes": "在RT-PCR半定量分析中，需选择表达稳定的内参基因（如ACTIN）作为参照尺。通过比较内参基因和目标基因的扩增条带强度，可以校正样本间RNA上样量、逆转录效率等差异。若内参信号基本一致，而目标基因条带明显增强，则说明目标基因转录本增加。内参基因的选择是相对定量实验的关键，常用内参还包括GAPDH、β-actin、18S rRNA等，需根据实验条件验证其稳定性。", "page": 49, "level": "掌握", "img": "assets/img/ch04/p049.jpg", "anim": null, "fig": null, "points": ["内参基因（如ACTIN）作为参照尺，校正上样量、逆转录效率差异", "内参信号一致而目标条带增强，说明目标基因转录本增加", "常用内参：GAPDH、β-actin、18S rRNA", "内参需根据实验条件验证其表达稳定性"], "check": {"q": "在RT-PCR半定量分析中，内参基因的主要作用是？", "o": ["A. 直接扩增目标基因以提高灵敏度", "B. 作为荧光染料结合双链DNA", "C. 校正样本间RNA上样量、逆转录效率等差异", "D. 替代目标基因进行定量分析"], "a": "C", "e": "内参基因（如ACTIN）表达稳定，作为参照尺可校正样本间RNA上样量、逆转录效率等差异，从而判断目标基因转录本的变化。"}, "cards": [{"front": "PCR的主要衍生类型有哪些？", "back": "RT-PCR、qPCR、反向PCR、锚定PCR、原位PCR、不对称PCR。", "mnemonic": "逆转定，反锚原不对", "useImg": false}]}, {"i": 9, "sec": "模块四：PCR与衍生技术", "title": "实时荧光定量PCR (p50)", "notes": "实时荧光定量PCR（qPCR）在PCR反应体系中加入荧光基团，实时监测荧光信号累积，通过标准曲线对未知模板进行定量分析。常用荧光标记方法分两类：非特异检测，如SYBR Green I荧光染料，结合双链DNA小沟；扩增序列专一检测，如TaqMan探针和分子信标。qPCR具有高灵敏度、高特异性和宽动态范围，广泛应用于基因表达定量、病原体检测、SNP分析等领域。", "page": 50, "level": "掌握", "img": "assets/img/ch04/p050.jpg", "anim": null, "fig": null, "points": ["qPCR在反应体系中加入荧光基团，实时监测荧光累积", "通过标准曲线对未知模板定量", "非特异检测：SYBR Green I结合双链DNA小沟", "序列专一检测：TaqMan探针、分子信标", "特点：高灵敏度、高特异性、宽动态范围"], "check": {"q": "关于实时荧光定量PCR（qPCR）的荧光标记方法，下列哪项正确？", "o": ["A. SYBR Green I属于扩增序列专一检测", "B. TaqMan探针和分子信标属于非特异检测", "C. SYBR Green I结合双链DNA小沟，属于非特异检测", "D. qPCR只能用于基因表达定量，不能用于病原体检测"], "a": "C", "e": "SYBR Green I结合双链DNA小沟，为非特异检测；TaqMan探针和分子信标为扩增序列专一检测；qPCR广泛应用于基因表达定量、病原体检测、SNP分析等。"}, "cards": [{"front": "RT-PCR的原理和用途是什么？", "back": "以mRNA为模板逆转录合成cDNA，再PCR扩增；用于半定量检测基因mRNA表达水平、cDNA克隆。", "mnemonic": "RNA转DNA再扩增", "useImg": false}]}, {"i": 10, "sec": "模块四：PCR与衍生技术", "title": "分子信标结构示意图 (p51)", "notes": "分子信标（molecular beacon）是一种发夹型杂交探针，其两端分别标记荧光基团和淬灭基团。在游离状态下，探针形成发夹结构，荧光基团与淬灭基团靠近，荧光被淬灭；当探针与目标序列特异性杂交后，发夹结构打开，荧光基团与淬灭基团分离，发出荧光信号。分子信标具有高特异性，可用于实时定量PCR、SNP分析等，尤其适合区分单核苷酸变异。", "page": 51, "level": "理解", "img": "assets/img/ch04/p051.jpg", "anim": null, "fig": "看探针的两种状态：左侧游离时发夹闭合、荧光被淬灭不发光；右侧与靶序列杂交后发夹打开、荧光基团远离淬灭基团而发光。", "points": ["分子信标是发夹型杂交探针，两端标记荧光基团和淬灭基团", "游离状态发夹结构使荧光基团与淬灭基团靠近，荧光被淬灭", "与目标序列杂交后发夹打开，两基团分离发出荧光", "高特异性，适合区分单核苷酸变异（SNP分析）"], "check": {"q": "关于分子信标的结构与工作原理，下列哪项正确？", "o": ["A. 游离状态下发夹结构打开，发出荧光", "B. 与目标序列杂交后发夹结构打开，荧光基团与淬灭基团分离而发出荧光", "C. 分子信标两端均标记荧光基团", "D. 分子信标特异性低，不能区分单核苷酸变异"], "a": "B", "e": "分子信标游离时形成发夹结构，荧光基团与淬灭基团靠近而荧光被淬灭；与目标序列杂交后发夹打开，两基团分离，发出荧光信号，具有高特异性，适合区分单核苷酸变异。"}, "cards": [{"front": "RT-PCR中常用的逆转录引物有哪三种？", "back": "Oligo(dT)引物、随机引物、基因特异性引物。", "mnemonic": "寡随机特异", "useImg": false}]}, {"i": 11, "sec": "模块四：PCR与衍生技术", "title": "荧光化学试剂比较 (p52)", "notes": "表格比较了三种常用qPCR荧光检测试剂：SYBR Green I结合双链DNA小沟，无淬灭剂，可用于定量和检测目标基因，但特异性较低；分子信标为发夹型杂交探针，有淬灭剂，适用于SNP分析和定量检测；TaqMan为水解型杂交探针，有淬灭剂，适用于SNP分析和定量检测。TaqMan探针特异性高，但设计成本较高；SYBR Green I成本低但可能产生非特异性信号，需通过溶解曲线分析排除。", "page": 52, "level": "理解", "img": "assets/img/ch04/p052.jpg", "anim": null, "fig": null, "points": ["SYBR Green I：结合双链DNA小沟，无淬灭剂，特异性较低、成本低", "分子信标：发夹型杂交探针，有淬灭剂，用于SNP分析和定量", "TaqMan：水解型杂交探针，有淬灭剂，特异性高但设计成本较高", "SYBR Green I需溶解曲线分析排除非特异性信号"], "check": {"q": "关于三种常用qPCR荧光检测试剂的比较，下列哪项正确？", "o": ["A. SYBR Green I有淬灭剂，特异性高", "B. 分子信标为水解型杂交探针", "C. TaqMan为水解型杂交探针，有淬灭剂，特异性高", "D. SYBR Green I成本高但无非特异性信号"], "a": "C", "e": "TaqMan为水解型杂交探针，有淬灭剂，适用于SNP分析和定量检测，特异性高但设计成本较高；SYBR Green I无淬灭剂、成本低但特异性较低，需溶解曲线分析排除非特异性信号；分子信标为发夹型杂交探针。"}, "cards": [{"front": "Oligo(dT)引物的特点和适用对象是什么？", "back": "识别mRNA的Poly(A)尾，优先逆转录带Poly(A)的真核mRNA；不适用于无Poly(A)尾的RNA。", "mnemonic": "抓尾巴，只认PolyA", "useImg": false}]}, {"i": 12, "sec": "模块四：PCR与衍生技术", "title": "qPCR定量原理与Ct值 (p53)", "notes": "qPCR定量原理涉及基线（Baseline）和阈值（Threshold）的概念。基线是样本荧光背景值和阴性对照荧光值；阈值是高于背景波动且穿过扩增曲线指数增长阶段的位置。Ct值（循环阈值）定义为荧光信号达到设定阈值时所对应的循环数，即扩增曲线与阈值线的交点对应的循环次数。Ct值是qPCR定量的核心参数，与起始模板量的对数呈线性关系。", "page": 53, "level": "掌握", "img": "assets/img/ch04/p053.jpg", "anim": null, "fig": null, "points": ["基线：样本荧光背景值和阴性对照荧光值", "阈值：高于背景波动且穿过扩增曲线指数增长阶段的位置", "Ct值：荧光信号达到阈值所对应的循环数，即扩增曲线与阈值线交点", "Ct值是qPCR定量核心参数，与起始模板量对数呈线性关系"], "check": {"q": "关于qPCR中Ct值的定义，下列哪项正确？", "o": ["A. Ct值是样本荧光背景值", "B. Ct值是阴性对照的荧光值", "C. Ct值是荧光信号达到设定阈值时所对应的循环数", "D. Ct值与起始模板量的对数呈反比关系"], "a": "C", "e": "Ct值（循环阈值）定义为荧光信号达到设定阈值时所对应的循环数，即扩增曲线与阈值线的交点对应的循环次数，与起始模板量的对数呈线性关系。"}, "cards": [{"front": "RT-PCR中内参基因的作用是什么？常用内参有哪些？", "back": "作为参照尺校正样本间RNA上样量、逆转录效率等差异；常用ACTIN、GAPDH、β-actin、18S rRNA等。", "mnemonic": "内参当尺子，校正上样差", "useImg": false}]}, {"i": 13, "sec": "模块四：PCR与衍生技术", "title": "Ct值与起始拷贝数的关系 (p54)", "notes": "在PCR扩增的指数期，模板的Ct值与起始拷贝数存在线性关系：DNA量越多，荧光达到阈值的循环数越少，即Ct值越小；反之，DNA量越少，Ct值越大。通过已知浓度的标准品制作标准曲线，可根据未知样本的Ct值推算其起始模板量。这一原理是qPCR绝对定量的基础，也是相对定量（如2^-ΔΔCt法）的依据。Ct值的准确测定依赖于扩增效率的一致性和阈值设置的合理性。", "page": 54, "level": "掌握", "img": "assets/img/ch04/p054.jpg", "anim": null, "fig": null, "points": ["指数期Ct值与起始拷贝数呈线性关系", "DNA量越多，Ct值越小；DNA量越少，Ct值越大", "用已知浓度标准品制作标准曲线，由Ct值推算起始模板量", "是绝对定量基础，也是2^-ΔΔCt相对定量的依据", "Ct准确测定依赖扩增效率一致和阈值设置合理"], "check": {"q": "关于Ct值与起始拷贝数的关系，下列哪项正确？", "o": ["A. DNA量越多，Ct值越大", "B. DNA量越少，Ct值越小", "C. DNA量越多，荧光达到阈值的循环数越少，Ct值越小", "D. Ct值与起始拷贝数无关"], "a": "C", "e": "在指数期，模板DNA量越多，荧光达到阈值的循环数越少，Ct值越小；反之Ct值越大。通过标准曲线可由Ct值推算起始模板量，是绝对定量和相对定量的基础。"}, "cards": [{"front": "qPCR常用的荧光标记方法分哪两类？各举例？", "back": "非特异检测（如SYBR Green I染料）；扩增序列专一检测（如TaqMan探针、分子信标）。", "mnemonic": "非特异染料，特异用探针", "useImg": false}]}, {"i": 14, "sec": "模块四：PCR与衍生技术", "title": "引物溶解曲线分析 (p55)", "notes": "溶解曲线分析是qPCR中用于评估扩增特异性的重要步骤。PCR结束后，仪器逐渐升高温度，使双链DNA解链，SYBR Green荧光随之减弱。当温度达到产物Tm值时，荧光急剧下降，形成特征性溶解峰。单一峰表明扩增产物特异；若出现多个峰，则提示存在非特异性扩增或引物二聚体。溶解曲线分析是SYBR Green I法qPCR的必要质控步骤，可有效区分特异性产物和非特异性产物。", "page": 55, "level": "理解", "img": "assets/img/ch04/p055.jpg", "anim": null, "fig": null, "points": ["溶解曲线分析用于评估qPCR扩增特异性", "升温使双链DNA解链，SYBR Green荧光随之减弱", "达产物Tm时荧光急剧下降，形成特征性溶解峰", "单一峰示产物特异；多峰提示非特异性扩增或引物二聚体", "是SYBR Green I法qPCR的必要质控步骤"], "check": {"q": "在SYBR Green I法qPCR的溶解曲线分析中，若出现多个溶解峰，最可能提示什么？", "o": ["A. 扩增产物量过高", "B. 存在非特异性扩增或引物二聚体", "C. 模板DNA完全降解", "D. 荧光染料失效"], "a": "B", "e": "单一峰表示产物特异，多个峰提示非特异性扩增或引物二聚体。"}, "cards": [{"front": "分子信标的结构和工作原理是什么？", "back": "发夹型杂交探针，两端标记荧光基团和淬灭基团；游离时发夹闭合荧光淬灭，与目标杂交后发夹打开发出荧光。", "mnemonic": "闭合灭，打开亮", "useImg": false}]}, {"i": 15, "sec": "模块四：PCR与衍生技术", "title": "反向PCR (p56)", "notes": "反向PCR（inverse PCR）用于扩增已知序列两侧的未知序列。其原理是：用限制性内切酶消化目标DNA，使已知序列两侧的片段被切割，然后通过连接酶使DNA片段自身环化，再设计一对与已知序列两端反向互补的引物进行PCR扩增，从而获得两侧未知序列。反向PCR的局限性包括：要求在目标DNA区段有合适的限制性内切酶位点，且DNA分子自身环化效率较低。", "page": 56, "level": "理解", "img": "assets/img/ch04/p056.jpg", "anim": null, "fig": null, "points": ["反向PCR用于扩增已知序列两侧的未知序列", "原理：限制酶消化→连接酶使片段自身环化→用反向互补引物PCR", "局限性：需合适限制酶位点，自身环化效率较低"], "check": {"q": "反向PCR扩增已知序列两侧未知序列的关键步骤是？", "o": ["A. 用末端转移酶加poly(dG)尾", "B. 用限制性内切酶消化后连接酶使片段自身环化", "C. 采用不等量引物进行不对称扩增", "D. 在组织切片上原位扩增"], "a": "B", "e": "反向PCR通过酶切、自身环化，再用反向互补引物扩增两侧未知序列。"}, "cards": [{"front": "SYBR Green I、分子信标、TaqMan探针各有什么特点？", "back": "SYBR Green I结合双链DNA小沟，无淬灭剂，成本低但特异性较低；分子信标为发夹型探针，有淬灭剂，适合SNP分析；TaqMan为水解型探针，有淬灭剂，特异性高但设计成本较高。", "mnemonic": "SYBR便宜不特异，信标发夹，TaqMan水解高特异", "useImg": false}]}, {"i": 16, "sec": "模块四：PCR与衍生技术", "title": "锚定PCR (p57)", "notes": "锚定PCR（anchored PCR）用于检测已知靶基因片段一侧的未知序列。其原理是：mRNA逆转录合成cDNA后，利用末端转移酶在cDNA的3'端（未知序列端）加上poly(dG)尾作为锚定序列；然后使用与poly(dG)尾互补的poly(dC)锚定引物，结合已知序列特异性引物，引导合成未知DNA序列。锚定PCR克服了反向PCR对限制性酶切位点的依赖，适用于已知一侧序列、需扩增另一侧未知序列的情况。", "page": 57, "level": "理解", "img": "assets/img/ch04/p057.jpg", "anim": null, "fig": null, "points": ["锚定PCR用于检测已知靶基因片段一侧的未知序列", "mRNA逆转录成cDNA后用末端转移酶加poly(dG)尾作锚定序列", "用poly(dC)锚定引物结合已知序列特异性引物扩增未知序列", "克服反向PCR对限制酶切位点的依赖"], "check": {"q": "锚定PCR中，在cDNA的3'端加上poly(dG)尾所用的酶是？", "o": ["A. Taq聚合酶", "B. 逆转录酶", "C. 末端转移酶", "D. 连接酶"], "a": "C", "e": "锚定PCR利用末端转移酶在cDNA 3'端加poly(dG)尾作为锚定序列。"}, "cards": [{"front": "qPCR中基线（Baseline）和阈值（Threshold）分别指什么？", "back": "基线是样本荧光背景值和阴性对照荧光值；阈值是高于背景波动且穿过扩增曲线指数增长阶段的位置。", "mnemonic": "基线是背景，阈值穿指数", "useImg": false}]}, {"i": 17, "sec": "模块四：PCR与衍生技术", "title": "原位PCR (p58)", "notes": "原位PCR（in situ PCR）是在组织切片或细胞涂片上直接进行PCR扩增，以检测和定位细胞中微量DNA或RNA的技术。步骤包括：样品固定、预处理、DNA热变性、加入引物和Taq聚合酶、在原位聚合酶仪内扩增、固定PCR产物、信号检测。该技术结合了PCR的高灵敏度和原位杂交的定位能力，可精确定位组织细胞中的微量核酸，广泛应用于病理学、病毒检测和基因表达定位研究。", "page": 58, "level": "理解", "img": "assets/img/ch04/p058.jpg", "anim": null, "fig": null, "points": ["原位PCR在组织切片或细胞涂片上直接进行PCR扩增", "可检测并定位细胞中微量DNA或RNA", "步骤：固定、预处理、热变性、加引物和Taq酶、原位扩增、固定产物、信号检测", "结合PCR高灵敏度与原位杂交定位能力，用于病理学、病毒检测、基因表达定位"], "check": {"q": "原位PCR最突出的技术特点是？", "o": ["A. 只能检测RNA", "B. 结合PCR高灵敏度与原位杂交的定位能力", "C. 不需要引物", "D. 只能在液体样本中进行"], "a": "B", "e": "原位PCR在切片或涂片上直接扩增，兼具高灵敏度和定位能力。"}, "cards": [{"front": "Ct值（循环阈值）的定义是什么？", "back": "荧光信号达到设定阈值时所对应的循环数，即扩增曲线与阈值线的交点对应的循环次数。", "mnemonic": "Ct就是到阈值时的循环数", "useImg": false}]}, {"i": 18, "sec": "模块四：PCR与衍生技术", "title": "不对称PCR (p59)", "notes": "不对称PCR（asymmetric PCR）采用不等量的一对引物，其中限制性引物浓度较低（约0.01 μM），非限制性引物浓度较高（约0.5 μM），最佳比例约为0.01∶0.5。在若干循环后，限制性引物先消耗完，后续循环中只有非限制性引物参与反应，从而产生大量单链DNA。不对称PCR主要用于制备核酸序列测定的模板和杂交探针。限制性引物的绝对量是实验成功的关键，比例需优化以获得高质量单链产物。", "page": 59, "level": "理解", "img": "assets/img/ch04/p059.jpg", "anim": null, "fig": null, "points": ["不对称PCR采用不等量引物：限制性引物约0.01 μM、非限制性引物约0.5 μM（最佳比例约0.01∶0.5）", "限制性引物耗尽后，后续循环只扩增单链DNA", "主要用于制备测序模板和杂交探针", "限制性引物绝对量是成功关键，比例需优化"], "check": {"q": "不对称PCR中，限制性引物与非限制性引物的常用浓度配比是？", "o": ["A. 限制性引物 0.01 μM，非限制性引物 0.5 μM", "B. 限制性引物 0.5 μM，非限制性引物 0.01 μM", "C. 两者均为 5–10 μM", "D. 两者均为 0.01–0.5 μM"], "a": "A", "e": "PPT给出的最佳比例一般为0.01∶0.5 μM，即限制性引物约0.01 μM、非限制性引物约0.5 μM；限制性引物先耗尽后产生大量单链DNA。"}, "cards": [{"front": "Ct值与起始模板量的关系是什么？", "back": "线性关系：DNA量越多，Ct值越小；DNA量越少，Ct值越大。", "mnemonic": "模板多，Ct小；模板少，Ct大", "useImg": false}]}, {"i": 19, "sec": "模块四：PCR与衍生技术", "title": "PCR的应用 (p60)", "notes": "PCR技术具有广泛的实际应用，几乎涵盖分子生物学所有领域：用于DNA克隆扩增、无需克隆的DNA测序、DNA测序反应；基因和调控序列定位、连锁分析（鉴定性状/疾病相关基因）；疾病诊断、病原体筛查、性别鉴定、法医分析、亲子鉴定；行为生态学研究、分子系统学与进化分析（比较不同生物同源序列）、群体遗传学、生理遗传学等。PCR的简便性、高效性和通用性使其成为现代分子生物学不可或缺的工具。", "page": 60, "level": "了解", "img": "assets/img/ch04/p060.jpg", "anim": null, "fig": null, "points": ["DNA克隆扩增、无需克隆的DNA测序", "基因与调控序列定位、连锁分析（鉴定性状/疾病相关基因）", "疾病诊断、病原体筛查、性别鉴定、法医分析、亲子鉴定", "分子系统学与进化分析、群体遗传学、行为生态学等"], "check": {"q": "下列哪项不属于讲义中列出的PCR应用？", "o": ["A. 法医分析与亲子鉴定", "B. 分子系统学与进化分析", "C. 连锁分析鉴定疾病相关基因", "D. 直接测定蛋白质三维结构"], "a": "D", "e": "讲义列举的是DNA克隆、测序、诊断、法医、进化分析等，未涉及蛋白质三维结构测定。"}, "cards": [{"front": "溶解曲线分析的作用和判断标准是什么？", "back": "评估qPCR扩增特异性；单一峰表明产物特异，多个峰提示非特异性扩增或引物二聚体。", "mnemonic": "单峰特异，多峰不纯", "useImg": false}]}, {"i": 20, "sec": "模块四：PCR与衍生技术", "title": "实时定量PCR的应用 (p61)", "notes": "实时定量PCR（qPCR）的应用十分广泛，包括：基因表达水平的精确分析（相对定量和绝对定量）、病原体（病毒、细菌）的快速检测和载量测定、SNP基因分型、转基因成分检测、microRNA表达分析、拷贝数变异分析等。qPCR的高灵敏度和宽动态范围使其成为临床诊断和基础研究的重要工具。随着数字PCR等新技术的发展，qPCR在精准医疗和分子诊断中持续发挥核心作用。", "page": 61, "level": "理解", "img": "assets/img/ch04/p061.jpg", "anim": null, "fig": "按图看qPCR应用分类：基因表达定量、病原体检测、SNP分型、转基因/拷贝数检测等；抓每类对应的检测目标。", "points": [], "check": {"q": "下列哪项属于实时定量PCR（qPCR）的典型应用？", "o": ["A. 蛋白质三维结构解析", "B. SNP基因分型与转基因成分检测", "C. 细胞切片原位定位", "D. 限制性内切酶位点作图"], "a": "B", "e": "qPCR应用于基因表达分析、病原体检测、SNP分型、转基因检测、拷贝数变异等。"}, "cards": [{"front": "反向PCR的原理和局限性是什么？", "back": "用限制性内切酶消化DNA后自身环化，用反向互补引物扩增已知序列两侧未知序列；局限：需合适酶切位点、环化效率较低。", "mnemonic": "切-环-反扩", "useImg": false}]}], "mcq": [{"id": "ch04_mcq_16", "mod": "模块四：PCR与衍生技术", "modI": 3, "q": "PCR反应中使用的热稳定DNA聚合酶最常用的是：", "o": ["A. DNA聚合酶I", "B. Taq聚合酶", "C. 逆转录酶", "D. RNA聚合酶"], "a": "B", "e": "Taq聚合酶是从嗜热菌Thermus aquaticus中分离的热稳定DNA聚合酶，能在高温（约72℃）下保持活性，是PCR反应中最常用的聚合酶。", "kp": "ch04_s3_1"}, {"id": "ch04_mcq_17", "mod": "模块四：PCR与衍生技术", "modI": 3, "q": "在实时荧光定量PCR中，Ct值的定义是：", "o": ["A. 荧光信号达到最大值时的循环数", "B. 荧光信号达到设定阈值时所对应的循环数", "C. PCR反应结束时的总循环数", "D. 模板DNA开始扩增时的循环数"], "a": "B", "e": "Ct值（循环阈值）是指荧光信号达到预先设定的荧光阈值时所对应的循环数，与起始模板量的对数呈线性关系，是qPCR定量的核心参数。", "kp": "ch04_s3_9"}, {"id": "ch04_mcq_18", "mod": "模块四：PCR与衍生技术", "modI": 3, "q": "下列哪种PCR技术用于扩增已知序列两侧的未知序列？", "o": ["A. RT-PCR", "B. 原位PCR", "C. 反向PCR", "D. 不对称PCR"], "a": "C", "e": "反向PCR通过限制性内切酶消化和自身环化，使已知序列两侧的未知序列被扩增，适用于获取已知序列侧翼的未知区域。", "kp": "ch04_s3_5"}, {"id": "ch04_mcq_19", "mod": "模块四：PCR与衍生技术", "modI": 3, "q": "在RT-PCR中，Oligo(dT)引物的作用是：", "o": ["A. 随机结合所有RNA", "B. 特异性识别mRNA的Poly(A)尾", "C. 只逆转录目标基因", "D. 结合rRNA"], "a": "B", "e": "Oligo(dT)引物专门识别mRNA的Poly(A)尾，优先逆转录带Poly(A)尾的真核mRNA，适合常规mRNA分析，不适用于无Poly(A)尾的RNA。", "kp": "ch04_s3_6"}, {"id": "ch04_mcq_20", "mod": "模块四：PCR与衍生技术", "modI": 3, "q": "不对称PCR的主要用途是：", "o": ["A. 定量分析基因表达", "B. 制备单链DNA用于测序或杂交探针", "C. 检测组织细胞中微量DNA", "D. 扩增未知序列"], "a": "B", "e": "不对称PCR采用不等量引物，限制性引物消耗完后，非限制性引物继续引导合成大量单链DNA，主要用于制备核酸测序模板和杂交探针。", "kp": "ch04_s3_18"}], "judge": [{"id": "ch04_judge_8", "modI": 3, "q": "PCR的退火温度通常约为95℃，延伸温度约为72℃。", "a": "错", "e": "PCR变性温度约95℃，退火温度约50-60℃，延伸温度约72℃。", "kp": "ch04_s3_1"}, {"id": "ch04_judge_9", "modI": 3, "q": "RT-PCR中Oligo(dT)引物识别mRNA的Poly(A)尾，适合常规mRNA分析，但不适用于无Poly(A)尾的RNA。", "a": "对", "e": "Oligo(dT)引物识别mRNA的Poly(A)尾，优先逆转录带Poly(A)的真核mRNA，适合常规mRNA分析，不适用于无Poly(A)尾的RNA；随机引物不依赖Poly(A)尾，适用范围更广。", "kp": "ch04_s3_7"}, {"id": "ch04_judge_10", "modI": 3, "q": "分子信标在游离状态下荧光基团与淬灭基团靠近，荧光被淬灭；与目标序列杂交后发夹结构打开，发出荧光信号。", "a": "对", "e": "分子信标是发夹型杂交探针，两端分别标记荧光基团和淬灭基团；游离时形成发夹结构使荧光淬灭，与目标序列特异性杂交后发夹打开、荧光基团与淬灭基团分离而发出荧光，具有高特异性，适合区分单核苷酸变异。", "kp": "ch04_s3_10"}], "fill": [{"id": "ch04_fill_8", "modI": 3, "q": "PCR每个循环包括三个基本步骤：变性（约________℃）、退火（约50-60℃）、延伸（约________℃）。", "a": "95,72", "kp": "ch04_s3_2"}, {"id": "ch04_fill_9", "modI": 3, "q": "RT-PCR中，Oligo(dT)引物识别mRNA的________尾，优先逆转录带Poly(A)的真核mRNA；随机引物不依赖Poly(A)尾，适用于多种RNA及部分降解的RNA。", "a": "Poly(A)", "kp": "ch04_s3_7"}, {"id": "ch04_fill_10", "modI": 3, "q": "qPCR中，SYBR Green I荧光染料结合双链DNA________，属于非特异检测；TaqMan探针和分子信标属于扩增序列________检测。", "a": "小沟,专一", "kp": "ch04_s3_9"}], "short": [{"id": "ch04_short_4", "modI": 3, "q": "简述RT-PCR的原理和基本步骤，并说明内参基因在半定量分析中的作用。", "a": "1. 原理：将RNA信息转化为DNA信息，以mRNA为模板在逆转录酶作用下合成cDNA，再以cDNA为模板进行PCR扩增，半定量检测基因mRNA表达水平。2. 步骤：提取组织或细胞总RNA→以Oligo(dT)、随机引物或基因特异性引物逆转录合成cDNA→以cDNA为模板PCR扩增→凝胶电泳检测。3. 内参基因作用：选择表达稳定的内参基因（如ACTIN、GAPDH、β-actin、18S rRNA）作为参照尺，校正样本间RNA上样量、逆转录效率等差异；若内参信号基本一致而目标基因条带明显增强，则说明目标基因转录本增加。4. 内参基因需根据实验条件验证其稳定性。", "kp": "ch04_s3_8"}, {"id": "ch04_short_5", "modI": 3, "q": "简述实时荧光定量PCR（qPCR）的原理及两类常用荧光标记方法。", "a": "1. 原理：在PCR反应体系中加入荧光基团，实时监测荧光信号累积，通过标准曲线对未知模板进行定量分析；利用指数增长期荧光信号与起始模板量的线性关系进行定量。2. 非特异检测：如SYBR Green I荧光染料，结合双链DNA小沟，只有结合双链DNA时才发出荧光。3. 扩增序列专一检测：如TaqMan探针和分子信标，探针与目标序列特异性杂交后产生荧光信号。4. 特点：高灵敏度、高特异性和宽动态范围，广泛应用于基因表达定量、病原体检测、SNP分析等领域。", "kp": "ch04_s3_9"}], "calc": [], "term": []}, {"i": 4, "name": "模块五：基因克隆（酶·载体·文库·筛选）", "slides": [{"i": 0, "sec": "模块五：基因克隆", "title": "基因克隆的同义词 (p62)", "notes": "基因克隆在文献中常被称为DNA克隆、重组DNA技术、分子克隆或基因工程，这些术语基本同义。需要强调的是，基因只是基因组序列中的一部分，因此基因克隆通常指从复杂基因组中分离并扩增特定DNA片段的过程，是分子生物学最基础、最核心的技术之一。", "page": 62, "level": "掌握", "img": "assets/img/ch04/p062.jpg", "anim": null, "fig": null, "points": ["基因克隆的同义术语：DNA克隆、重组DNA技术、分子克隆、基因工程", "基因克隆指从复杂基因组中分离并扩增特定DNA片段", "基因克隆是分子生物学最基础、最核心的技术之一"], "check": {"q": "基因克隆在文献中常被称为什么？", "o": ["A. DNA克隆、重组DNA技术、分子克隆或基因工程", "B. 蛋白质克隆、细胞克隆、组织工程或发酵工程", "C. 基因敲除、基因编辑、RNA干扰或基因沉默", "D. 蛋白质纯化、色谱分析、电泳分离或质谱鉴定"], "a": "A", "e": "基因克隆常被称为DNA克隆、重组DNA技术、分子克隆或基因工程，这些术语基本同义。"}, "cards": [{"front": "基因克隆在文献中有哪些同义术语？", "back": "DNA克隆、重组DNA技术、分子克隆、基因工程", "mnemonic": "克隆四兄弟：DNA、重组、分子、工程", "useImg": false}, {"front": "菌落杂交筛选文库的过程是什么？", "back": "菌落转移到膜上→裂解细胞固定DNA→与标记探针杂交→放射自显影或显色检测阳性克隆（噬菌体文库则筛噬菌斑）", "mnemonic": "转膜、裂解、杂交、显影", "useImg": false}]}, {"i": 1, "sec": "模块五：基因克隆", "title": "基因克隆的定义 (p63)", "notes": "基因克隆是指将外源目的基因或DNA片段与适宜的载体连接形成重组DNA分子，再导入细菌或噬菌体等宿主细胞中，随宿主繁殖而大量扩增，从而获得大量纯化的目的基因。其本质是“体外重组、体内扩增”，是分离、保存和研究特定基因的基础手段。", "page": 63, "level": "掌握", "img": "assets/img/ch04/p063.jpg", "anim": null, "fig": null, "points": ["基因克隆定义：外源目的基因/ DNA片段与适宜载体连接形成重组DNA分子", "导入细菌或噬菌体等宿主细胞随宿主繁殖大量扩增", "本质是“体外重组、体内扩增”", "是分离、保存和研究特定基因的基础手段"], "check": {"q": "基因克隆的本质可概括为？", "o": ["A. 体外重组、体内扩增", "B. 体内重组、体外扩增", "C. 体外转录、体内翻译", "D. 体内切割、体外连接"], "a": "A", "e": "基因克隆是将目的DNA与载体连接形成重组DNA并导入宿主扩增，本质是“体外重组、体内扩增”。"}, "cards": [{"front": "基因克隆的本质是什么？", "back": "从复杂基因组中分离并扩增特定DNA片段的过程", "mnemonic": "大海捞针再复制", "useImg": false}]}, {"i": 2, "sec": "模块五：基因克隆", "title": "DNA克隆的基本流程 (p64)", "notes": "DNA克隆主要包括五个步骤：用限制酶和连接酶将目的DNA片段插入载体形成重组DNA；将重组DNA转入感受态细胞；繁殖含重组DNA的细胞形成克隆；利用选择标记筛选所需克隆。该流程体现了“切、接、转、增、筛”的核心思路，是后续所有克隆实验的框架。", "page": 64, "level": "掌握", "img": "assets/img/ch04/p064.jpg", "anim": null, "fig": null, "points": ["DNA克隆五步骤：限制酶切割与连接酶连接形成重组DNA", "转化感受态细胞", "繁殖形成克隆", "利用选择标记筛选所需克隆", "核心思路概括为“切、接、转、增、筛”"], "check": {"q": "DNA克隆的基本流程体现了“切、接、转、增、筛”的核心思路，其中“转”指的是？", "o": ["A. 将重组DNA转入感受态细胞", "B. 用限制酶切割DNA", "C. 用连接酶连接DNA片段", "D. 利用选择标记筛选克隆"], "a": "A", "e": "“转”指将重组DNA转入感受态细胞；“切”为酶切，“接”为连接，“增”为繁殖扩增，“筛”为筛选。"}, "cards": [{"front": "基因克隆的定义是什么？", "back": "外源目的基因与载体连接成重组DNA，导入宿主细胞随繁殖大量扩增，获得大量纯化目的基因", "mnemonic": "体外重组、体内扩增", "useImg": false}]}, {"i": 3, "sec": "模块五：基因克隆", "title": "DNA克隆的分子工具 (p65)", "notes": "DNA克隆需要三大类分子工具：限制性内切酶用于切割DNA；克隆载体用于携带外源DNA并使其在宿主中保存和操作；宿主细胞（如大肠杆菌）为载体提供复制和扩增的环境，保证重组DNA被忠实复制和传递。三者缺一不可，共同构成基因克隆的技术基础。", "page": 65, "level": "掌握", "img": "assets/img/ch04/p065.jpg", "anim": null, "fig": null, "points": ["三大分子工具：限制性内切酶、克隆载体、宿主细胞", "限制酶负责切割DNA", "载体携带外源DNA并在宿主中保存和操作", "宿主细胞（如大肠杆菌）提供复制扩增环境", "三者缺一不可，共同构成基因克隆技术基础"], "check": {"q": "DNA克隆需要的三大类分子工具是？", "o": ["A. 限制性内切酶、克隆载体、宿主细胞", "B. DNA聚合酶、RNA聚合酶、连接酶", "C. 质粒、噬菌体、病毒", "D. 感受态细胞、培养基、抗生素"], "a": "A", "e": "DNA克隆需要限制性内切酶（切割DNA）、克隆载体（携带外源DNA）和宿主细胞（提供复制扩增环境）三大类工具。"}, "cards": [{"front": "DNA克隆的基本流程有哪五步？", "back": "切（限制酶切割）、接（连接酶连接）、转（转化感受态细胞）、增（繁殖形成克隆）、筛（选择标记筛选）", "mnemonic": "切接转增筛", "useImg": false}]}, {"i": 4, "sec": "模块五：基因克隆", "title": "限制性内切酶的作用 (p66)", "notes": "限制性内切酶被称为“DNA分子手术刀”，能识别DNA上特定的短序列并在特定位点切割双链DNA，从而将大分子DNA切成可操作的片段。不同酶识别序列不同，目前已有数百种限制酶，每种都有其特异的识别序列，为基因克隆提供了精确切割DNA的工具。", "page": 66, "level": "掌握", "img": "assets/img/ch04/p066.jpg", "anim": null, "fig": null, "points": ["限制性内切酶被称为“DNA分子手术刀”", "识别DNA特定短序列并在特定位点切割双链DNA", "不同酶识别序列不同，已有数百种限制酶", "为基因克隆提供精确切割DNA的工具"], "check": {"q": "限制性内切酶被称为“DNA分子手术刀”，其作用是？", "o": ["A. 识别DNA特定短序列并在特定位点切割双链DNA", "B. 将DNA片段连接形成重组DNA分子", "C. 以DNA为模板合成RNA", "D. 将DNA水解为单个核苷酸"], "a": "A", "e": "限制性内切酶能识别DNA上特定短序列并在特定位点切割双链DNA，将大分子DNA切成可操作片段。"}, "cards": [{"front": "DNA克隆需要哪三大类分子工具？", "back": "限制性内切酶（切割DNA）、克隆载体（携带外源DNA）、宿主细胞（提供复制扩增环境）", "mnemonic": "刀、车、厂", "useImg": false}]}, {"i": 5, "sec": "模块五：基因克隆", "title": "限制酶产生的末端类型 (p67)", "notes": "限制酶切割DNA后可产生两类末端：平末端（blunt ends）和粘性末端（sticky ends）。粘性末端具有单链突出，便于通过互补配对与载体连接，是克隆中最常用的末端类型；平末端连接效率较低，但可通过末端修饰后使用。末端类型直接影响后续连接策略的选择。", "page": 67, "level": "掌握", "img": "assets/img/ch04/p067.jpg", "anim": null, "fig": null, "points": ["限制酶切割产生两类末端：平末端和粘性末端", "粘性末端有单链突出，便于互补配对连接，是克隆中最常用类型", "平末端连接效率较低，可经末端修饰后使用", "末端类型直接影响后续连接策略选择"], "check": {"q": "关于限制酶产生的末端类型，下列说法正确的是？", "o": ["A. 粘性末端具有单链突出，便于通过互补配对与载体连接，是克隆中最常用的末端类型", "B. 平末端具有单链突出，连接效率最高", "C. 粘性末端连接效率低于平末端，故克隆中较少使用", "D. 限制酶切割DNA只能产生平末端"], "a": "A", "e": "粘性末端具有单链突出，便于互补配对连接，是克隆中最常用的末端类型；平末端连接效率较低。"}, "cards": [{"front": "限制性内切酶被称为什么？其作用是什么？", "back": "被称为DNA分子手术刀；识别特定短序列并在特定位点切割双链DNA", "mnemonic": "分子手术刀，精准切割", "useImg": false}]}, {"i": 6, "sec": "模块五：基因克隆", "title": "限制酶之间的差异 (p68)", "notes": "不同限制酶在四方面存在差异：识别位点的序列特异性不同；识别序列长度不同，导致切割频率不同；产生的末端类型不同（平末端或粘性末端）；切割活性也有差异。这些差异决定了实验中限制酶的选择依据，例如需要高频切割还是低频切割、是否需要粘性末端等。", "page": 68, "level": "理解", "img": "assets/img/ch04/p068.jpg", "anim": null, "fig": null, "points": ["限制酶差异体现在四方面：识别位点序列特异性", "识别序列长度不同导致切割频率不同", "产生的末端类型不同（平末端或粘性末端）", "切割活性存在差异", "这些差异是实验中限制酶选择的依据"], "check": {"q": "不同限制酶之间的差异不包括下列哪一项？", "o": ["A. 识别位点的序列特异性不同", "B. 识别序列长度不同，导致切割频率不同", "C. 产生的末端类型不同（平末端或粘性末端）", "D. 催化DNA连接反应的效率不同"], "a": "D", "e": "限制酶差异体现在识别位点特异性、识别序列长度、末端类型和切割活性四方面，不涉及催化DNA连接反应。"}, "cards": [{"front": "限制酶切割DNA产生哪两类末端？", "back": "平末端（blunt ends）和粘性末端（sticky ends）", "mnemonic": "平粘两端", "useImg": false}]}, {"i": 7, "sec": "模块五：基因克隆", "title": "识别序列长度与切割频率 (p69)", "notes": "限制酶识别序列越长，在基因组中出现的频率越低。4 bp序列约每256 bp出现一次，6 bp约每4096 bp一次，8 bp约每65 kb一次，14 bp识别序列的理论频率约每2.68亿bp一次；宏核酸酶识别14–40 bp，频率随长度增加而更低。以上均为按识别序列长度估算的理论频率，例如人类基因组约3.1 Gb时，EcoRI约每4 kb、NotI约每65 kb出现一次。", "page": 69, "level": "掌握", "img": "assets/img/ch04/p069.jpg", "anim": null, "fig": null, "points": ["识别序列越长，在基因组中出现频率越低", "4 bp约每256 bp一次，6 bp约每4096 bp一次，8 bp约每65 kb一次", "14 bp理论频率约每2.68亿bp一次；宏核酸酶识别14–40 bp", "可据此估算酶在基因组中的切割频率", "人类基因组约3.1 Gb，EcoRI约每4 kb、NotI约每65 kb出现一次（理论估算）"], "check": {"q": "关于限制酶识别序列长度与切割频率的关系，下列叙述正确的是？", "o": ["A. 识别序列越长，在基因组中出现的频率越高", "B. 4 bp识别序列约每4096 bp出现一次", "C. 识别序列越长，在基因组中出现的频率越低", "D. 8 bp识别序列约每256 bp出现一次"], "a": "C", "e": "识别序列越长，其在基因组中出现的概率越低；4 bp约每256 bp一次，6 bp约每4096 bp一次，8 bp约每65 kb一次。"}, "cards": [{"front": "哪类末端更便于与载体连接？为什么？", "back": "粘性末端；具有单链突出，可通过互补配对连接，是克隆中最常用的类型", "mnemonic": "粘性互补好连接", "useImg": false}]}, {"i": 8, "sec": "模块五：基因克隆", "title": "载体的定义与基本特征 (p70)", "notes": "载体是基因克隆中携带外源DNA的DNA分子，多为质粒或噬菌体DNA。其基本特征包括：含复制起点（ori），能独立于宿主基因组自主复制；易于从宿主细胞中分离纯化；含至少一个筛选标记，便于筛选含载体的宿主细胞；含多克隆位点（MCS），供限制酶切割以插入外源DNA。多数载体为环状，少数为线状（如YAC）。", "page": 70, "level": "掌握", "img": "assets/img/ch04/p070.jpg", "anim": null, "fig": null, "points": ["载体是携带外源DNA的DNA分子，多为质粒或噬菌体DNA", "基本特征：含复制起点（ori）能自主复制", "易于从宿主细胞分离纯化", "含至少一个筛选标记和供插入外源DNA的多克隆位点（MCS）", "多数载体为环状，少数为线状（如YAC）"], "check": {"q": "下列哪项不属于基因克隆载体应具备的基本特征？", "o": ["A. 含复制起点，能自主复制", "B. 含至少一个筛选标记", "C. 含多克隆位点供外源DNA插入", "D. 必须含有完整的lacZ'基因用于蓝白斑筛选"], "a": "D", "e": "载体的基本特征包括ori、易分离纯化、筛选标记和MCS；lacZ'只是pUC等特定载体的筛选系统，并非所有载体的必备特征。"}, "cards": [{"front": "不同限制酶在哪些方面存在差异？", "back": "识别位点序列特异性、识别序列长度（切割频率）、末端类型（平/粘）、切割活性", "mnemonic": "序列、长度、末端、活性", "useImg": false}]}, {"i": 9, "sec": "模块五：基因克隆", "title": "常见载体类型及用途 (p71)", "notes": "载体按用途可分为三类：克隆载体用于保存和扩增DNA，代表为pUC18；原核表达载体用于在细菌中表达蛋白，代表为pET-28a、pGEX-4T-1；真核表达载体用于在真核细胞中表达基因，代表为pcDNA3.1、pCAMBIA系列。选择载体需根据实验目的决定，是克隆实验设计的重要环节。", "page": 71, "level": "理解", "img": "assets/img/ch04/p071.jpg", "anim": null, "fig": null, "points": ["载体按用途分三类：克隆载体（代表pUC18）用于保存扩增DNA", "原核表达载体（代表pET-28a、pGEX-4T-1）用于细菌中表达蛋白", "真核表达载体（代表pcDNA3.1、pCAMBIA系列）用于真核细胞表达", "选择载体需根据实验目的决定"], "check": {"q": "若实验目的是在细菌中表达目的蛋白，应优先选择下列哪类载体？", "o": ["A. 克隆载体pUC18", "B. 原核表达载体pET-28a", "C. 真核表达载体pcDNA3.1", "D. 真核表达载体pCAMBIA系列"], "a": "B", "e": "pET-28a、pGEX-4T-1属于原核表达载体，用于在细菌中表达蛋白；pUC18为克隆载体，pcDNA3.1、pCAMBIA为真核表达载体。"}, "cards": [{"front": "限制酶识别序列长度与切割频率的关系？", "back": "识别序列越长，基因组中出现频率越低。4bp约每256bp一次，6bp约每4096bp一次，8bp约每65kb一次", "mnemonic": "越长越稀，4-256、6-4096、8-65k", "useImg": false}]}, {"i": 10, "sec": "模块五：基因克隆", "title": "pUC质粒系列与蓝白斑筛选 (p72)", "notes": "pUC18、pUC19是最常用的克隆载体，其多克隆位点位于lacZ'基因（β-半乳糖苷酶部分基因）内部。外源DNA插入MCS会中断lacZ'基因（通常破坏其阅读框），使β-半乳糖苷酶失活，从而无法水解底物X-gal产生蓝色产物，形成白色菌落。这一蓝/白斑筛选系统为重组克隆的筛选提供了简便直观的方法。", "page": 72, "level": "掌握", "img": "assets/img/ch04/p072.jpg", "anim": null, "fig": null, "points": ["pUC18、pUC19是最常用克隆载体", "多克隆位点位于lacZ'基因（β-半乳糖苷酶部分基因）内部", "外源DNA插入MCS通常中断lacZ'基因/阅读框，β-半乳糖苷酶失活", "无法水解X-gal产生蓝色产物，形成白色菌落", "蓝/白斑筛选为重组克隆筛选提供简便直观方法"], "check": {"q": "pUC18/pUC19蓝白斑筛选的原理是？", "o": ["A. 外源DNA插入MCS破坏lacZ'阅读框，β-半乳糖苷酶失活，菌落呈白色", "B. 外源DNA插入MCS增强lacZ'表达，菌落呈蓝色", "C. 外源DNA插入抗性基因使其失活，菌落无法生长", "D. 外源DNA插入ori使质粒不能复制，菌落呈白色"], "a": "A", "e": "pUC载体的MCS位于lacZ'内部，插入外源DNA通常中断lacZ'基因/阅读框，β-半乳糖苷酶失活，不能水解X-gal，形成白色菌落。"}, "cards": [{"front": "载体的定义与基本特征是什么？", "back": "携带外源DNA的DNA分子（多为质粒或噬菌体）；含复制起点ori、易分离纯化、含筛选标记、含多克隆位点MCS", "mnemonic": "ori+标记+MCS，自主复制易纯化", "useImg": false}]}, {"i": 11, "sec": "模块五：基因克隆", "title": "pUC18的结构与筛选原理 (p73)", "notes": "pUC18长约3 kb，含氨苄青霉素抗性基因（Ampr）、复制起点（ori）、多克隆位点（MCS）、lac启动子和lacZ'基因。当外源DNA片段插入MCS时，lacZ'基因的开放阅读框被中断，产生无功能的基因产物，不能消化底物X-gal，因此重组克隆不显蓝色，从而实现筛选。", "page": 73, "level": "掌握", "img": "assets/img/ch04/p073.jpg", "anim": null, "fig": null, "points": ["pUC18长约3 kb", "含氨苄青霉素抗性基因（Ampr）、复制起点（ori）、多克隆位点（MCS）", "含lac启动子和lacZ'基因", "外源DNA插入MCS中断lacZ'开放阅读框，产生无功能产物", "重组克隆不能消化X-gal，不显蓝色，从而实现筛选"], "check": {"q": "pUC18载体结构中，外源DNA插入导致重组克隆不显蓝色的直接原因是？", "o": ["A. 氨苄青霉素抗性基因被破坏", "B. 复制起点ori被破坏", "C. lacZ'基因开放阅读框被中断，产物无功能", "D. lac启动子被增强，表达量升高"], "a": "C", "e": "外源DNA插入MCS使lacZ'开放阅读框中断，产生无功能的基因产物，不能消化X-gal，故重组克隆不显蓝色。"}, "cards": [{"front": "载体按用途可分为哪三类？各举代表？", "back": "克隆载体（pUC18）、原核表达载体（pET-28a、pGEX-4T-1）、真核表达载体（pcDNA3.1、pCAMBIA系列）", "mnemonic": "克隆pUC、原核pET、真核pcDNA", "useImg": false}]}, {"i": 12, "sec": "模块五：基因克隆", "title": "IPTG与X-gal的作用 (p74)", "notes": "实验中在选择性培养基中加入IPTG和X-gal。IPTG是乳糖类似物，为强诱导剂，不被细菌代谢且稳定，可诱导lac启动子表达；X-gal是人工合成的半乳糖苷，被β-半乳糖苷酶水解后产生蓝色化合物。目的DNA插入MCS后lacZ'失活，不能水解X-gal，蓝色菌落无法形成，取而代之的是白色菌落。", "page": 74, "level": "掌握", "img": "assets/img/ch04/p074.jpg", "anim": null, "fig": null, "points": ["IPTG是乳糖类似物，为强诱导剂，不被细菌代谢且稳定", "IPTG诱导lac启动子表达", "X-gal是人工合成半乳糖苷，被β-半乳糖苷酶水解产生蓝色化合物", "目的DNA插入MCS后lacZ'失活，不能水解X-gal，形成白色菌落"], "check": {"q": "关于IPTG和X-gal的作用，下列叙述正确的是？", "o": ["A. IPTG是β-半乳糖苷酶的底物，水解后产生蓝色化合物", "B. X-gal是强诱导剂，可诱导lac启动子表达", "C. IPTG诱导lac启动子表达，X-gal被β-半乳糖苷酶水解产生蓝色化合物", "D. IPTG和X-gal均被细菌代谢利用作为碳源"], "a": "C", "e": "IPTG是稳定的乳糖类似物，为强诱导剂，诱导lac启动子表达；X-gal是人工合成的半乳糖苷，被β-半乳糖苷酶水解后产生蓝色化合物。"}, "cards": [{"front": "pUC18/19载体的MCS位于哪个基因内？", "back": "lacZ'基因（β-半乳糖苷酶部分基因）内部", "mnemonic": "MCS插在lacZ'里", "useImg": false}]}, {"i": 13, "sec": "模块五：基因克隆", "title": "蓝白斑筛选流程 (p75)", "notes": "蓝白斑筛选流程为：将外源DNA与pUC载体连接后转化宿主菌，涂布于含IPTG和X-gal的选择性培养基上培养。未插入外源DNA的载体表达完整lacZ'，水解X-gal形成蓝色菌落；插入外源DNA的载体lacZ'被破坏，形成白色菌落。挑取白色菌落即可获得含重组DNA的克隆，实现重组子的初步筛选。", "page": 75, "level": "掌握", "img": "assets/img/ch04/p075.jpg", "anim": null, "fig": "看蓝白斑筛选：含空载体（lacZ'完整）的菌落水解X-gal呈蓝色；插入外源DNA的菌落lacZ'失活呈白色；挑白色菌落。", "points": [], "check": {"q": "蓝白斑筛选流程中，挑取白色菌落的原因是？", "o": ["A. 白色菌落含未插入外源DNA的载体，lacZ'完整", "B. 白色菌落含重组DNA，lacZ'被破坏不能水解X-gal", "C. 白色菌落因氨苄青霉素抗性基因失活而无法生长", "D. 白色菌落中质粒复制起点被破坏，无法复制"], "a": "B", "e": "插入外源DNA的载体lacZ'被破坏，不能水解X-gal，形成白色菌落；挑取白色菌落即可获得含重组DNA的克隆。"}, "cards": [{"front": "蓝白斑筛选的原理是什么？", "back": "外源DNA插入MCS破坏lacZ'阅读框→β-半乳糖苷酶失活→不能水解X-gal→白色菌落；未插入则显蓝色", "mnemonic": "插入变白，空载变蓝", "useImg": false}]}, {"i": 14, "sec": "模块五：基因克隆", "title": "质粒载体中的克隆过程 (p76)", "notes": "该图展示质粒载体克隆的完整过程：用限制酶切割质粒载体和目的DNA，在DNA连接酶作用下形成重组质粒；将重组质粒转化感受态宿主细胞；细胞繁殖形成克隆；通过选择标记和蓝白斑等筛选方法挑出含重组DNA的克隆。该过程直观体现了“切、接、转、增、筛”的克隆流程。", "page": 76, "level": "理解", "img": "assets/img/ch04/p076.jpg", "anim": null, "fig": "按箭头顺序看：先看限制酶切割载体与目的DNA，再看连接酶连接成重组质粒，随后转化宿主细胞、繁殖成克隆，最后经筛选挑出重组克隆。", "points": ["限制酶切割质粒载体和目的DNA，连接酶作用下形成重组质粒", "重组质粒转化感受态宿主细胞", "细胞繁殖形成克隆", "通过选择标记和蓝白斑筛选挑出含重组DNA的克隆", "直观体现“切、接、转、增、筛”的克隆流程"], "check": {"q": "质粒载体克隆过程中，将重组质粒导入感受态宿主细胞后，通常通过什么方式挑出含重组DNA的克隆？", "o": ["A. 通过显微镜直接观察质粒形态", "B. 通过选择标记和蓝白斑等筛选方法", "C. 通过测定宿主细胞的呼吸速率", "D. 通过加热使非重组细胞死亡"], "a": "B", "e": "重组质粒转化后，需借助选择标记及蓝白斑等筛选方法挑出含重组DNA的克隆。"}, "cards": [{"front": "pUC18的结构包含哪些元件？", "back": "氨苄青霉素抗性基因（Ampr）、复制起点ori、多克隆位点MCS、lac启动子、lacZ'基因，长约3kb", "mnemonic": "Amp+ori+MCS+lac", "useImg": false}]}, {"i": 15, "sec": "模块五：基因克隆", "title": "表达载体的特征 (p77)", "notes": "表达载体是允许克隆基因在有机体内表达的克隆载体。除复制起点、选择标记和多克隆位点外，还必须含启动子和终止子以控制转录，插入基因还需具备起始密码子、终止密码子和正确的阅读框才能翻译。表达载体分为原核和真核两类，是实现外源基因功能研究的重要工具。", "page": 77, "level": "掌握", "img": "assets/img/ch04/p077.jpg", "anim": null, "fig": null, "points": ["表达载体是允许克隆基因在有机体内表达的克隆载体", "除复制起点、选择标记、MCS外，还必须含启动子和终止子控制转录", "插入基因需具备起始密码子、终止密码子和正确阅读框才能翻译", "表达载体分原核和真核两类", "是外源基因功能研究的重要工具"], "check": {"q": "与普通克隆载体相比，表达载体必须额外具备的关键元件是？", "o": ["A. 复制起点和选择标记", "B. 多克隆位点", "C. 启动子和终止子", "D. 氨苄青霉素抗性基因"], "a": "C", "e": "表达载体除复制起点、选择标记和多克隆位点外，还必须含启动子和终止子以控制转录。"}, "cards": [{"front": "IPTG和X-gal分别起什么作用？", "back": "IPTG是乳糖类似物强诱导剂，诱导lac启动子表达；X-gal被β-半乳糖苷酶水解产生蓝色化合物", "mnemonic": "IPTG诱导，X-gal显色", "useImg": false}]}, {"i": 16, "sec": "模块五：基因克隆", "title": "T7表达载体的结构 (p78)", "notes": "T7表达载体是大肠杆菌表达系统中常用的原核表达载体，其结构包括T7启动子、核糖体结合位点（RBS）、起始密码子、多克隆位点、转录终止子、氨苄青霉素抗性基因和复制起点。T7启动子由T7 RNA聚合酶特异性识别，可实现目的基因的高效转录，是原核表达的重要元件。", "page": 78, "level": "理解", "img": "assets/img/ch04/p078.jpg", "anim": null, "fig": null, "points": ["T7表达载体是常用原核表达载体", "结构包括T7启动子、核糖体结合位点（RBS）、起始密码子、多克隆位点", "含转录终止子、氨苄青霉素抗性基因和复制起点", "T7启动子由T7 RNA聚合酶特异性识别，实现目的基因高效转录"], "check": {"q": "T7表达载体中，T7启动子的特点是？", "o": ["A. 由宿主细胞普通RNA聚合酶识别", "B. 由T7 RNA聚合酶特异性识别，实现高效转录", "C. 只负责翻译起始", "D. 直接编码氨苄青霉素抗性"], "a": "B", "e": "T7启动子由T7 RNA聚合酶特异性识别，可实现目的基因的高效转录。"}, "cards": [{"front": "蓝白斑筛选的流程是什么？", "back": "连接→转化→涂布含IPTG和X-gal的选择性培养基→未插入载体显蓝色、插入载体显白色→挑取白色菌落", "mnemonic": "涂板培养，挑白弃蓝", "useImg": false}]}, {"i": 17, "sec": "模块五：基因克隆", "title": "宿主生物与细胞 (p79)", "notes": "宿主细胞是重组DNA复制和扩增的场所。原核宿主最常用大肠杆菌，也有农杆菌等；真核宿主包括酿酒酵母、植物原生质体细胞等。选择宿主需考虑载体复制方式、表达需求及实验目的。宿主细胞的感受态状态直接影响转化效率，是克隆实验成功的关键因素之一。", "page": 79, "level": "理解", "img": "assets/img/ch04/p079.jpg", "anim": null, "fig": null, "points": ["宿主细胞是重组DNA复制和扩增的场所", "原核宿主最常用大肠杆菌，也有农杆菌等", "真核宿主包括酿酒酵母、植物原生质体细胞等", "选择宿主需考虑载体复制方式、表达需求及实验目的", "感受态状态直接影响转化效率，是克隆成功关键因素之一"], "check": {"q": "关于宿主细胞的选择，下列说法正确的是？", "o": ["A. 原核宿主最常用酿酒酵母", "B. 真核宿主包括大肠杆菌和农杆菌", "C. 选择宿主需考虑载体复制方式、表达需求及实验目的", "D. 宿主细胞的感受态状态与转化效率无关"], "a": "C", "e": "选择宿主需综合考虑载体复制方式、表达需求及实验目的；感受态状态直接影响转化效率。"}, "cards": [{"front": "表达载体相比克隆载体还需具备哪些元件？", "back": "启动子和终止子（控制转录）；插入基因还需起始密码子、终止密码子和正确阅读框", "mnemonic": "启动终止加三码一框", "useImg": false}]}, {"i": 18, "sec": "模块五：基因克隆", "title": "转化与感受态细胞 (p80)", "notes": "转化是指宿主细胞从外界环境中摄取DNA的过程。有些细菌天然具有遗传感受态，能自然摄取DNA；实验室中常用氯化钙处理细胞，使其成为感受态，从而提高对重组DNA的摄取效率。转化是基因克隆流程中将重组DNA导入宿主的关键步骤，其效率直接影响克隆结果。", "page": 80, "level": "掌握", "img": "assets/img/ch04/p080.jpg", "anim": null, "fig": null, "points": ["转化指宿主细胞从外界环境摄取DNA的过程", "有些细菌天然具有遗传感受态，能自然摄取DNA", "实验室常用氯化钙处理细胞使其成为感受态", "转化是基因克隆中导入重组DNA的关键步骤", "转化效率直接影响克隆结果"], "check": {"q": "实验室中常用什么方法处理细菌，使其成为感受态以提高对重组DNA的摄取效率？", "o": ["A. 氯化钙处理", "B. 高温高压处理", "C. 紫外线照射", "D. 加入蛋白酶"], "a": "A", "e": "实验室常用氯化钙处理细胞使其成为感受态，从而提高对重组DNA的摄取效率。"}, "cards": [{"front": "T7表达载体的结构包含哪些元件？", "back": "T7启动子、核糖体结合位点RBS、起始密码子、MCS、转录终止子、Amp抗性基因、ori", "mnemonic": "T7启动+RBS+MCS+终止", "useImg": false}]}, {"i": 19, "sec": "模块五：基因克隆", "title": "DNA文库的概念 (p81)", "notes": "DNA文库是一群载体（克隆），每个载体含有不同的DNA插入片段，共同代表一个生物的全部或部分基因组信息。基因组文库由总基因组DNA经限制酶切割后克隆而成，尽可能保存生物全部基因组DNA信息，但并非每个克隆都含完整基因，常用于基因组测序等研究。", "page": 81, "level": "掌握", "img": "assets/img/ch04/p081.jpg", "anim": null, "fig": null, "points": ["DNA文库是一群载体（克隆），每个载体含不同DNA插入片段", "共同代表一个生物的全部或部分基因组信息", "基因组文库由总基因组DNA经限制酶切割后克隆而成", "尽可能保存全部基因组DNA信息，但并非每个克隆都含完整基因", "常用于基因组测序等研究"], "check": {"q": "关于基因组文库，下列说法正确的是？", "o": ["A. 每个克隆都含完整基因", "B. 由总基因组DNA经限制酶切割后克隆而成，尽可能保存全部基因组信息", "C. 只代表生物的部分基因，不能用于基因组测序", "D. 文库中所有载体含相同的DNA插入片段"], "a": "B", "e": "基因组文库由总基因组DNA切割后克隆而成，尽可能保存全部基因组DNA信息，但并非每个克隆都含完整基因。"}, "cards": [{"front": "常用宿主细胞有哪些？", "back": "原核：大肠杆菌（最常用）、农杆菌；真核：酿酒酵母、植物原生质体细胞", "mnemonic": "原核大肠杆菌，真核酵母植原", "useImg": false}]}, {"i": 20, "sec": "模块五：基因克隆", "title": "DNA文库的构建 (p82)", "notes": "该图展示DNA文库的构建过程：将基因组DNA用限制酶切割成片段，与载体连接形成重组分子，转化宿主细胞后获得大量含不同插入片段的克隆，共同构成文库。构建文库的关键在于保证片段覆盖度和代表性，使文库能尽可能完整地保存原基因组的遗传信息。", "page": 82, "level": "理解", "img": "assets/img/ch04/p082.jpg", "anim": null, "fig": "按流程看：基因组DNA先被限制酶切成片段，再与载体连接成重组分子，转化宿主后得到大量含不同插入片段的克隆，这些克隆总体即构成文库。", "points": ["基因组DNA用限制酶切割成片段", "片段与载体连接形成重组分子", "转化宿主细胞获得大量含不同插入片段的克隆", "克隆群体共同构成文库", "关键在保证片段覆盖度和代表性，尽可能完整保存基因组信息"], "check": {"q": "构建DNA文库的关键在于？", "o": ["A. 只使用一种限制酶切出单一长度片段", "B. 保证片段覆盖度和代表性，尽可能完整保存原基因组信息", "C. 尽量减少克隆数量以方便筛选", "D. 不使用载体直接转化宿主"], "a": "B", "e": "构建文库的关键是保证片段覆盖度和代表性，使文库尽可能完整地保存原基因组的遗传信息。"}, "cards": [{"front": "转化的定义及实验室常用方法？", "back": "宿主细胞从外界摄取DNA的过程；实验室常用氯化钙处理使细胞成为感受态，提高摄取效率", "mnemonic": "CaCl2造感受态", "useImg": false}]}, {"i": 21, "sec": "模块五：基因克隆", "title": "cDNA文库 (p83)", "notes": "该图展示cDNA文库的构建：以mRNA为模板，在逆转录酶作用下合成cDNA，再与载体连接、转化宿主，形成含不同cDNA插入片段的克隆群体。cDNA文库只包含表达基因的序列，不含内含子和调控序列，适用于克隆编码特定蛋白的基因，与基因组文库形成互补。", "page": 83, "level": "掌握", "img": "assets/img/ch04/p083.jpg", "anim": null, "fig": "按流程看：从mRNA出发，经逆转录酶合成cDNA，再与载体连接并转化宿主，所得含不同cDNA插入片段的克隆群体即cDNA文库。", "points": ["以mRNA为模板，在逆转录酶作用下合成cDNA", "cDNA与载体连接、转化宿主，形成含不同cDNA插入片段的克隆群体", "cDNA文库只包含表达基因序列，不含内含子和调控序列", "适用于克隆编码特定蛋白的基因", "与基因组文库形成互补"], "check": {"q": "关于cDNA文库的构建与特点，下列叙述正确的是？", "o": ["A. 以基因组DNA为模板直接克隆得到", "B. 以mRNA为模板经逆转录酶合成cDNA后与载体连接、转化宿主", "C. 文库中包含全部内含子与调控序列", "D. 构建过程不需要载体和宿主细胞"], "a": "B", "e": "cDNA文库以mRNA为模板，在逆转录酶作用下合成cDNA，再与载体连接并转化宿主，形成克隆群体；它只含表达基因序列，不含内含子和调控序列。"}, "cards": [{"front": "DNA文库的概念是什么？", "back": "一群载体（克隆），每个含不同DNA插入片段，共同代表一个生物全部或部分基因组信息", "mnemonic": "一群载体，各藏一段", "useImg": false}]}, {"i": 22, "sec": "模块五：基因克隆", "title": "cDNA文库的定义与用途 (p84)", "notes": "cDNA文库是利用逆转录酶将mRNA逆转录为cDNA后构建的文库。由于cDNA只代表表达基因，不含内含子，因此当目标是克隆编码某一特定蛋白的基因时尤为有用。cDNA文库的构建是基因表达分析、功能克隆和真核基因分离的重要技术手段。", "page": 84, "level": "掌握", "img": "assets/img/ch04/p084.jpg", "anim": null, "fig": null, "points": ["cDNA文库利用逆转录酶将mRNA逆转录为cDNA后构建", "cDNA只代表表达基因，不含内含子", "克隆编码特定蛋白的基因时尤为有用", "是基因表达分析、功能克隆和真核基因分离的重要技术手段"], "check": {"q": "当目标是克隆编码某一特定蛋白的基因时，优先选用cDNA文库的主要原因是？", "o": ["A. cDNA文库只代表表达基因且不含内含子", "B. cDNA文库包含全部基因组序列", "C. cDNA文库构建不需要逆转录酶", "D. cDNA文库只能用于原核生物"], "a": "A", "e": "cDNA由mRNA逆转录而来，只代表表达基因、不含内含子，因此特别适合克隆编码特定蛋白的基因。"}, "cards": [{"front": "基因组文库与cDNA文库的核心区别？", "back": "基因组文库含全部基因组DNA（含内含子、调控序列）；cDNA文库只含表达基因（无内含子），由mRNA逆转录而来", "mnemonic": "基因库全，cDNA只表达", "useImg": false}]}, {"i": 23, "sec": "模块五：基因克隆", "title": "cDNA文库构建中的保护策略 (p85)", "notes": "在cDNA文库构建中，若cDNA内部存在EcoRI位点，酶切连接时会被切断。因此在酶切之前先用EcoRI甲基转移酶对cDNA内部的EcoRI位点进行甲基化保护，使其不被EcoRI切割，而接头上的EcoRI位点仍可被切割用于连接载体。该策略保证了cDNA片段的完整性，提高了文库构建效率。", "page": 85, "level": "理解", "img": "assets/img/ch04/p085.jpg", "anim": null, "fig": null, "points": ["问题：cDNA内部若存在EcoRI位点，酶切连接时会被切断", "对策：酶切前先用EcoRI甲基转移酶对cDNA内部EcoRI位点甲基化保护", "接头上的EcoRI位点仍可被切割用于连接载体", "该策略保证cDNA片段完整性，提高文库构建效率"], "check": {"q": "cDNA文库构建中，若cDNA内部存在EcoRI位点，为防止酶切连接时被切断，应采取的措施是？", "o": ["A. 先用EcoRI甲基转移酶甲基化保护cDNA内部位点", "B. 直接用EcoRI切割cDNA后再连接", "C. 用DNA聚合酶补平所有末端", "D. 提高EcoRI酶量以完全切割"], "a": "A", "e": "先用EcoRI甲基转移酶对cDNA内部EcoRI位点甲基化保护，使其不被切割，而接头上的EcoRI位点仍可被切割用于连接载体，从而保证cDNA完整性。"}, "cards": [{"front": "cDNA文库构建的基本过程？", "back": "以mRNA为模板，逆转录酶合成cDNA，与载体连接，转化宿主，形成含不同cDNA插入片段的克隆群体", "mnemonic": "mRNA→cDNA→载体→宿主", "useImg": false}]}, {"i": 24, "sec": "模块五：基因克隆", "title": "菌落杂交筛选文库 (p86)", "notes": "菌落杂交是利用标记DNA探针筛选文库的过程：将文库菌落转移到膜上，裂解细胞使DNA固定，与标记探针杂交，通过放射自显影或显色检测阳性克隆。若文库用噬菌体载体构建，则筛选的是噬菌斑而非菌落，方法基本相同。该技术是从文库中分离目的基因的经典手段。", "page": 86, "level": "掌握", "img": "assets/img/ch04/p086.jpg", "anim": null, "fig": null, "points": ["菌落杂交：将文库菌落转移到膜上", "裂解细胞使DNA固定", "与标记DNA探针杂交", "通过放射自显影或显色检测阳性克隆", "噬菌体载体文库筛选的是噬菌斑，方法基本相同"], "check": {"q": "利用标记DNA探针从文库中筛选阳性克隆的经典技术是？", "o": ["A. 菌落杂交（噬菌体文库则为噬菌斑杂交）", "B. SDS-PAGE电泳", "C. PCR定点突变", "D. 琼脂糖凝胶电泳回收"], "a": "A", "e": "菌落杂交将文库菌落转移到膜上，裂解固定DNA后与标记探针杂交，通过放射自显影或显色检测阳性克隆；噬菌体文库则筛选噬菌斑，方法基本相同。"}, "cards": [{"front": "cDNA文库构建中为何要用EcoRI甲基转移酶？", "back": "保护cDNA内部EcoRI位点不被切割，而接头上的EcoRI位点仍可被切割用于连接载体，保证cDNA完整性", "mnemonic": "内部甲基化保护，接头照切", "useImg": false}]}], "mcq": [{"id": "ch04_mcq_21", "mod": "模块五：基因克隆（酶·载体·文库·筛选）", "modI": 4, "q": "基因克隆过程中，将外源DNA片段插入载体形成重组DNA分子所需要的酶是：", "o": ["A. 限制性内切酶和DNA连接酶", "B. DNA聚合酶和RNA聚合酶", "C. 逆转录酶和核酸酶", "D. 解旋酶和拓扑异构酶"], "a": "A", "e": "形成重组DNA需要限制性内切酶切割DNA、DNA连接酶连接片段，二者是基因克隆中“切”和“接”的关键工具。", "kp": "ch04_s4_1"}, {"id": "ch04_mcq_22", "mod": "模块五：基因克隆（酶·载体·文库·筛选）", "modI": 4, "q": "关于限制性内切酶识别序列长度与切割频率的关系，正确的是：", "o": ["A. 识别序列越长，切割频率越高", "B. 识别序列越短，切割频率越低", "C. 识别序列越长，切割频率越低", "D. 切割频率与识别序列长度无关"], "a": "C", "e": "识别序列越长，其在基因组中出现的概率越低，切割频率越低。如4 bp约每256 bp切一次，8 bp约每65 kb切一次。", "kp": "ch04_s4_7"}, {"id": "ch04_mcq_23", "mod": "模块五：基因克隆（酶·载体·文库·筛选）", "modI": 4, "q": "pUC18载体中多克隆位点（MCS）位于lacZ'基因内部，外源DNA插入后利用X-gal进行筛选，重组克隆应呈现：", "o": ["A. 蓝色菌落", "B. 白色菌落", "C. 红色菌落", "D. 绿色菌落"], "a": "B", "e": "外源DNA插入MCS会破坏lacZ'阅读框，β-半乳糖苷酶失活，不能水解X-gal产生蓝色产物，因此重组克隆为白色菌落。", "kp": "ch04_s4_10"}, {"id": "ch04_mcq_24", "mod": "模块五：基因克隆（酶·载体·文库·筛选）", "modI": 4, "q": "与基因组文库相比，cDNA文库的特点是：", "o": ["A. 包含全部基因组DNA序列", "B. 只包含表达基因的序列，不含内含子", "C. 由总基因组DNA经限制酶切割构建", "D. 每个克隆都含完整基因"], "a": "B", "e": "cDNA文库以mRNA为模板逆转录合成cDNA，只代表表达基因，不含内含子和调控序列，适用于克隆编码特定蛋白的基因。", "kp": "ch04_s4_21"}, {"id": "ch04_mcq_25", "mod": "模块五：基因克隆（酶·载体·文库·筛选）", "modI": 4, "q": "表达载体区别于一般克隆载体的关键特征是：", "o": ["A. 含复制起点", "B. 含选择标记", "C. 含多克隆位点", "D. 含启动子和终止子等表达调控元件"], "a": "D", "e": "表达载体除具备复制起点、选择标记和多克隆位点外，还必须含启动子和终止子等转录调控元件，插入基因还需有起始密码子、终止密码子和正确阅读框才能表达。", "kp": "ch04_s4_15"}], "judge": [], "fill": [], "short": [], "calc": [], "term": []}, {"i": 5, "name": "模块六：克隆基因的表达", "slides": [{"i": 0, "sec": "模块六：克隆基因的表达", "title": "Expressing Cloned Genes (p87)", "notes": "本节主题为克隆基因的表达。基因克隆的最终目的不仅是获得DNA片段，更重要的是研究基因结构与功能并获取其表达产物。将目标基因置于合适的表达载体和宿主系统中，可实现外源蛋白的高效表达，为后续鉴定、纯化及功能研究提供物质基础。", "page": 87, "level": "掌握", "img": "assets/img/ch04/p087.jpg", "anim": null, "fig": null, "points": ["基因克隆的最终目的：研究基因结构与功能、获取表达产物", "将目标基因置于合适表达载体和宿主系统中实现外源蛋白高效表达", "表达产物为后续鉴定、纯化及功能研究提供物质基础"], "check": {"q": "关于克隆基因表达的意义，下列哪项最符合本节内容？", "o": ["A. 基因克隆的唯一目的是获得大量DNA片段", "B. 将目标基因置于合适表达载体和宿主系统中可高效表达外源蛋白", "C. 外源基因只能在真核系统中表达", "D. 表达产物无需纯化即可直接用于功能研究"], "a": "B", "e": "本节指出基因克隆最终目的不仅是获得DNA片段，更重要的是研究基因结构与功能并获取表达产物，需将目标基因置于合适表达载体和宿主系统中实现高效表达。"}, "cards": [{"front": "基因克隆的最终目的是什么？", "back": "不仅是获得DNA片段，更重要的是研究基因结构与功能并获取其表达产物。", "mnemonic": "克隆为表达，表达为功能", "useImg": false}, {"front": "真核表达系统的主要优点是什么？", "back": "蛋白倾向于正确折叠因而可溶；可进行真核特有的翻译后修饰，如磷酸化、糖基化等，这些修饰对许多真核蛋白的活性、稳定性和功能至关重要。", "mnemonic": "折叠好+修饰全，更像天然蛋白", "useImg": false}]}, {"i": 1, "sec": "模块六：克隆基因的表达", "title": "基因克隆的目的与表达系统 (p88)", "notes": "基因克隆的目的在于研究基因结构、功能及其产物，无论出于科研还是盈利目的。克隆与表达可高效获得大量目标蛋白，常将目标蛋白与酶、荧光蛋白或标签融合，便于鉴定或纯化。因此需要选择合适的表达系统，包括原核和真核表达系统。", "page": 88, "level": "掌握", "img": "assets/img/ch04/p088.jpg", "anim": null, "fig": null, "points": ["基因克隆目的在于研究基因结构、功能及其产物", "克隆与表达可高效获得大量目标蛋白", "常将目标蛋白与酶、荧光蛋白或标签融合，便于鉴定或纯化", "表达系统分原核表达系统和真核表达系统两大类"], "check": {"q": "根据本节内容，选择表达系统时需要考虑的类型包括？", "o": ["A. 仅原核表达系统", "B. 仅真核表达系统", "C. 原核和真核表达系统", "D. 仅病毒表达系统"], "a": "C", "e": "讲义明确指出需要选择合适的表达系统，包括原核和真核表达系统。"}, "cards": [{"front": "为什么常将目标蛋白与酶、荧光蛋白或标签融合表达？", "back": "便于对目标蛋白进行鉴定、检测或纯化。", "mnemonic": "融合=带工具上路", "useImg": false}, {"front": "真核表达载体通常含哪些元件？可转染哪些细胞？", "back": "含真核启动子、增强子、多聚腺苷酸化信号及筛选标记；可转染酵母、昆虫或哺乳动物细胞。", "mnemonic": "启动+增强+polyA+筛选，酵母昆虫哺乳动物", "useImg": false}]}, {"i": 2, "sec": "模块六：克隆基因的表达", "title": "融合蛋白表达示意 (p89)", "notes": "该示意图展示融合蛋白表达的基本策略：将目标基因与编码标签或报告蛋白的序列融合在同一开放阅读框中，表达出含目标蛋白和融合伙伴的单一多肽链。融合标签可用于检测、纯化或提高溶解度，是原核表达中常用的设计。", "page": 89, "level": "理解", "img": "assets/img/ch04/p089.jpg", "anim": null, "fig": "看图中目标基因与标签编码序列如何连接在同一开放阅读框内，理解转录翻译后形成一条含两部分的多肽链。", "points": ["融合蛋白策略：目标基因与标签/报告蛋白序列融合在同一开放阅读框中", "表达产物为含目标蛋白和融合伙伴的单一多肽链", "融合标签用于检测、纯化或提高溶解度", "是原核表达中常用的设计"], "check": {"q": "融合蛋白表达的基本策略是？", "o": ["A. 目标基因与标签序列分别置于两个独立启动子下表达", "B. 将目标基因与编码标签或报告蛋白的序列融合在同一开放阅读框中", "C. 将标签蛋白单独表达后再与目标蛋白化学连接", "D. 目标基因与标签序列之间必须插入终止密码子"], "a": "B", "e": "示意图展示将目标基因与编码标签或报告蛋白的序列融合在同一开放阅读框中，表达出含目标蛋白和融合伙伴的单一多肽链。"}, "cards": [{"front": "表达系统主要分为哪两大类？", "back": "原核表达系统和真核表达系统。", "mnemonic": "原核+真核", "useImg": false}]}, {"i": 3, "sec": "模块六：克隆基因的表达", "title": "原核表达——融合蛋白 (p90)", "notes": "PPT原文为“由含有两个融合在一起的开放阅读框的重组DNA表达产生”；融合后通常形成一个连续开放阅读框，表达一条融合多肽。以pTrcHis载体为例，在目标蛋白氨基端融合六个组氨酸，便于用镍亲和层析纯化；必要时可用肠激酶切除标签（识别DDDDK，在K后切割）；该位点是否位于标签与目标蛋白之间取决于载体设计，pTrcHis 通常位于两者之间。", "page": 90, "level": "掌握", "img": "assets/img/ch04/p090.jpg", "anim": null, "fig": "看融合蛋白结构：N端六个组氨酸标签→（可选EK位点）→目标蛋白；标签用于镍亲和纯化，EK用于切除标签。", "points": [], "check": {"q": "以pTrcHis载体为例，在目标蛋白氨基端融合的标签及切除标签所用的酶分别是？", "o": ["A. GST标签；凝血酶", "B. 六个组氨酸；肠激酶", "C. GFP标签；肠激酶", "D. 六个组氨酸；凝血酶"], "a": "B", "e": "pTrcHis载体在目标蛋白氨基端融合六个组氨酸便于镍亲和层析纯化，必要时引入肠激酶识别位点DDDDK，该酶在K后切割以切除标签。"}, "cards": [{"front": "融合蛋白表达的基本策略是什么？", "back": "将目标基因与编码标签或报告蛋白的序列融合在同一开放阅读框中，表达出含目标蛋白和融合伙伴的单一多肽链。", "mnemonic": "同一ORF，一条多肽", "useImg": false}]}, {"i": 4, "sec": "模块六：克隆基因的表达", "title": "组氨酸标签融合蛋白示意 (p91)", "notes": "该图示意寡聚组氨酸表达载体表达出的融合蛋白结构：目标蛋白的N端带有六个组氨酸标签。该标签分子量小、免疫原性低，一般不影响目标蛋白结构与功能，并可与镍离子特异性结合，为后续亲和纯化提供便利。", "page": 91, "level": "理解", "img": "assets/img/ch04/p091.jpg", "anim": null, "fig": "看图中融合蛋白结构：N端为六个组氨酸标签，其后连接目标蛋白，理解标签位置与纯化原理的关系。", "points": ["寡聚组氨酸表达载体表达的目标蛋白N端带六个组氨酸标签", "His标签分子量小、免疫原性低", "一般不影响目标蛋白结构与功能", "标签可与镍离子特异性结合，便于亲和纯化"], "check": {"q": "关于寡聚组氨酸标签的特点，下列哪项不正确？", "o": ["A. 分子量小", "B. 免疫原性低", "C. 一般不影响目标蛋白结构与功能", "D. 可与镍离子特异性结合但无法用于纯化"], "a": "D", "e": "组氨酸标签可与镍离子特异性结合，正是利用这一特性进行亲和纯化，因此D项错误。"}, "cards": [{"front": "pTrcHis载体如何在目标蛋白N端加六个组氨酸？目的是什么？", "back": "PPT原文为两个融合在一起的开放阅读框，融合后形成一个连续ORF，在目标蛋白氨基端融合六个组氨酸，便于用镍亲和层析纯化。", "mnemonic": "六His=N端挂钩，镍柱来抓", "useImg": false}]}, {"i": 5, "sec": "模块六：克隆基因的表达", "title": "镍亲和层析纯化组氨酸标签蛋白 (p92)", "notes": "融合蛋白中的寡聚组氨酸区域对镍离子有高亲和力，因此可用镍亲和层析纯化。固定化镍柱结合带His标签的蛋白，杂蛋白被洗去后，用咪唑或低pH缓冲液竞争洗脱目标蛋白。该方法温和、简便，是重组蛋白纯化的常用手段。", "page": 92, "level": "掌握", "img": "assets/img/ch04/p092.jpg", "anim": null, "fig": null, "points": ["寡聚组氨酸区域对镍离子有高亲和力，可用镍亲和层析纯化", "固定化镍柱结合带His标签蛋白，杂蛋白被洗去", "用咪唑或低pH缓冲液竞争洗脱目标蛋白", "该方法温和、简便，是重组蛋白纯化常用手段"], "check": {"q": "用镍亲和层析纯化His标签蛋白时，洗脱目标蛋白常用的方法是？", "o": ["A. 用高浓度盐溶液竞争洗脱", "B. 用咪唑或低pH缓冲液竞争洗脱", "C. 用SDS变性洗脱", "D. 用EDTA螯合镍后自然脱落"], "a": "B", "e": "固定化镍柱结合带His标签的蛋白，杂蛋白洗去后，用咪唑或低pH缓冲液竞争洗脱目标蛋白，该方法温和简便。"}, "cards": [{"front": "肠激酶识别位点DDDDK的作用是什么？", "back": "肠激酶是丝氨酸蛋白酶，在K后切割，可切除标签获得天然蛋白。", "mnemonic": "DDDDK，K后切", "useImg": false}]}, {"i": 6, "sec": "模块六：克隆基因的表达", "title": "融合标签的常见类型 (p93)", "notes": "常见融合策略包括：LacZ融合（酶），将目标基因与LacZ编码序列融合，可用X-gal显色检测（延伸；PPT仅说明LacZ为酶融合伙伴）；GFP融合（荧光蛋白），将目标基因插入GFP的N端或C端，融合蛋白发出绿色荧光便于示踪；His-tag融合（标签），在目标ORF的N端或C端插入编码His标签的序列，通过结合镍柱纯化。", "page": 93, "level": "掌握", "img": "assets/img/ch04/p093.jpg", "anim": null, "fig": "看三种融合策略：LacZ为酶、GFP为荧光、His为纯化标签；注意融合位置（N/C端）与用途对应。", "points": [], "check": {"q": "下列融合策略与其检测或纯化方式的对应关系，错误的是？", "o": ["A. LacZ融合——可用X-gal显色检测", "B. GFP融合——融合蛋白发出绿色荧光便于示踪", "C. His-tag融合——通过结合镍柱纯化", "D. GFP融合——通过结合镍柱纯化"], "a": "D", "e": "GFP融合是利用绿色荧光便于示踪，而非结合镍柱纯化；结合镍柱纯化对应的是His-tag融合。"}, "cards": [{"front": "组氨酸标签有哪些特点？", "back": "分子量小、免疫原性低，一般不影响目标蛋白结构与功能，可与镍离子特异性结合，便于亲和纯化。", "mnemonic": "小、低、不干扰、能抓镍", "useImg": false}]}, {"i": 7, "sec": "模块六：克隆基因的表达", "title": "原核表达——诱导表达载体 (p94)", "notes": "为获得更多蛋白产物需要强启动子，但如何控制克隆基因表达是关键。诱导型启动子位于克隆基因上游，在未诱导时关闭基因表达，诱导后开启。这样可避免过早表达对细菌生长的影响，尤其当外源蛋白有毒性时，并可通过调整诱导强度和条件改善蛋白可溶性与正确折叠。", "page": 94, "level": "掌握", "img": "assets/img/ch04/p094.jpg", "anim": null, "fig": null, "points": ["获得更多蛋白产物需要强启动子", "诱导型启动子位于克隆基因上游，未诱导时关闭表达，诱导后开启", "可避免过早表达对细菌生长的影响，尤其当外源蛋白有毒性时", "调整诱导强度和条件可改善蛋白可溶性与正确折叠"], "check": {"q": "关于诱导型启动子在原核表达中的作用，下列叙述正确的是？", "o": ["A. 未诱导时关闭克隆基因表达，诱导后开启，可避免过早表达影响细菌生长", "B. 诱导型启动子位于克隆基因下游，只能降低转录效率", "C. 诱导型启动子持续开启表达，因此最适合表达有毒外源蛋白", "D. 诱导型启动子仅用于真核细胞，不能用于原核表达"], "a": "A", "e": "诱导型启动子位于克隆基因上游，未诱导时关闭、诱导后开启，可避免过早表达对细菌生长的影响，尤其在外源蛋白有毒时。"}, "cards": [{"front": "如何用镍亲和层析纯化His标签蛋白？", "back": "固定化镍柱结合带His标签的蛋白，杂蛋白被洗去后，用咪唑或低pH缓冲液竞争洗脱目标蛋白。", "mnemonic": "镍柱抓His，咪唑/低pH放", "useImg": false}]}, {"i": 8, "sec": "模块六：克隆基因的表达", "title": "诱导表达与包涵体 (p95)", "notes": "利用诱导表达载体可减少过早表达对细菌生长的影响，尤其避免外源蛋白毒性；调整诱导强度和条件可避免蛋白合成过快，改善可溶性和正确折叠。但外源基因在大肠杆菌中高水平表达时，常形成不溶、无活性的蛋白聚集体即包涵体。包涵体富含重组蛋白，经分离、变性溶解后需复性重折叠才能获得有生物活性的蛋白。", "page": 95, "level": "掌握", "img": "assets/img/ch04/p095.jpg", "anim": null, "fig": null, "points": ["诱导表达可减少过早表达对细菌生长的影响，避免外源蛋白毒性", "调整诱导强度和条件可避免合成过快，改善可溶性和正确折叠", "外源基因在大肠杆菌高水平表达常形成不溶、无活性的包涵体", "包涵体富含重组蛋白，需分离、变性溶解后复性重折叠才能获得有活性蛋白"], "check": {"q": "外源基因在大肠杆菌中高水平表达时常常形成包涵体，关于包涵体的叙述正确的是？", "o": ["A. 包涵体是可溶且有生物活性的重组蛋白", "B. 包涵体是不溶、无活性的蛋白聚集体，需变性溶解后复性重折叠", "C. 包涵体不含重组蛋白，无法回收利用", "D. 形成包涵体说明蛋白已正确折叠，无需复性"], "a": "B", "e": "包涵体是不溶、无活性的蛋白聚集体，富含重组蛋白，需分离、变性溶解并复性重折叠才能获得有活性的蛋白。"}, "cards": [{"front": "常见融合标签有哪三种？各自用途是什么？", "back": "LacZ融合（酶，X-gal显色检测）；GFP融合（荧光蛋白，绿色荧光示踪）；His-tag融合（标签，结合镍柱纯化）。", "mnemonic": "LacZ显色、GFP发光、His抓镍", "useImg": false}]}, {"i": 9, "sec": "模块六：克隆基因的表达", "title": "常用诱导型启动子 (p96)", "notes": "常用诱导型启动子包括：lac启动子受IPTG诱导；trc启动子是trp和lac的杂合启动子，也受IPTG诱导；PBAD启动子受阿拉伯糖诱导，如用PBAD载体通过阿拉伯糖诱导表达GFP；PL启动子受温度诱导（通常升温至42℃）。不同诱导方式适用于不同表达需求。", "page": 96, "level": "掌握", "img": "assets/img/ch04/p096.jpg", "anim": null, "fig": "看PBAD/araC调控：阿拉伯糖存在时诱导GFP表达；对比诱导前后，理解“先关后开”的控制逻辑。", "points": [], "check": {"q": "下列诱导型启动子与其诱导方式的对应关系中，正确的是？", "o": ["A. lac启动子受温度诱导（42℃）", "B. PBAD启动子受IPTG诱导", "C. PL启动子受阿拉伯糖诱导", "D. trc启动子是trp和lac的杂合启动子，受IPTG诱导"], "a": "D", "e": "lac和trc启动子受IPTG诱导；PBAD受阿拉伯糖诱导；PL受温度诱导（42℃）。"}, "cards": [{"front": "为什么原核表达常用诱导型启动子？", "back": "未诱导时关闭基因表达，避免过早表达影响细菌生长（尤其外源蛋白有毒性时）；诱导后开启，并可通过调整诱导强度和条件改善蛋白可溶性与正确折叠。", "mnemonic": "先关后开，护菌又护蛋白", "useImg": false}]}, {"i": 10, "sec": "模块六：克隆基因的表达", "title": "真核表达 (p97)", "notes": "外源基因也可在真核细胞中表达。其优点包括：蛋白倾向于正确折叠，因而可溶；可进行真核特有的翻译后修饰，如磷酸化、糖基化等。这些修饰对许多真核蛋白的活性、稳定性和功能至关重要，因此真核表达系统更适合表达需要翻译后修饰的复杂蛋白。", "page": 97, "level": "掌握", "img": "assets/img/ch04/p097.jpg", "anim": null, "fig": null, "points": ["外源基因也可在真核细胞中表达", "真核表达蛋白倾向于正确折叠，因而可溶", "可进行真核特有的翻译后修饰，如磷酸化、糖基化", "这些修饰对真核蛋白的活性、稳定性和功能至关重要，适合表达需翻译后修饰的复杂蛋白"], "check": {"q": "与大肠杆菌表达系统相比，真核表达系统的主要优点不包括？", "o": ["A. 蛋白倾向于正确折叠，因而可溶", "B. 可进行磷酸化、糖基化等翻译后修饰", "C. 表达产物更接近天然蛋白，适合复杂蛋白", "D. 无需任何筛选标记即可高效表达外源基因"], "a": "D", "e": "真核表达的优点是正确折叠和翻译后修饰；筛选标记是载体的组成部分，并非真核表达相对原核表达的优点。"}, "cards": [{"front": "什么是包涵体？如何处理？", "back": "外源基因在大肠杆菌中高水平表达时形成的不溶、无活性蛋白聚集体。富含重组蛋白，经分离、变性溶解后需复性重折叠才能获得有生物活性的蛋白。", "mnemonic": "聚集成团→变性溶解→复性重生", "useImg": false}]}, {"i": 11, "sec": "模块六：克隆基因的表达", "title": "真核表达系统示意 (p98)", "notes": "该示意图展示外源基因在真核细胞中表达的过程与优势。真核表达载体通常含真核启动子、增强子、多聚腺苷酸化信号及筛选标记，可转染酵母、昆虫或哺乳动物细胞。表达产物能正确折叠并进行糖基化、磷酸化等修饰，更接近天然蛋白，适用于功能研究和药物生产。", "page": 98, "level": "理解", "img": "assets/img/ch04/p098.jpg", "anim": null, "fig": "看图中外源基因在真核细胞内的表达流程及载体元件，注意启动子、增强子、polyA信号和筛选标记的作用，以及产物修饰优势。", "points": ["真核表达载体通常含真核启动子、增强子、多聚腺苷酸化信号及筛选标记", "可转染酵母、昆虫或哺乳动物细胞", "表达产物能正确折叠并进行糖基化、磷酸化等修饰，更接近天然蛋白", "适用于功能研究和药物生产"], "check": {"q": "关于真核表达载体及真核表达系统的叙述，正确的是？", "o": ["A. 真核表达载体通常含真核启动子、增强子、多聚腺苷酸化信号及筛选标记", "B. 真核表达载体只能转染大肠杆菌", "C. 真核表达产物不能进行糖基化修饰", "D. 真核表达系统只适用于原核蛋白的功能研究"], "a": "A", "e": "真核表达载体含真核启动子、增强子、多聚腺苷酸化信号及筛选标记，可转染酵母、昆虫或哺乳动物细胞，产物可正确折叠并修饰。"}, "cards": [{"front": "常用诱导型启动子及其诱导方式有哪些？", "back": "lac启动子受IPTG诱导；trc启动子（trp和lac杂合）受IPTG诱导；PBAD启动子受阿拉伯糖诱导；PL启动子受温度诱导（42℃）。", "mnemonic": "lac/trc用IPTG，PBAD用阿拉伯糖，PL用42℃", "useImg": false}]}], "mcq": [{"id": "ch04_mcq_26", "mod": "模块六：克隆基因的表达", "modI": 5, "q": "在原核表达中，将目标蛋白与六个组氨酸标签融合的主要目的是什么？", "o": ["A. 提高目标蛋白的转录水平", "B. 便于通过镍亲和层析纯化目标蛋白", "C. 使目标蛋白发生糖基化修饰", "D. 促进目标蛋白形成包涵体"], "a": "B", "e": "寡聚组氨酸标签对镍离子有高亲和力，可用镍亲和层析纯化融合蛋白。", "kp": "ch04_s5_4"}, {"id": "ch04_mcq_27", "mod": "模块六：克隆基因的表达", "modI": 5, "q": "关于诱导型启动子的作用，下列叙述正确的是？", "o": ["A. 在未诱导时关闭克隆基因表达，减少对宿主生长的影响", "B. 持续高水平表达外源基因，不受诱导条件控制", "C. 仅存在于真核表达载体中", "D. 可自动切除融合标签"], "a": "A", "e": "诱导型启动子位于克隆基因上游，未诱导时关闭表达，诱导后开启，可减少过早表达对细菌生长的影响，尤其当外源蛋白有毒性时。", "kp": "ch04_s5_9"}, {"id": "ch04_mcq_28", "mod": "模块六：克隆基因的表达", "modI": 5, "q": "下列哪种启动子受阿拉伯糖诱导？", "o": ["A. lac启动子", "B. trc启动子", "C. PBAD启动子", "D. PL启动子"], "a": "C", "e": "PBAD启动子受阿拉伯糖诱导；lac和trc受IPTG诱导，PL受温度诱导。", "kp": "ch04_s5_9"}, {"id": "ch04_mcq_29", "mod": "模块六：克隆基因的表达", "modI": 5, "q": "外源基因在大肠杆菌中高水平表达时，常形成的不溶性、无活性蛋白聚集体称为什么？", "o": ["A. 融合蛋白", "B. 包涵体", "C. 组氨酸标签", "D. 复性体"], "a": "B", "e": "包涵体是外源基因高水平表达时形成的不溶性、无活性蛋白聚集体，需经变性溶解和复性重折叠才能获得有生物活性的蛋白。", "kp": "ch04_s5_8"}, {"id": "ch04_mcq_30", "mod": "模块六：克隆基因的表达", "modI": 5, "q": "与大肠杆菌表达系统相比，真核表达系统的主要优势是什么？", "o": ["A. 表达速度更快且成本更低", "B. 蛋白倾向于正确折叠并可进行糖基化等翻译后修饰", "C. 不需要任何筛选标记", "D. 只能表达原核基因"], "a": "B", "e": "真核表达系统可使蛋白正确折叠，并进行磷酸化、糖基化等真核特有的翻译后修饰，更适合表达复杂真核蛋白。", "kp": "ch04_s5_11"}], "judge": [], "fill": [], "short": [], "calc": [], "term": []}, {"i": 6, "name": "模块七：基因操作（过表达·RNAi·CRISPR）", "slides": [{"i": 0, "sec": "基因操作", "title": "基因操作概述 (p99)", "notes": "本节介绍基因操作（gene manipulation）的核心策略：通过人为升高或降低特定基因的表达量，放大或缩小其生物学效应，从而推断该基因的生物学功能。这是功能基因组学研究的基本逻辑，也是分子生物学从“读基因”走向“写/改基因”的关键一步。", "page": 99, "level": "掌握", "img": "assets/img/ch04/p099.jpg", "anim": null, "fig": null, "points": ["基因操作的核心策略：人为升高或降低特定基因的表达量", "通过放大或缩小生物学效应推断基因功能", "是功能基因组学研究的基本逻辑", "标志分子生物学从'读基因'走向'写/改基因'"], "check": {"q": "基因操作推断基因功能的基本逻辑是？", "o": ["A. 通过人为升高或降低特定基因的表达量，放大或缩小其生物学效应", "B. 通过测序直接读取基因的碱基序列", "C. 通过改变基因的染色体位置来改变其功能", "D. 通过随机突变所有基因后筛选表型"], "a": "A", "e": "基因操作的核心策略是人为升高或降低特定基因表达量，放大或缩小其生物学效应，从而推断基因功能。"}, "cards": [{"front": "基因操作推断基因功能的基本逻辑是什么？", "back": "人为升高或降低特定基因的表达量，放大或缩小其生物学效应，从而推断该基因的生物学功能。", "mnemonic": "调表达→看表型→推功能", "useImg": false}]}, {"i": 1, "sec": "基因操作", "title": "功能获得与功能缺失策略 (p100)", "notes": "确定基因功能有两条互补路径：功能获得（gain of function）即过表达（overexpression），提高表达量以观察表型增强；功能缺失（loss of function）即RNA干扰（RNAi）或基因敲除（knock-out），降低表达量以观察表型减弱或消失。二者相互印证，可较可靠地确定基因功能。", "page": 100, "level": "掌握", "img": "assets/img/ch04/p100.jpg", "anim": null, "fig": null, "points": ["功能获得（gain of function）即过表达，提高表达量观察表型增强", "功能缺失（loss of function）即RNAi或基因敲除，降低表达量观察表型减弱或消失", "两条路径互补、相互印证", "二者结合可较可靠地确定基因功能"], "check": {"q": "下列哪项属于功能缺失（loss of function）策略？", "o": ["A. 过表达", "B. RNA干扰或基因敲除", "C. 强启动子驱动目标基因", "D. 提高蛋白水平观察表型增强"], "a": "B", "e": "功能缺失即RNAi或基因敲除，降低表达量以观察表型减弱或消失；过表达属于功能获得。"}, "cards": [{"front": "确定基因功能的两条互补路径是什么？", "back": "功能获得（gain of function，过表达）与功能缺失（loss of function，RNAi或基因敲除）。", "mnemonic": "一升一降，互相印证", "useImg": false}]}, {"i": 2, "sec": "基因操作", "title": "过表达确定基因功能示意 (p101)", "notes": "该页为示意图，表达过表达技术确定基因功能的实验逻辑：将目标基因克隆到强启动子/表达载体中，转染细胞后使蛋白水平显著升高，再比较过表达组与对照组的表型、增殖、凋亡或信号通路变化。若过表达引起特定表型，则提示该基因在该过程中起促进或调控作用，常与敲低/敲除实验互为佐证。", "page": 101, "level": "理解", "img": "assets/img/ch04/p101.jpg", "anim": null, "fig": "图示过表达确定基因功能的实验逻辑：左侧为构建含强启动子的表达载体并转染细胞，右侧对比过表达组与对照组的表型/增殖/凋亡等指标。沿箭头方向看'基因克隆→转染→蛋白升高→表型比较'的流程即可理解实验设计。", "points": ["将目标基因克隆到强启动子/表达载体中", "转染细胞使蛋白水平显著升高", "比较过表达组与对照组的表型、增殖、凋亡或信号通路变化", "过表达引起特定表型提示该基因起促进或调控作用", "常与敲低/敲除实验互为佐证"], "check": {"q": "过表达确定基因功能的实验中，通常将目标基因克隆到何处？", "o": ["A. 弱启动子/表达载体", "B. 强启动子/表达载体", "C. 仅克隆到siRNA载体", "D. 直接导入dsRNA"], "a": "B", "e": "过表达需将目标基因克隆到强启动子/表达载体中，转染后使蛋白水平显著升高，再与对照组比较表型。"}, "cards": [{"front": "过表达确定基因功能的实验逻辑是什么？", "back": "将目标基因克隆到强启动子/表达载体，转染细胞使蛋白显著升高，比较过表达组与对照组的表型、增殖、凋亡或信号通路变化；若引起特定表型，提示该基因起促进或调控作用。", "mnemonic": "强启动子+转染→蛋白升高→比表型", "useImg": false}]}, {"i": 3, "sec": "基因操作", "title": "RNA干扰的原理 (p102)", "notes": "RNAi的原理是：双链RNA（dsRNA）进入细胞后被Dicer切割成小干扰RNA（siRNA），siRNA组装进RISC复合体，以碱基配对方式识别并结合靶mRNA，导致其降解或翻译受抑，从而特异性降低该基因表达。注：PPT原文为简化表述（dsRNA与mRNA配对并抑制翻译）；经典机制为dsRNA经Dicer加工成siRNA、组装进RISC后识别靶mRNA。RNAi具有高度序列特异性、操作简便、可快速实现基因敲低，是研究基因功能的常用手段。", "page": 102, "level": "掌握", "img": "assets/img/ch04/p102.jpg", "anim": null, "fig": null, "points": ["dsRNA被Dicer切割成siRNA", "siRNA组装进RISC复合体", "以碱基配对识别并结合靶mRNA，导致降解或翻译受抑", "具有高度序列特异性、操作简便、可快速敲低基因", "是研究基因功能的常用手段"], "check": {"q": "RNAi中，dsRNA被Dicer切割后形成什么并组装进RISC？", "o": ["A. gRNA", "B. siRNA", "C. cDNA", "D. PAM序列"], "a": "B", "e": "dsRNA被Dicer切割成siRNA，siRNA组装进RISC，以碱基配对识别并结合靶mRNA，导致其降解或翻译受抑。"}, "cards": [{"front": "RNAi的基本原理是什么？", "back": "dsRNA被Dicer切割成siRNA，siRNA组装进RISC，以碱基配对识别并结合靶mRNA，导致其降解或翻译受抑，特异性降低基因表达。", "mnemonic": "Dicer切→RISC装→配对切mRNA", "useImg": false}]}, {"i": 4, "sec": "基因操作", "title": "RNAi实验流程与qPCR检测 (p103)", "notes": "该页展示RNAi实验流程：将siRNA或shRNA转染细胞→培养一定时间→提取细胞总RNA→反转录为cDNA→用实时定量PCR（Realtime PCR）检测靶基因mRNA水平，以评估敲低效率。通常还需设阴性对照siRNA，并以管家基因作内参归一化。敲低效率确认后，再观察表型变化以推断基因功能。", "page": 103, "level": "掌握", "img": "assets/img/ch04/p103.jpg", "anim": null, "fig": "图示RNAi实验流程：从siRNA/shRNA转染细胞开始，依次经培养、提取总RNA、反转录cDNA到实时定量PCR检测。按箭头顺序理解各步骤，注意qPCR环节用于评估敲低效率，并配有阴性对照与管家基因内参。", "points": ["流程：siRNA/shRNA转染细胞→培养→提取总RNA→反转录为cDNA→Realtime PCR检测mRNA水平", "以qPCR评估敲低效率", "需设阴性对照siRNA", "以管家基因作内参归一化", "敲低效率确认后再观察表型变化推断基因功能"], "check": {"q": "RNAi实验流程中，评估敲低效率通常采用什么方法检测靶基因mRNA水平？", "o": ["A. 实时定量PCR（Realtime PCR）", "B. 免疫共沉淀", "C. 凝胶迁移实验", "D. 染色体免疫沉淀"], "a": "A", "e": "流程为转染siRNA/shRNA→培养→提取总RNA→反转录为cDNA→实时定量PCR检测靶基因mRNA水平，并以管家基因作内参归一化。"}, "cards": [{"front": "RNAi实验流程及敲低效率如何检测？", "back": "转染siRNA或shRNA→培养→提取总RNA→反转录为cDNA→实时定量PCR检测靶基因mRNA水平；设阴性对照siRNA，以管家基因作内参归一化，确认敲低后再观察表型。", "mnemonic": "转染→提RNA→反转录→qPCR→看表型", "useImg": false}]}, {"i": 5, "sec": "基因操作", "title": "CRISPR/Cas9基因编辑原理 (p104)", "notes": "CRISPR/Cas9系统工作原理分三个关键步骤：①gRNA与Cas9形成复合物；②gRNA通过碱基互补靶向基因组特定位点，Cas9识别PAM序列后切割DNA产生双链断裂；③细胞通过修复机制修复断裂。PPT本页仅给出“三步骤”框架，PAM识别等细节见后续页/教材。其核心优势是可编程性——只需设计不同gRNA，即可靶向几乎任何DNA序列，实现基因敲除、敲入或修饰。", "page": 104, "level": "掌握", "img": "assets/img/ch04/p104.jpg", "anim": null, "fig": null, "points": ["gRNA与Cas9形成复合物", "gRNA通过碱基互补靶向特定位点，Cas9识别PAM后切割DNA产生双链断裂", "细胞通过修复机制修复断裂", "核心优势是可编程性：设计不同gRNA即可靶向几乎任何DNA序列", "可实现基因敲除、敲入或修饰"], "check": {"q": "CRISPR/Cas9切割DNA前，Cas9识别靶位点所需的序列是？", "o": ["A. TATA盒", "B. PAM序列", "C. 启动子", "D. 增强子"], "a": "B", "e": "gRNA通过碱基互补靶向特定位点，Cas9识别PAM序列后切割DNA产生双链断裂。"}, "cards": [{"front": "CRISPR/Cas9系统工作的三个关键步骤是什么？", "back": "①gRNA与Cas9形成复合物；②gRNA碱基互补靶向特定位点，Cas9识别PAM后切割DNA产生双链断裂；③细胞通过修复机制修复断裂。核心优势是可编程性。", "mnemonic": "组装→靶向切割（认PAM）→修复", "useImg": false}]}, {"i": 6, "sec": "基因操作", "title": "NHEJ与HDR两种修复途径 (p105)", "notes": "Cas9切割后，细胞通过两种途径修复：无修复模板时走非同源末端连接（NHEJ），在断裂处产生随机插入或缺失（indel），可造成移码或功能丧失（并非所有indel都导致移码），从而获得功能性敲除细胞系；提供修复模板时走同源定向修复（HDR），可在特定位点精确引入用户定义的序列，用于过表达新基因、建立疾病相关细胞模型或用报告基因标记内源基因。", "page": 105, "level": "掌握", "img": "assets/img/ch04/p105.jpg", "anim": null, "fig": null, "points": ["无修复模板时走非同源末端连接（NHEJ），产生随机插入或缺失（indel）", "indel可造成移码或功能丧失（并非必然），可获得功能性敲除细胞系", "提供修复模板时走同源定向修复（HDR）", "HDR可精确引入用户定义序列，用于过表达新基因、建立疾病模型或用报告基因标记内源基因"], "check": {"q": "Cas9切割后无修复模板时，细胞通过哪种途径修复并产生indel？", "o": ["A. 同源定向修复（HDR）", "B. 非同源末端连接（NHEJ）", "C. 碱基切除修复", "D. 错配修复"], "a": "B", "e": "无修复模板时走NHEJ，在断裂处产生随机插入或缺失（indel），可造成移码或功能丧失（并非必然）；提供模板时走HDR。"}, "cards": [{"front": "Cas9切割后NHEJ与HDR两种修复途径有何区别？", "back": "NHEJ无修复模板，产生随机插入/缺失（indel），可造成移码或功能丧失（并非必然），用于功能性敲除；HDR提供修复模板，可精确引入用户定义序列，用于敲入、疾病模型或报告基因标记。", "mnemonic": "NHEJ无模板→indel敲除；HDR有模板→精确敲入", "useImg": false}]}, {"i": 7, "sec": "基因操作", "title": "不同Cas蛋白与PAM序列 (p106)", "notes": "不同来源的Cas蛋白识别的PAM序列不同，为科研提供多样化工具：SpCas9最常用，识别NGG，基因组中分布广；SaCas9蛋白尺寸小，更适合病毒载体递送；Cas12a识别富含T的TTTV，切割产生黏性末端，有时用于多基因编辑；xCas9等工程化变体放宽PAM限制（如NG、GAA），扩大可靶向范围。选择时需兼顾PAM可用性、载体容量与编辑目的（此句为延伸建议，PPT未列具体标准）。", "page": 106, "level": "理解", "img": "assets/img/ch04/p106.jpg", "anim": null, "fig": null, "points": ["不同来源Cas蛋白识别的PAM序列不同，提供多样化工具", "SpCas9最常用，识别NGG，基因组分布广", "SaCas9蛋白尺寸小，更适合病毒载体递送", "Cas12a识别富含T的TTTV，产生黏性末端，有时用于多基因编辑", "xCas9等工程化变体放宽PAM限制（如NG、GAA），扩大靶向范围；选择需兼顾PAM可用性、载体容量与编辑目的（延伸建议）"], "check": {"q": "关于不同Cas蛋白与PAM序列的叙述，下列哪项正确？", "o": ["A. SpCas9识别富含T的TTTV序列，切割产生黏性末端", "B. SaCas9蛋白尺寸小，更适合病毒载体递送", "C. Cas12a识别NGG，基因组中分布最广", "D. xCas9等工程化变体收紧了PAM限制，只能识别NGG"], "a": "B", "e": "SaCas9蛋白尺寸小，更适合病毒载体递送；SpCas9识别NGG，Cas12a识别富含T的TTTV并产生黏性末端，xCas9等变体放宽PAM限制。"}, "cards": [{"front": "常见Cas蛋白的PAM序列及特点是什么？", "back": "SpCas9识别NGG，最常用、分布广；SaCas9蛋白小，适合病毒载体递送；Cas12a识别富含T的TTTV，产生黏性末端，有时用于多基因编辑；xCas9等变体放宽PAM限制（NG、GAA），扩大靶向范围。", "mnemonic": "Sp=NGG常用；Sa=小好递送；Cas12a=TTTV黏性末端；xCas9=PAM放宽", "useImg": false}]}], "mcq": [{"id": "ch04_mcq_31", "mod": "模块七：基因操作（过表达·RNAi·CRISPR）", "modI": 6, "q": "下列哪项属于“功能缺失（loss of function）”研究策略？", "o": ["A. 将目标基因克隆到强启动子下游过表达", "B. 用RNAi降低目标基因表达", "C. 用报告基因标记内源基因", "D. 用HDR引入点突变以增强蛋白活性"], "a": "B", "e": "RNAi通过降解mRNA降低表达，属于功能缺失；过表达为功能获得，报告基因标记和HDR增强活性不属于功能缺失。", "kp": "ch04_s6_1"}, {"id": "ch04_mcq_32", "mod": "模块七：基因操作（过表达·RNAi·CRISPR）", "modI": 6, "q": "RNA干扰中，与靶mRNA碱基配对并抑制其翻译或促其降解的关键复合体是？", "o": ["A. 剪接体", "B. RISC", "C. 核糖体大亚基", "D. 蛋白酶体"], "a": "B", "e": "dsRNA被Dicer切割为siRNA后组装进RISC，由RISC识别并切割靶mRNA，实现特异性基因沉默。", "kp": "ch04_s6_3"}, {"id": "ch04_mcq_33", "mod": "模块七：基因操作（过表达·RNAi·CRISPR）", "modI": 6, "q": "CRISPR/Cas9切割产生双链断裂后，在无修复模板情况下主要发生的修复方式是？", "o": ["A. 同源定向修复（HDR）", "B. 非同源末端连接（NHEJ）", "C. 碱基切除修复（BER）", "D. 错配修复（MMR）"], "a": "B", "e": "无模板时细胞主要走NHEJ，产生随机插入/缺失，可用于构建功能性敲除细胞系；提供模板时才走HDR。", "kp": "ch04_s6_5"}, {"id": "ch04_mcq_34", "mod": "模块七：基因操作（过表达·RNAi·CRISPR）", "modI": 6, "q": "关于SpCas9识别的PAM序列，正确的是？", "o": ["A. TTTV", "B. NNGRRT", "C. NGG", "D. GAA"], "a": "C", "e": "SpCas9来源于化脓链球菌，识别NGG；TTTV为Cas12a，NNGRRT为SaCas9，GAA为工程化变体放宽后的PAM。", "kp": "ch04_s6_7"}, {"id": "ch04_mcq_35", "mod": "模块七：基因操作（过表达·RNAi·CRISPR）", "modI": 6, "q": "检测RNAi敲低效率时，最直接且常用的方法是？", "o": ["A. 提取RNA反转录后进行Realtime PCR检测靶基因mRNA水平", "B. 直接进行Western blot检测DNA含量", "C. 用CRISPR敲除该基因", "D. 用HDR引入报告基因"], "a": "A", "e": "RNAi主要降低mRNA并影响蛋白，提取RNA反转录后qPCR检测mRNA水平是评估敲低效率的常用直接方法。", "kp": "ch04_s6_4"}], "judge": [], "fill": [], "short": [], "calc": [], "term": []}, {"i": 7, "name": "模块八：组学技术与基因组学", "slides": [{"i": 0, "sec": "组学技术与基因组学", "title": "Omics Technologies 全景扫描 (p107)", "notes": "组学（Omics）是一类在整体水平上研究生物分子集合的学科群，包括基因组学、转录组学、蛋白质组学、代谢组学和表观基因组学等。其核心价值在于：全景扫描——一次性获取海量分子信息；发现假说——通过差异分析和功能富集提出候选机制；揭示网络——整合多组学数据构建调控网络。组学改变了传统“一个基因一个实验”的研究范式，使系统生物学成为可能。", "page": 107, "level": "掌握", "img": "assets/img/ch04/p107.jpg", "anim": null, "fig": null, "points": ["组学定义：整体水平研究生物分子集合的学科群", "五大组学：基因组学、转录组学、蛋白质组学、代谢组学、表观基因组学", "核心价值：全景扫描、发现假说、揭示网络", "改变'一个基因一个实验'范式，使系统生物学成为可能"], "check": {"q": "关于组学（Omics）的核心价值，下列哪项描述最符合本页内容？", "o": ["A. 只研究单个基因的功能，强调逐一实验验证", "B. 全景扫描获取海量分子信息，并通过差异分析与功能富集提出候选机制、整合多组学构建调控网络", "C. 仅用于测定DNA序列，不涉及其他分子层次", "D. 主要目的是替代所有下游靶向实验，直接证明机制"], "a": "B", "e": "组学强调全景扫描、发现假说和揭示网络，改变“一个基因一个实验”的范式，但不能替代下游验证。"}, "cards": [{"front": "什么是组学（Omics）？其核心价值体现在哪三个方面？", "back": "组学是在整体水平研究生物分子集合的学科群（基因组学、转录组学、蛋白质组学、代谢组学、表观基因组学等）。核心价值：①全景扫描——一次性获取海量分子信息；②发现假说——通过差异分析和功能富集提出候选机制；③揭示网络——整合多组学数据构建调控网络。", "mnemonic": "扫（全景）→猜（假说）→网（网络）", "useImg": false}]}, {"i": 1, "sec": "组学技术与基因组学", "title": "组学名称与核心研究对象 (p108)", "notes": "本页以表格形式列出五类组学：基因组学研究全部DNA序列、结构、功能；转录组学研究特定条件下所有RNA转录本（尤其mRNA）的种类和数量；蛋白质组学研究全部蛋白质的表达、修饰与相互作用；代谢组学研究所有小分子代谢物（糖、脂、氨基酸等）的种类和数量；表观基因组学研究DNA序列不变时所有可遗传化学修饰（DNA甲基化、组蛋白修饰等）。各层次从遗传信息到表型逐步展开，构成系统生物学的基础。", "page": 108, "level": "掌握", "img": "assets/img/ch04/p108.jpg", "anim": null, "fig": null, "points": ["基因组学：全部DNA序列、结构、功能", "转录组学：特定条件下所有RNA转录本（尤其mRNA）的种类和数量", "蛋白质组学：全部蛋白质的表达、修饰与相互作用", "代谢组学：所有小分子代谢物种类和数量", "表观基因组学：DNA序列不变时的可遗传化学修饰（DNA甲基化、组蛋白修饰）"], "check": {"q": "下列组学与其核心研究对象的对应关系，正确的是？", "o": ["A. 转录组学——研究全部DNA序列与结构", "B. 蛋白质组学——研究所有小分子代谢物的种类和数量", "C. 表观基因组学——研究DNA序列不变时所有可遗传化学修饰", "D. 代谢组学——研究全部RNA转录本的种类和数量"], "a": "C", "e": "表观基因组学研究DNA序列不变时的可遗传化学修饰，如DNA甲基化和组蛋白修饰。"}, "cards": [{"front": "五类组学各自的核心研究对象是什么？", "back": "基因组学：全部DNA序列、结构、功能；转录组学：特定条件下所有RNA转录本（尤其mRNA）的种类和数量；蛋白质组学：全部蛋白质的表达、修饰与相互作用；代谢组学：所有小分子代谢物（糖、脂、氨基酸等）的种类和数量；表观基因组学：DNA序列不变时所有可遗传化学修饰（DNA甲基化、组蛋白修饰等）。", "mnemonic": "DNA→RNA→蛋白→代谢物，外加表观修饰层", "useImg": false}]}, {"i": 2, "sec": "组学技术与基因组学", "title": "组学研究的一般技术路线 (p109)", "notes": "组学研究的通用流程包括四步：①样本制备与数据采集，利用高通量技术大规模获取数据；②数据处理与生物信息学分析，这是核心步骤，包括序列比对/组装、定量与比较（如疾病vs健康）、功能富集分析（找出差异分子显著集中的通路）；③整合分析，将多组学数据（如转录组+蛋白质组）联合分析，构建更完整的调控网络；④验证与机制研究，组学通常产生海量“相关性”假设，需下游靶向实验验证并探索机制。", "page": 109, "level": "掌握", "img": "assets/img/ch04/p109.jpg", "anim": null, "fig": null, "points": ["四步流程：样本制备与数据采集→生物信息学分析→整合分析→验证与机制研究", "生物信息学分析是核心：序列比对/组装、定量比较、功能富集分析", "整合分析：多组学联合构建调控网络", "组学产生'相关性'假设，需下游靶向实验验证"], "check": {"q": "在组学研究的一般技术路线中，被视为核心步骤的是？", "o": ["A. 样本制备与数据采集", "B. 数据处理与生物信息学分析", "C. 整合分析", "D. 验证与机制研究"], "a": "B", "e": "数据处理与生物信息学分析是核心步骤，包括比对/组装、定量比较和功能富集分析等。"}, "cards": [{"front": "组学研究的一般技术路线包括哪四步？哪一步是核心？", "back": "①样本制备与数据采集（高通量技术大规模获取数据）；②数据处理与生物信息学分析（核心步骤：序列比对/组装、定量与比较、功能富集分析）；③整合分析（多组学数据联合分析，构建调控网络）；④验证与机制研究（组学产生海量相关性假设，需下游靶向实验验证）。", "mnemonic": "采→算→整→验", "useImg": false}]}, {"i": 3, "sec": "基因组学", "title": "基因组和基因组学的定义 (p110)", "notes": "基因组（genome）是有机体的一组完整基因，最终由DNA全序列决定。基因组学（genomics）是研究整个基因组结构与功能的学科，其核心原理是利用测序技术获取生物体全部遗传密码，并结合生物信息学方法分析其结构、功能和变异。基因组学从整体视角研究遗传信息，区别于传统针对单个基因的研究，是组学时代的起点和基石。", "page": 110, "level": "掌握", "img": "assets/img/ch04/p110.jpg", "anim": null, "fig": null, "points": ["基因组：有机体的一组完整基因，由DNA全序列决定", "基因组学：研究整个基因组结构与功能的学科", "核心原理：测序获取全部遗传密码+生物信息学分析结构、功能、变异", "整体视角区别于单基因研究，是组学时代的起点和基石"], "check": {"q": "关于基因组和基因组学的定义，下列哪项正确？", "o": ["A. 基因组指有机体的一组完整基因，最终由DNA全序列决定", "B. 基因组学只研究单个基因的结构与功能", "C. 基因组学不依赖测序技术和生物信息学", "D. 基因组是指全部蛋白质的集合"], "a": "A", "e": "基因组是有机体的一组完整基因，最终由DNA全序列决定；基因组学从整体视角研究整个基因组。"}, "cards": [{"front": "基因组（genome）与基因组学（genomics）的定义分别是什么？", "back": "基因组：有机体的一组完整基因，最终由DNA全序列决定。基因组学：研究整个基因组结构与功能的学科，核心原理是利用测序技术获取生物体全部遗传密码，并结合生物信息学方法分析其结构、功能和变异。", "mnemonic": "基因组是“全部基因”，基因组学是“整体研究”", "useImg": false}]}, {"i": 4, "sec": "基因组学", "title": "现代基因组学三大分支 (p111)", "notes": "本页为示意图，结合上下文可概括：现代基因组学研究主要围绕三大分支展开——①结构基因组学：测定基因组全部DNA序列并解析其结构组织；②功能基因组学：研究基因功能、表达调控及相互作用；③比较基因组学：通过不同物种基因组比较揭示进化关系与保守元件。三大分支分别回答“基因组是什么”“基因做什么”“物种间有何异同”的问题，共同构成基因组学的完整框架。", "page": 111, "level": "理解", "img": "assets/img/ch04/p111.jpg", "anim": null, "fig": "示意图展示基因组学三大分支。看图时注意三个分支各自对应的研究内容与所回答的核心问题，理解'结构—功能—比较'的递进关系。", "points": ["结构基因组学：测定全部DNA序列并解析结构组织，回答'基因组是什么'", "功能基因组学：研究基因功能、表达调控及相互作用，回答'基因做什么'", "比较基因组学：物种间基因组比较揭示进化关系与保守元件，回答'物种间有何异同'", "三大分支共同构成基因组学完整框架"], "check": {"q": "现代基因组学的三大分支分别回答的问题，对应正确的是？", "o": ["A. 结构基因组学——基因做什么；功能基因组学——基因组是什么；比较基因组学——物种间有何异同", "B. 结构基因组学——基因组是什么；功能基因组学——基因做什么；比较基因组学——物种间有何异同", "C. 结构基因组学——物种间有何异同；功能基因组学——基因组是什么；比较基因组学——基因做什么", "D. 三大分支都只回答“基因组是什么”"], "a": "B", "e": "结构基因组学测定序列并解析结构组织，功能基因组学研究基因功能与调控，比较基因组学揭示物种间进化关系与保守元件。"}, "cards": [{"front": "现代基因组学的三大分支及其各自回答的问题是什么？", "back": "①结构基因组学：测定全部DNA序列并解析结构组织——回答“基因组是什么”；②功能基因组学：研究基因功能、表达调控及相互作用——回答“基因做什么”；③比较基因组学：通过物种间基因组比较揭示进化关系与保守元件——回答“物种间有何异同”。", "mnemonic": "是什么→做什么→有何异同", "useImg": false}]}, {"i": 5, "sec": "基因组学", "title": "基因组测序技术 (p112)", "notes": "基因组测序是检测有机体所有染色体DNA上核苷酸（A、C、G、T）的排列顺序。不同物种核苷酸数目和序列不同；同一物种个体间大多数序列相同，少量差异构成遗传多样性。大型真核基因组测序需要组装：先将基因组打断成小片段DNA（reads），测序后组装成重叠群（contig），再组装成较大片段（scaffold），最终完成整套染色体组装。二代测序通量高、读长短，三代测序读长长，各有优势。", "page": 112, "level": "掌握", "img": "assets/img/ch04/p112.jpg", "anim": null, "fig": null, "points": ["基因组测序：检测所有染色体DNA上A、C、G、T的排列顺序", "同一物种个体间大多数序列相同，少量差异构成遗传多样性", "组装流程：打断成reads→组装成contig→组装成scaffold→染色体组装", "二代测序通量高、读长短；三代测序读长长，各有优势"], "check": {"q": "关于基因组测序与组装，下列描述正确的是？", "o": ["A. 同一物种个体间所有序列完全相同，不存在遗传多样性", "B. 大型真核基因组测序无需组装，可直接得到完整染色体序列", "C. 测序得到的短片段称为reads，先组装成重叠群（contig），再组装成较大片段（scaffold）", "D. 二代测序读长长，三代测序读长短"], "a": "C", "e": "大型真核基因组需组装：reads→contig→scaffold→染色体；二代测序通量高读长短，三代测序读长长。"}, "cards": [{"front": "基因组测序中reads、contig、scaffold分别指什么？", "back": "reads：基因组打断后测序得到的小片段DNA序列；contig（重叠群）：reads组装成的较长连续序列；scaffold：contig进一步组装成的较大片段；最终完成整套染色体组装。", "mnemonic": "读段→重叠群→支架→染色体，逐级拼装", "useImg": false}]}, {"i": 6, "sec": "基因组学", "title": "Illumina与Nanopore测序原理 (p113)", "notes": "本页为示意图，结合上下文可概括：Illumina测序采用“边合成边测序”（sequencing by synthesis）原理，将DNA片段固定在流动池上桥式扩增形成簇，每轮加入带荧光标记的可逆终止核苷酸，拍照记录荧光信号后切除标记进入下一轮，通过逐轮信号读取碱基序列，通量高、准确度高、读长较短。Nanopore测序属于三代测序，将单链DNA穿过纳米孔，不同碱基通过时引起特征性电流变化，据此直接读取序列，读长超长、无需扩增，可检测碱基修饰，但准确率相对略低。两者互补，广泛用于基因组组装和变异检测。", "page": 113, "level": "理解", "img": "assets/img/ch04/p113.jpg", "anim": null, "fig": "示意图对比Illumina与Nanopore测序原理。看图时分别抓住'荧光信号逐轮读取'与'电流信号变化直接读序'两条主线，对比二者在读长、通量上的差异。", "points": ["Illumina：边合成边测序，桥式扩增成簇，荧光可逆终止核苷酸逐轮读取", "Illumina特点：通量高、准确度高、读长较短", "Nanopore：单链DNA穿过纳米孔，碱基引起特征性电流变化直接读序", "Nanopore属三代测序，读长长"], "check": {"q": "关于Illumina与Nanopore测序原理，下列描述正确的是？", "o": ["A. Illumina采用边合成边测序，加入带荧光标记的可逆终止核苷酸，逐轮读取信号", "B. Nanopore通过桥式扩增形成簇后拍照读取荧光信号", "C. Illumina读长超长、无需扩增，可检测碱基修饰", "D. Nanopore准确率最高、读长最短，主要用于短读长组装"], "a": "A", "e": "Illumina为边合成边测序，使用荧光标记可逆终止核苷酸；Nanopore让单链DNA穿过纳米孔，依据特征电流变化读序，读长超长。"}, "cards": [{"front": "Illumina测序与Nanopore测序的原理和特点有何不同？", "back": "Illumina：边合成边测序（SBS），流动池桥式扩增成簇，每轮加入带荧光标记的可逆终止核苷酸，拍照后切除标记进入下一轮；通量高、准确度高、读长短。Nanopore（三代）：单链DNA穿过纳米孔，不同碱基引起特征性电流变化，直接读取序列；读长长。", "mnemonic": "Illumina“拍照合成”，Nanopore“过孔测电流”", "useImg": false}]}, {"i": 7, "sec": "转录组学", "title": "转录组的定义与特点 (p114)", "notes": "转录组（transcriptome）是特定细胞、组织或生物体在一定时间和条件下产生的全部RNA转录本及其丰度。主要特点：①动态性——不同组织、发育阶段和环境条件下转录组会发生变化；②多样性——一个基因可通过可变剪接等方式产生多种RNA转录本；③组成广泛——既包括蛋白质编码RNA（mRNA），也包括多种非编码RNA（ncRNA）。转录组是连接基因组与蛋白质组的桥梁，反映基因表达状态。", "page": 114, "level": "掌握", "img": "assets/img/ch04/p114.jpg", "anim": null, "fig": null, "points": ["转录组定义：特定细胞/组织/生物体在一定时间和条件下的全部RNA转录本及丰度", "动态性：随组织、发育阶段和环境条件变化", "多样性：可变剪接使一个基因产生多种转录本", "组成广泛：包括mRNA和多种非编码RNA", "转录组是连接基因组与蛋白质组的桥梁"], "check": {"q": "关于转录组（transcriptome）的叙述，下列哪项最准确？", "o": ["A. 转录组是指某个细胞中全部DNA序列及其拷贝数", "B. 转录组是特定细胞、组织或生物体在一定时间和条件下产生的全部RNA转录本及其丰度", "C. 转录组仅包括蛋白质编码的mRNA，不包括非编码RNA", "D. 转录组在所有组织和发育阶段保持恒定不变"], "a": "B", "e": "转录组定义为特定细胞、组织或生物体在一定时间和条件下产生的全部RNA转录本及其丰度，具有动态性、多样性和组成广泛（含mRNA与ncRNA）的特点。"}, "cards": [{"front": "转录组（transcriptome）的定义及其三大特点是什么？", "back": "定义：特定细胞、组织或生物体在一定时间和条件下产生的全部RNA转录本及其丰度。特点：①动态性——不同组织、发育阶段和环境条件下会变化；②多样性——一个基因可通过可变剪接产生多种转录本；③组成广泛——包括mRNA和多种非编码RNA（ncRNA）。", "mnemonic": "动态、多样、广泛", "useImg": false}]}, {"i": 8, "sec": "转录组学", "title": "转录组学研究框架 (p115)", "notes": "本页为示意图，结合上下文可概括：转录组学研究框架通常包括：样本制备与RNA提取、文库构建、高通量测序（RNA-seq）、数据质控与比对、表达定量（如FPKM/TPM）、差异表达分析、功能富集分析（GO/KEGG）、可变剪接分析及非编码RNA分析等。其目标是在整体水平上揭示特定条件下基因表达的種類与丰度变化，为理解发育、疾病和应激等过程的分子机制提供线索。", "page": 115, "level": "理解", "img": "assets/img/ch04/p115.jpg", "anim": null, "fig": "示意图展示转录组学研究框架流程。看图时按'样本制备→测序→定量→差异与富集分析'的顺序理解各步骤的衔接关系。", "points": ["流程：RNA提取→文库构建→RNA-seq测序→质控比对→表达定量（FPKM/TPM）", "下游分析：差异表达分析、功能富集分析（GO/KEGG）", "还包括可变剪接分析及非编码RNA分析", "目标：整体水平揭示特定条件下基因表达的种类与丰度变化"], "check": {"q": "下列哪项不属于转录组学研究框架的典型环节？", "o": ["A. 样本制备与RNA提取、文库构建", "B. 高通量测序与数据质控、比对", "C. 表达定量与差异表达分析、功能富集分析", "D. 直接测定蛋白质三维结构并解析其晶体结构"], "a": "D", "e": "转录组学框架包括RNA提取、文库构建、RNA-seq、质控比对、表达定量、差异分析、功能富集、可变剪接及非编码RNA分析等，蛋白质三维结构解析不属于其典型环节。"}, "cards": [{"front": "转录组学研究框架通常包括哪些主要环节？", "back": "样本制备与RNA提取→文库构建→高通量测序（RNA-seq）→数据质控与比对→表达定量（FPKM/TPM）→差异表达分析→功能富集分析（GO/KEGG）→可变剪接分析及非编码RNA分析。", "mnemonic": "提→建→测→比→量→差→富→剪/非编码", "useImg": false}]}, {"i": 9, "sec": "转录组学", "title": "转录组学研究现状与前沿方向 (p116)", "notes": "当前转录组学前沿包括：①空间转录组学——在保留组织空间位置信息前提下测定基因表达谱，解决“基因在哪里表达”，技术如10x Visium、Stereo-seq，用于绘制组织发育和肿瘤微环境图谱；②单细胞转录组学——在单细胞分辨率研究基因表达，揭示细胞异质性、鉴定稀有细胞类型、描绘分化轨迹，技术如10x Genomics、Smart-seq2；③多组学整合——将转录组与基因组、表观组、蛋白组整合，构建完整调控网络，如CITE-seq、ATAC-seq；④全长与直接RNA测序——利用三代测序获得完整转录本并直接检测RNA修饰，如PacBio Iso-Seq、Oxford Nanopore Direct RNA-seq。", "page": 116, "level": "掌握", "img": "assets/img/ch04/p116.jpg", "anim": null, "fig": null, "points": ["空间转录组学：保留组织空间位置测定表达谱，解决'基因在哪里表达'，如10x Visium、Stereo-seq", "单细胞转录组学：单细胞分辨率揭示细胞异质性、鉴定稀有细胞类型、描绘分化轨迹，如10x Genomics、Smart-seq2", "多组学整合：转录组与基因组、表观组、蛋白组整合", "应用于组织发育图谱、肿瘤微环境等"], "check": {"q": "下列哪项最能体现空间转录组学的核心特点？", "o": ["A. 在单细胞分辨率上鉴定稀有细胞类型", "B. 在保留组织空间位置信息的前提下测定基因表达谱", "C. 将转录组与蛋白组通过CITE-seq整合", "D. 利用三代测序直接检测RNA修饰"], "a": "B", "e": "空间转录组学在保留组织空间位置信息前提下测定基因表达谱，解决“基因在哪里表达”的问题；单细胞分辨率、多组学整合和直接RNA测序属于其他前沿方向。"}, "cards": [{"front": "当前转录组学的三大前沿方向是什么？", "back": "①空间转录组学：保留组织空间位置信息测定基因表达谱，解决“基因在哪里表达”（如10x Visium、Stereo-seq）；②单细胞转录组学：单细胞分辨率研究基因表达，揭示细胞异质性、鉴定稀有细胞类型、描绘分化轨迹（如10x Genomics、Smart-seq2）；③多组学整合：转录组与基因组、表观组、蛋白组整合构建调控网络。", "mnemonic": "空间定位、单细胞分辨、多组学整合", "useImg": false}]}, {"i": 10, "sec": "组学技术与基因组学", "title": "本章结束 (p117)", "notes": "本页为“本章结束”提示页，无实质知识点。回顾本章（分子生物学方法一）内容，重点包括分子克隆、核酸杂交、PCR、测序技术以及组学与基因组学等核心方法。组学部分强调从整体水平获取和分析生物分子信息，是现代分子生物学研究的重要工具，为后续学习基因表达调控、疾病机制和系统生物学奠定方法论基础。", "page": 117, "level": "了解", "img": "assets/img/ch04/p117.jpg", "anim": null, "fig": null, "points": ["本章为结束提示页，无实质知识点", "重点回顾：分子克隆、核酸杂交、PCR、测序技术、组学与基因组学", "组学强调整体水平获取和分析生物分子信息", "为基因表达调控、疾病机制和系统生物学奠定方法论基础"], "check": {"q": "关于本章（分子生物学方法一）内容的回顾，下列哪项最恰当？", "o": ["A. 本章只介绍了PCR一种方法", "B. 本章重点包括分子克隆、核酸杂交、PCR、测序技术以及组学与基因组学等核心方法", "C. 本章组学部分强调只研究单个基因的表达", "D. 本章内容与基因表达调控和系统生物学无关"], "a": "B", "e": "本章结束页回顾本章重点包括分子克隆、核酸杂交、PCR、测序技术及组学与基因组学，组学强调从整体水平获取和分析生物分子信息。"}, "cards": [{"front": "基因组测序史上的关键里程碑（1976—2004）有哪些？", "back": "1976年第一个RNA病毒基因组（噬菌体MS2）测序；1977年Sanger完成第一个DNA基因组（噬菌体Φ-X174，5386 bp）；1995年第一个细菌基因组（流感嗜血杆菌）；1996年第一个真核生物基因组（酵母）；1998年第一个多细胞真核生物（线虫）；1999年人类22号染色体完成；2004年人类基因组序列完成。", "mnemonic": "RNA病毒→DNA病毒→细菌→酵母→线虫→人染色体→人类基因组", "useImg": false}]}, {"i": 11, "sec": "基因组学", "title": "基因组测序的历史 (p118)", "notes": "基因组测序发展历程中的里程碑：1976年第一个RNA病毒基因组（噬菌体MS2）被测序；1977年Fred Sanger完成第一个DNA基因组（噬菌体Φ-X174，5386 bp）测序；1995年第一个细菌基因组（流感嗜血杆菌）测序完成；1996年第一个真核生物基因组（酵母）测序完成；1998年第一个多细胞真核生物（线虫）基因组测序完成；1999年人类22号染色体完成；2004年人类基因组序列完成。测序技术从Sanger法到高通量测序，成本大幅下降、速度显著提升。", "page": 118, "level": "理解", "img": "assets/img/ch04/p118.jpg", "anim": null, "fig": null, "points": ["1976年第一个RNA病毒基因组（噬菌体MS2）测序", "1977年Sanger完成第一个DNA基因组（Φ-X174，5386 bp）", "1995年第一个细菌基因组（流感嗜血杆菌）", "1996年第一个真核生物基因组（酵母）；1998年第一个多细胞真核生物（线虫）", "2004年人类基因组序列完成"], "check": {"q": "下列基因组测序里程碑对应关系正确的是？", "o": ["A. 1977年Sanger完成第一个DNA基因组（噬菌体Φ-X174）测序", "B. 1995年完成第一个真核生物（酵母）基因组测序", "C. 1998年完成人类基因组序列", "D. 1976年完成第一个细菌基因组测序"], "a": "A", "e": "1977年Sanger完成噬菌体Φ-X174（5386 bp）第一个DNA基因组测序；1995年为第一个细菌基因组，1996年为酵母，1998年为线虫，2004年人类基因组序列完成。"}, "cards": [{"front": "为什么说流感嗜血杆菌（1995）的测序是全基因组鸟枪法的重要里程碑？", "back": "它是第一个全基因组测序的自由生活生物（1,830,137 bp），标志着全基因组鸟枪法测序策略的成功应用，为后续大规模基因组测序奠定了基础。", "mnemonic": "第一个“自由生活”生物全基因组", "useImg": false}]}, {"i": 12, "sec": "基因组学", "title": "基因组测序里程碑项目 (p119)", "notes": "本页以表格列出基因组测序史上的标志性项目：1976年噬菌体MS2（3,569 nt）为第一个完整测序的RNA基因组；1977年噬菌体ΦX174（约5,386 nt）为第一个DNA基因组，并揭示重叠基因；1995年流感嗜血杆菌（1,830,137 bp）为第一个全基因组测序的自由生活生物，是全基因组鸟枪法的重要里程碑；1996年酿酒酵母（约12.1 Mb）为第一个真核生物；1998年线虫（约97 Mb）为第一个多细胞动物；2000年拟南芥（约120 Mb）为第一个植物基因组；2001年人类基因组工作草图（约3.2 Gb）发表；2004年人类基因组完成常染色质序列（2.85 Gb组装）。（注：PPT p119表记ΦX174约5,375 nt，p118及常用值为5,386 nt；此处采用5,386 nt，表格数字可视为笔误。）", "page": 119, "level": "理解", "img": "assets/img/ch04/p119.jpg", "anim": null, "fig": null, "points": ["1976年MS2（3,569 nt）：第一个完整测序的RNA基因组", "1977年ΦX174（约5,386 nt）：第一个DNA基因组，揭示重叠基因", "1995年流感嗜血杆菌（1,830,137 bp）：第一个全基因组测序的自由生活生物，全基因组鸟枪法里程碑", "1996年酿酒酵母（约12.1 Mb）：第一个真核生物", "1998年线虫：第一个多细胞真核生物"], "check": {"q": "根据基因组测序里程碑项目表，下列叙述正确的是？", "o": ["A. 1976年噬菌体MS2是第一个完整测序的DNA基因组", "B. 1977年噬菌体ΦX174是第一个DNA基因组，并揭示重叠基因", "C. 1995年流感嗜血杆菌是第一个真核生物基因组", "D. 2000年拟南芥是第一个多细胞动物基因组"], "a": "B", "e": "1976年MS2为第一个完整测序的RNA基因组；1977年ΦX174为第一个DNA基因组并揭示重叠基因；1995年流感嗜血杆菌为第一个全基因组测序的自由生活生物；2000年拟南芥为第一个植物基因组。"}, "cards": [{"front": "“灵长类基因组计划”于何时发表？由谁牵头？发布了多少种灵长类基因组数据？", "back": "2023年6月2日《科学》杂志发表一组8篇论文，由中国科学家牵头发起、多国科学家共同参与，共发布27种灵长类动物基因组数据，为理解灵长类进化、人类起源与疾病模型研究提供宝贵资源。", "mnemonic": "2023·6·2，中国牵头，27种灵长类", "useImg": false}]}, {"i": 13, "sec": "基因组学", "title": "灵长类基因组计划 (p120)", "notes": "2023年6月2日，《科学》杂志发表一组8篇论文，公布由中国科学家牵头发起、多国科学家共同参与的“灵长类基因组计划”重大进展，共发布27种灵长类动物基因组数据。图中展示蜂猴、滇金丝猴、川金丝猴、白颊长臂猿、山魈、环尾狐猴等物种。该计划为理解灵长类进化、人类起源与疾病模型研究提供了宝贵资源，也体现了中国科学家在基因组学领域的国际贡献。", "page": 120, "level": "了解", "img": "assets/img/ch04/p120.jpg", "anim": null, "fig": null, "points": ["2023年6月《科学》发表8篇论文，中国科学家牵头发起、多国参与", "发布27种灵长类动物基因组数据", "展示蜂猴、滇金丝猴、川金丝猴、白颊长臂猿、山魈、环尾狐猴等物种", "为灵长类进化、人类起源与疾病模型研究提供宝贵资源"], "check": {"q": "关于2023年公布的“灵长类基因组计划”，下列叙述正确的是？", "o": ["A. 由单一国家独立完成，未开展国际合作", "B. 由中国科学家牵头发起、多国科学家共同参与，共发布27种灵长类动物基因组数据", "C. 该计划仅公布了人类基因组数据", "D. 该计划发表于《自然》杂志，共8篇论文"], "a": "B", "e": "2023年6月2日《科学》杂志发表8篇论文，公布由中国科学家牵头发起、多国科学家共同参与的灵长类基因组计划进展，共发布27种灵长类动物基因组数据。"}, "cards": [{"front": "已测序最大动物基因组是哪种生物？其基因组大小和重复序列占比如何？说明了什么？", "back": "南美肺鱼，基因组约91 Gb，约为人类基因组的30倍，其中约90%为重复序列，主要源于转座元件大量扩增和重复序列积累。说明基因组大小与生物复杂性并不成正比，重复序列在基因组演化中具有重要作用。", "mnemonic": "肺鱼91 Gb、90%重复——大不等于复杂", "useImg": false}]}, {"i": 14, "sec": "基因组学", "title": "已测序最大动物基因组——南美肺鱼 (p121)", "notes": "2024年已测序基因组中，南美肺鱼体长可超过1米，是现存肺鱼的重要代表，也是研究脊椎动物从水生向陆生演化的重要物种。它拥有目前已测序最大的动物基因组，大小约91 Gb，约为人类基因组的30倍，其中约90%为重复序列。如此巨大的基因组主要源于转座元件的大量扩增和重复序列的积累。（延伸结论）基因组大小与生物复杂性并不成正比，重复序列在基因组演化中具有重要作用。（注：PPT此页“南美飞肺鱼——地球上生物量最大的动物”有误；这里是已测序最大动物基因组。）", "page": 121, "level": "了解", "img": "assets/img/ch04/p121.jpg", "anim": null, "fig": null, "points": ["南美肺鱼是研究脊椎动物水生向陆生演化的重要物种", "拥有已测序最大动物基因组，约91 Gb，约为人类基因组30倍", "约90%为重复序列，主要源于转座元件扩增和重复序列积累", "（延伸）基因组大小与生物复杂性不成正比，重复序列在演化中具重要作用"], "check": {"q": "关于南美肺鱼基因组，下列哪项描述正确？", "o": ["A. 其基因组约91 Gb，约为人类基因组的30倍，约90%为重复序列", "B. 其基因组约9.1 Gb，与人类基因组大小相近", "C. 其基因组虽大，但重复序列比例很低，不足10%", "D. 其基因组大小与生物复杂性呈明显正相关"], "a": "A", "e": "南美肺鱼拥有目前已测序最大的动物基因组，约91 Gb，约为人类基因组的30倍，其中约90%为重复序列；该案例说明基因组大小与生物复杂性并不成正比。"}, "cards": [{"front": "地球生物物种数量概览：已知物种约多少？推测真核生物约多少种？", "back": "现代科学发现的物种约222万种；推测世界上可能有约870万种真核生物。已知植物约34.5万种；哺乳动物4300种、鸟类约8000种、爬行动物6000种、两栖动物3500种、鱼类2.3万种。说明已测序基因组仅覆盖极小部分物种，基因组学仍有广阔探索空间。", "mnemonic": "已知222万，推测870万——测序路还长", "useImg": false}]}, {"i": 15, "sec": "基因组学", "title": "地球生物物种数量概览 (p122)", "notes": "本页介绍地球生物多样性：全球已知植物约34.5万种；已知动物中哺乳动物4300种、鸟类约8000种、爬行动物6000种、两栖动物3500种、鱼类2.3万种；现代科学发现的物种约222万种；推测世界上可能有约870万种真核生物。这说明已测序基因组仅覆盖极小部分物种，基因组学仍有广阔探索空间，也凸显了生物多样性保护和基因组资源积累的重要性。", "page": 122, "level": "了解", "img": "assets/img/ch04/p122.jpg", "anim": null, "fig": null, "points": ["已知植物约34.5万种；哺乳动物4300种、鸟类约8000种、爬行动物6000种、两栖动物3500种、鱼类2.3万种", "现代科学发现物种约222万种", "推测真核生物可能约870万种", "已测序基因组仅覆盖极小部分物种，基因组学探索空间广阔"], "check": {"q": "按照该页给出的数据，下列哪项正确？", "o": ["A. 全球已知植物约34.5万种，推测真核生物可能约870万种", "B. 现代科学发现的物种约870万种，已知植物约222万种", "C. 已知哺乳动物约2.3万种，鱼类约4300种", "D. 已测序基因组已覆盖地球上大部分真核生物物种"], "a": "A", "e": "该页指出全球已知植物约34.5万种，现代科学发现物种约222万种，推测真核生物可能约870万种；已测序基因组仅覆盖极小部分物种。"}, "cards": null}], "mcq": [{"id": "ch04_mcq_36", "mod": "模块八：组学技术与基因组学", "modI": 7, "q": "下列哪一组学主要研究特定条件下细胞中所有RNA转录本的种类和数量？", "o": ["A. 基因组学", "B. 转录组学", "C. 蛋白质组学", "D. 代谢组学"], "a": "B", "e": "转录组学（Transcriptomics）研究特定条件下细胞中所有RNA转录本（特别是mRNA）的种类和数量；基因组学研究DNA，蛋白质组学研究蛋白质，代谢组学研究小分子代谢物。", "kp": "ch04_s7_1"}, {"id": "ch04_mcq_37", "mod": "模块八：组学技术与基因组学", "modI": 7, "q": "组学研究技术路线中，被认为是核心步骤的是？", "o": ["A. 样本制备与数据采集", "B. 数据处理与生物信息学分析", "C. 整合分析", "D. 验证与机制研究"], "a": "B", "e": "数据处理与生物信息学分析是组学研究的核心步骤，包括序列比对/组装、定量与比较、功能富集分析等；样本制备是前提，整合分析和验证是后续深化。", "kp": "ch04_s7_2"}, {"id": "ch04_mcq_38", "mod": "模块八：组学技术与基因组学", "modI": 7, "q": "关于基因组测序组装，下列描述正确的是？", "o": ["A. reads直接组装成完整染色体", "B. contig由scaffold进一步打断产生", "C. 先将基因组打断成小片段测序得到reads，再组装成contig和scaffold", "D. 真核基因组无需组装即可直接测序"], "a": "C", "e": "大型真核基因组测序需先将基因组打断成小片段DNA（reads），测序后组装成重叠群（contig），再组装成较大片段（scaffold），最终完成染色体组装。", "kp": "ch04_s7_5"}, {"id": "ch04_mcq_39", "mod": "模块八：组学技术与基因组学", "modI": 7, "q": "下列哪项技术可在保留组织空间位置信息的前提下测定基因表达谱？", "o": ["A. 单细胞转录组学（10x Genomics）", "B. 空间转录组学（10x Visium）", "C. CITE-seq", "D. Oxford Nanopore Direct RNA-seq"], "a": "B", "e": "空间转录组学（如10x Visium、Stereo-seq）在保留组织空间位置信息的前提下测定基因表达谱，解决“基因在哪里表达”的问题；单细胞转录组学丢失空间信息。", "kp": "ch04_s7_9"}, {"id": "ch04_mcq_40", "mod": "模块八：组学技术与基因组学", "modI": 7, "q": "目前已被测序的最大动物基因组——南美肺鱼，其基因组大小约为多少？", "o": ["A. 3.2 Gb", "B. 12.1 Mb", "C. 91 Gb", "D. 120 Mb"], "a": "C", "e": "南美肺鱼基因组大小约91 Gb，约为人类基因组的30倍，其中约90%为重复序列，主要源于转座元件扩增和重复序列积累。", "kp": "ch04_s7_14"}], "judge": [], "fill": [], "short": [], "calc": [], "term": []}], "mcq": [{"id": "ch04_mcq_1", "mod": "模块一：方法总览与核酸凝胶电泳", "modI": 0, "q": "关于琼脂糖凝胶与聚丙烯酰胺凝胶的比较，下列叙述正确的是：", "o": ["A. 琼脂糖分辨率高，可区分相差一个碱基的DNA片段", "B. 聚丙烯酰胺分离范围宽，可分离数十kb的DNA", "C. 琼脂糖分辨率较低，但可分离几百bp至数十kb的DNA", "D. 两者分辨率相同，仅孔径不同"], "a": "C", "e": "琼脂糖分辨率较低但分离范围宽，可分离几百bp至数十kb的DNA；聚丙烯酰胺分辨率高但分离范围窄，仅适合1至几百bp。", "kp": "ch04_s0_5"}, {"id": "ch04_mcq_2", "mod": "模块一：方法总览与核酸凝胶电泳", "modI": 0, "q": "脉冲场凝胶电泳（PFGE）能够有效分离大分子DNA的主要原因是：", "o": ["A. 使用更高浓度的琼脂糖凝胶", "B. 电场方向以脉冲形式周期性改变，使DNA分子反复重定向", "C. 加入溴化乙锭使DNA带正电", "D. 将DNA先切成小片段再电泳"], "a": "B", "e": "PFGE通过周期性改变电场方向，小分子转向快、迁移快，大分子转向困难、迁移慢，从而分离10kb至10Mb的大分子DNA。", "kp": "ch04_s0_10"}, {"id": "ch04_mcq_3", "mod": "模块一：方法总览与核酸凝胶电泳", "modI": 0, "q": "DNA在凝胶电泳中向正极迁移的直接原因是：", "o": ["A. DNA分子带有正电荷", "B. DNA分子中的磷酸骨架带负电荷", "C. 凝胶基质带正电荷", "D. 荧光染料使DNA带负电"], "a": "B", "e": "DNA的磷酸骨架带负电荷，在电场中向正极迁移；凝胶网络对较长分子的阻滞更强，从而实现按大小分离。", "kp": "ch04_s0_3"}, {"id": "ch04_mcq_4", "mod": "模块一：方法总览与核酸凝胶电泳", "modI": 0, "q": "RNA电泳前常用乙二醛等试剂处理，其目的是：", "o": ["A. 使RNA带上正电荷", "B. 将RNA降解为小片段", "C. 破坏RNA的二级和三级结构，使迁移率与分子量成正比", "D. 使RNA与DNA分离"], "a": "C", "e": "单链RNA易形成高级结构而影响迁移率，乙二醛等变性试剂可消除高级结构，使RNA迁移率约与分子量成正比。", "kp": "ch04_s0_14"}, {"id": "ch04_mcq_5", "mod": "模块一：方法总览与核酸凝胶电泳", "modI": 0, "q": "在凝胶电泳中，超螺旋DNA、线性DNA和开环/切口环状DNA的迁移速度由快到慢一般为：", "o": ["A. 开环环状DNA > 线性DNA > 超螺旋DNA", "B. 线性DNA > 超螺旋DNA > 开环环状DNA", "C. 超螺旋DNA > 线性DNA > 开环环状DNA", "D. 三者迁移速度相同"], "a": "C", "e": "超螺旋DNA结构最紧凑，迁移最快；开环/切口环状DNA最松散，迁移最慢；线性DNA居中。", "kp": "ch04_s0_3"}, {"id": "ch04_mcq_6", "mod": "模块二：蛋白质电泳与层析", "modI": 1, "q": "在SDS-PAGE中，蛋白质的迁移率主要取决于下列哪一因素？", "o": ["A. 蛋白质的等电点", "B. 蛋白质的分子量", "C. 蛋白质的疏水性", "D. 蛋白质的二级结构"], "a": "B", "e": "SDS使蛋白质变性并带上均匀负电荷，消除了电荷差异，因此迁移率主要与分子量相关，分子量越小迁移越快。", "kp": "ch04_s1_0"}, {"id": "ch04_mcq_7", "mod": "模块二：蛋白质电泳与层析", "modI": 1, "q": "Western blotting中，一抗的作用是：", "o": ["A. 将蛋白质从凝胶转移到膜上", "B. 封闭膜上的非特异性结合位点", "C. 特异性识别并结合目标蛋白", "D. 催化显色反应"], "a": "C", "e": "一抗特异性识别目标蛋白，二抗携带酶或荧光基团用于检测；转膜、封闭和显色分别由其他步骤或试剂完成。", "kp": "ch04_s1_2"}, {"id": "ch04_mcq_8", "mod": "模块二：蛋白质电泳与层析", "modI": 1, "q": "关于DEAE-Sephadex离子交换层析，下列说法正确的是：", "o": ["A. 它带负电荷，结合带正电的蛋白质", "B. 它带正电荷，结合带负电的蛋白质", "C. 它按分子大小分离蛋白质", "D. 它利用抗原抗体亲和力纯化蛋白质"], "a": "B", "e": "DEAE-Sephadex为阴离子交换剂，带正电荷，可结合带负电荷的蛋白质；按大小分离是凝胶过滤，亲和纯化是亲和层析。", "kp": "ch04_s1_3"}, {"id": "ch04_mcq_9", "mod": "模块二：蛋白质电泳与层析", "modI": 1, "q": "凝胶过滤层析中，最先被洗脱出来的是：", "o": ["A. 分子量最大的蛋白质", "B. 分子量最小的蛋白质", "C. 带正电荷最多的蛋白质", "D. 疏水性最强的蛋白质"], "a": "A", "e": "大分子不能进入凝胶珠孔隙，被排阻在珠外，路径短，因此最先洗脱；小分子进入孔隙，路径长，洗脱较慢。", "kp": "ch04_s1_5"}, {"id": "ch04_mcq_10", "mod": "模块二：蛋白质电泳与层析", "modI": 1, "q": "镍亲和层析纯化融合蛋白所依据的原理是：", "o": ["A. 寡聚组氨酸标签与Ni2+的高亲和结合", "B. 蛋白质与Ni2+的离子交换作用", "C. 蛋白质分子大小差异", "D. 蛋白质等电点差异"], "a": "A", "e": "融合蛋白中的寡聚组氨酸标签（His-tag）与固定化Ni2+形成高亲和配位结合，从而实现特异性纯化，属于亲和层析。", "kp": "ch04_s1_6"}, {"id": "ch04_mcq_11", "mod": "模块三：分子杂交（探针·Southern/Northern·FISH）", "modI": 2, "q": "下列关于核酸分子杂交的叙述，正确的是：", "o": ["A. 杂交是两条同源双链DNA之间通过共价键结合的过程", "B. 杂交是互补单链核酸在合适离子强度和温度下通过碱基配对结合的过程", "C. 杂交只能在放射性标记条件下发生", "D. 杂交过程中探针必须与目标序列完全相同才能结合"], "a": "B", "e": "分子杂交的本质是互补单链核酸在合适离子强度和温度下通过碱基互补配对形成双链，不涉及共价键，也不依赖标记类型；探针与目标序列互补即可，无需完全相同。", "kp": "ch04_s2_0"}, {"id": "ch04_mcq_12", "mod": "模块三：分子杂交（探针·Southern/Northern·FISH）", "modI": 2, "q": "Southern blot hybridization 的基本流程是：", "o": ["A. 提取RNA→电泳→转膜→探针杂交→检测", "B. DNA酶切→电泳→变性→转膜→封闭→探针杂交→检测", "C. 固定细胞→变性→探针杂交→荧光成像", "D. PCR扩增→直接测序→比对"], "a": "B", "e": "Southern印迹检测DNA：先酶切和电泳分离，碱性变性后转膜，封闭后与标记探针杂交并检测。A为Northern印迹，C为FISH，D不是杂交检测流程。", "kp": "ch04_s2_5"}, {"id": "ch04_mcq_13", "mod": "模块三：分子杂交（探针·Southern/Northern·FISH）", "modI": 2, "q": "关于探针标记物与检测方式，下列配对错误的是：", "o": ["A. ³²P——X光胶片自显影", "B. 地高辛——抗DIG抗体结合酶促显色或化学发光", "C. 生物素——利用生物素与链霉亲和素的高亲和力检测", "D. Cy3——必须通过抗Cy3抗体酶促显色检测"], "a": "D", "e": "Cy3、Cy5、FAM等为荧光标记，可直接进行荧光检测，不需要抗体酶促显色；A、B、C的配对均正确。", "kp": "ch04_s2_3"}, {"id": "ch04_mcq_14", "mod": "模块三：分子杂交（探针·Southern/Northern·FISH）", "modI": 2, "q": "Northern blotting 与 Southern blotting 的主要区别是：", "o": ["A. Northern检测RNA，条带强度反映特定RNA的相对量", "B. Northern不需要电泳分离", "C. Northern不使用探针杂交", "D. Northern只能检测DNA突变"], "a": "A", "e": "Northern印迹与Southern流程类似，但分离和检测对象是RNA，杂交条带强度反映特定RNA的相对含量，用于基因转录活性分析；它仍需电泳、转膜和探针杂交。", "kp": "ch04_s2_10"}, {"id": "ch04_mcq_15", "mod": "模块三：分子杂交（探针·Southern/Northern·FISH）", "modI": 2, "q": "荧光原位杂交（FISH）的主要特点是：", "o": ["A. 必须先把DNA提取出来再电泳转膜", "B. 无需核酸提取，可在固定细胞中原位保留目标核酸的空间位置信息", "C. 只能用于检测RNA含量", "D. 探针不需要标记"], "a": "B", "e": "FISH对固定细胞中的DNA变性后直接与标记探针杂交并荧光成像，无需提取核酸，能保留目标序列在染色体或细胞核中的空间位置，常用于染色体定位和染色质三维组织研究。", "kp": "ch04_s2_11"}, {"id": "ch04_mcq_16", "mod": "模块四：PCR与衍生技术", "modI": 3, "q": "PCR反应中使用的热稳定DNA聚合酶最常用的是：", "o": ["A. DNA聚合酶I", "B. Taq聚合酶", "C. 逆转录酶", "D. RNA聚合酶"], "a": "B", "e": "Taq聚合酶是从嗜热菌Thermus aquaticus中分离的热稳定DNA聚合酶，能在高温（约72℃）下保持活性，是PCR反应中最常用的聚合酶。", "kp": "ch04_s3_1"}, {"id": "ch04_mcq_17", "mod": "模块四：PCR与衍生技术", "modI": 3, "q": "在实时荧光定量PCR中，Ct值的定义是：", "o": ["A. 荧光信号达到最大值时的循环数", "B. 荧光信号达到设定阈值时所对应的循环数", "C. PCR反应结束时的总循环数", "D. 模板DNA开始扩增时的循环数"], "a": "B", "e": "Ct值（循环阈值）是指荧光信号达到预先设定的荧光阈值时所对应的循环数，与起始模板量的对数呈线性关系，是qPCR定量的核心参数。", "kp": "ch04_s3_9"}, {"id": "ch04_mcq_18", "mod": "模块四：PCR与衍生技术", "modI": 3, "q": "下列哪种PCR技术用于扩增已知序列两侧的未知序列？", "o": ["A. RT-PCR", "B. 原位PCR", "C. 反向PCR", "D. 不对称PCR"], "a": "C", "e": "反向PCR通过限制性内切酶消化和自身环化，使已知序列两侧的未知序列被扩增，适用于获取已知序列侧翼的未知区域。", "kp": "ch04_s3_5"}, {"id": "ch04_mcq_19", "mod": "模块四：PCR与衍生技术", "modI": 3, "q": "在RT-PCR中，Oligo(dT)引物的作用是：", "o": ["A. 随机结合所有RNA", "B. 特异性识别mRNA的Poly(A)尾", "C. 只逆转录目标基因", "D. 结合rRNA"], "a": "B", "e": "Oligo(dT)引物专门识别mRNA的Poly(A)尾，优先逆转录带Poly(A)尾的真核mRNA，适合常规mRNA分析，不适用于无Poly(A)尾的RNA。", "kp": "ch04_s3_6"}, {"id": "ch04_mcq_20", "mod": "模块四：PCR与衍生技术", "modI": 3, "q": "不对称PCR的主要用途是：", "o": ["A. 定量分析基因表达", "B. 制备单链DNA用于测序或杂交探针", "C. 检测组织细胞中微量DNA", "D. 扩增未知序列"], "a": "B", "e": "不对称PCR采用不等量引物，限制性引物消耗完后，非限制性引物继续引导合成大量单链DNA，主要用于制备核酸测序模板和杂交探针。", "kp": "ch04_s3_18"}, {"id": "ch04_mcq_21", "mod": "模块五：基因克隆（酶·载体·文库·筛选）", "modI": 4, "q": "基因克隆过程中，将外源DNA片段插入载体形成重组DNA分子所需要的酶是：", "o": ["A. 限制性内切酶和DNA连接酶", "B. DNA聚合酶和RNA聚合酶", "C. 逆转录酶和核酸酶", "D. 解旋酶和拓扑异构酶"], "a": "A", "e": "形成重组DNA需要限制性内切酶切割DNA、DNA连接酶连接片段，二者是基因克隆中“切”和“接”的关键工具。", "kp": "ch04_s4_1"}, {"id": "ch04_mcq_22", "mod": "模块五：基因克隆（酶·载体·文库·筛选）", "modI": 4, "q": "关于限制性内切酶识别序列长度与切割频率的关系，正确的是：", "o": ["A. 识别序列越长，切割频率越高", "B. 识别序列越短，切割频率越低", "C. 识别序列越长，切割频率越低", "D. 切割频率与识别序列长度无关"], "a": "C", "e": "识别序列越长，其在基因组中出现的概率越低，切割频率越低。如4 bp约每256 bp切一次，8 bp约每65 kb切一次。", "kp": "ch04_s4_7"}, {"id": "ch04_mcq_23", "mod": "模块五：基因克隆（酶·载体·文库·筛选）", "modI": 4, "q": "pUC18载体中多克隆位点（MCS）位于lacZ'基因内部，外源DNA插入后利用X-gal进行筛选，重组克隆应呈现：", "o": ["A. 蓝色菌落", "B. 白色菌落", "C. 红色菌落", "D. 绿色菌落"], "a": "B", "e": "外源DNA插入MCS会破坏lacZ'阅读框，β-半乳糖苷酶失活，不能水解X-gal产生蓝色产物，因此重组克隆为白色菌落。", "kp": "ch04_s4_10"}, {"id": "ch04_mcq_24", "mod": "模块五：基因克隆（酶·载体·文库·筛选）", "modI": 4, "q": "与基因组文库相比，cDNA文库的特点是：", "o": ["A. 包含全部基因组DNA序列", "B. 只包含表达基因的序列，不含内含子", "C. 由总基因组DNA经限制酶切割构建", "D. 每个克隆都含完整基因"], "a": "B", "e": "cDNA文库以mRNA为模板逆转录合成cDNA，只代表表达基因，不含内含子和调控序列，适用于克隆编码特定蛋白的基因。", "kp": "ch04_s4_21"}, {"id": "ch04_mcq_25", "mod": "模块五：基因克隆（酶·载体·文库·筛选）", "modI": 4, "q": "表达载体区别于一般克隆载体的关键特征是：", "o": ["A. 含复制起点", "B. 含选择标记", "C. 含多克隆位点", "D. 含启动子和终止子等表达调控元件"], "a": "D", "e": "表达载体除具备复制起点、选择标记和多克隆位点外，还必须含启动子和终止子等转录调控元件，插入基因还需有起始密码子、终止密码子和正确阅读框才能表达。", "kp": "ch04_s4_15"}, {"id": "ch04_mcq_26", "mod": "模块六：克隆基因的表达", "modI": 5, "q": "在原核表达中，将目标蛋白与六个组氨酸标签融合的主要目的是什么？", "o": ["A. 提高目标蛋白的转录水平", "B. 便于通过镍亲和层析纯化目标蛋白", "C. 使目标蛋白发生糖基化修饰", "D. 促进目标蛋白形成包涵体"], "a": "B", "e": "寡聚组氨酸标签对镍离子有高亲和力，可用镍亲和层析纯化融合蛋白。", "kp": "ch04_s5_4"}, {"id": "ch04_mcq_27", "mod": "模块六：克隆基因的表达", "modI": 5, "q": "关于诱导型启动子的作用，下列叙述正确的是？", "o": ["A. 在未诱导时关闭克隆基因表达，减少对宿主生长的影响", "B. 持续高水平表达外源基因，不受诱导条件控制", "C. 仅存在于真核表达载体中", "D. 可自动切除融合标签"], "a": "A", "e": "诱导型启动子位于克隆基因上游，未诱导时关闭表达，诱导后开启，可减少过早表达对细菌生长的影响，尤其当外源蛋白有毒性时。", "kp": "ch04_s5_9"}, {"id": "ch04_mcq_28", "mod": "模块六：克隆基因的表达", "modI": 5, "q": "下列哪种启动子受阿拉伯糖诱导？", "o": ["A. lac启动子", "B. trc启动子", "C. PBAD启动子", "D. PL启动子"], "a": "C", "e": "PBAD启动子受阿拉伯糖诱导；lac和trc受IPTG诱导，PL受温度诱导。", "kp": "ch04_s5_9"}, {"id": "ch04_mcq_29", "mod": "模块六：克隆基因的表达", "modI": 5, "q": "外源基因在大肠杆菌中高水平表达时，常形成的不溶性、无活性蛋白聚集体称为什么？", "o": ["A. 融合蛋白", "B. 包涵体", "C. 组氨酸标签", "D. 复性体"], "a": "B", "e": "包涵体是外源基因高水平表达时形成的不溶性、无活性蛋白聚集体，需经变性溶解和复性重折叠才能获得有生物活性的蛋白。", "kp": "ch04_s5_8"}, {"id": "ch04_mcq_30", "mod": "模块六：克隆基因的表达", "modI": 5, "q": "与大肠杆菌表达系统相比，真核表达系统的主要优势是什么？", "o": ["A. 表达速度更快且成本更低", "B. 蛋白倾向于正确折叠并可进行糖基化等翻译后修饰", "C. 不需要任何筛选标记", "D. 只能表达原核基因"], "a": "B", "e": "真核表达系统可使蛋白正确折叠，并进行磷酸化、糖基化等真核特有的翻译后修饰，更适合表达复杂真核蛋白。", "kp": "ch04_s5_11"}, {"id": "ch04_mcq_31", "mod": "模块七：基因操作（过表达·RNAi·CRISPR）", "modI": 6, "q": "下列哪项属于“功能缺失（loss of function）”研究策略？", "o": ["A. 将目标基因克隆到强启动子下游过表达", "B. 用RNAi降低目标基因表达", "C. 用报告基因标记内源基因", "D. 用HDR引入点突变以增强蛋白活性"], "a": "B", "e": "RNAi通过降解mRNA降低表达，属于功能缺失；过表达为功能获得，报告基因标记和HDR增强活性不属于功能缺失。", "kp": "ch04_s6_1"}, {"id": "ch04_mcq_32", "mod": "模块七：基因操作（过表达·RNAi·CRISPR）", "modI": 6, "q": "RNA干扰中，与靶mRNA碱基配对并抑制其翻译或促其降解的关键复合体是？", "o": ["A. 剪接体", "B. RISC", "C. 核糖体大亚基", "D. 蛋白酶体"], "a": "B", "e": "dsRNA被Dicer切割为siRNA后组装进RISC，由RISC识别并切割靶mRNA，实现特异性基因沉默。", "kp": "ch04_s6_3"}, {"id": "ch04_mcq_33", "mod": "模块七：基因操作（过表达·RNAi·CRISPR）", "modI": 6, "q": "CRISPR/Cas9切割产生双链断裂后，在无修复模板情况下主要发生的修复方式是？", "o": ["A. 同源定向修复（HDR）", "B. 非同源末端连接（NHEJ）", "C. 碱基切除修复（BER）", "D. 错配修复（MMR）"], "a": "B", "e": "无模板时细胞主要走NHEJ，产生随机插入/缺失，可用于构建功能性敲除细胞系；提供模板时才走HDR。", "kp": "ch04_s6_5"}, {"id": "ch04_mcq_34", "mod": "模块七：基因操作（过表达·RNAi·CRISPR）", "modI": 6, "q": "关于SpCas9识别的PAM序列，正确的是？", "o": ["A. TTTV", "B. NNGRRT", "C. NGG", "D. GAA"], "a": "C", "e": "SpCas9来源于化脓链球菌，识别NGG；TTTV为Cas12a，NNGRRT为SaCas9，GAA为工程化变体放宽后的PAM。", "kp": "ch04_s6_7"}, {"id": "ch04_mcq_35", "mod": "模块七：基因操作（过表达·RNAi·CRISPR）", "modI": 6, "q": "检测RNAi敲低效率时，最直接且常用的方法是？", "o": ["A. 提取RNA反转录后进行Realtime PCR检测靶基因mRNA水平", "B. 直接进行Western blot检测DNA含量", "C. 用CRISPR敲除该基因", "D. 用HDR引入报告基因"], "a": "A", "e": "RNAi主要降低mRNA并影响蛋白，提取RNA反转录后qPCR检测mRNA水平是评估敲低效率的常用直接方法。", "kp": "ch04_s6_4"}, {"id": "ch04_mcq_36", "mod": "模块八：组学技术与基因组学", "modI": 7, "q": "下列哪一组学主要研究特定条件下细胞中所有RNA转录本的种类和数量？", "o": ["A. 基因组学", "B. 转录组学", "C. 蛋白质组学", "D. 代谢组学"], "a": "B", "e": "转录组学（Transcriptomics）研究特定条件下细胞中所有RNA转录本（特别是mRNA）的种类和数量；基因组学研究DNA，蛋白质组学研究蛋白质，代谢组学研究小分子代谢物。", "kp": "ch04_s7_1"}, {"id": "ch04_mcq_37", "mod": "模块八：组学技术与基因组学", "modI": 7, "q": "组学研究技术路线中，被认为是核心步骤的是？", "o": ["A. 样本制备与数据采集", "B. 数据处理与生物信息学分析", "C. 整合分析", "D. 验证与机制研究"], "a": "B", "e": "数据处理与生物信息学分析是组学研究的核心步骤，包括序列比对/组装、定量与比较、功能富集分析等；样本制备是前提，整合分析和验证是后续深化。", "kp": "ch04_s7_2"}, {"id": "ch04_mcq_38", "mod": "模块八：组学技术与基因组学", "modI": 7, "q": "关于基因组测序组装，下列描述正确的是？", "o": ["A. reads直接组装成完整染色体", "B. contig由scaffold进一步打断产生", "C. 先将基因组打断成小片段测序得到reads，再组装成contig和scaffold", "D. 真核基因组无需组装即可直接测序"], "a": "C", "e": "大型真核基因组测序需先将基因组打断成小片段DNA（reads），测序后组装成重叠群（contig），再组装成较大片段（scaffold），最终完成染色体组装。", "kp": "ch04_s7_5"}, {"id": "ch04_mcq_39", "mod": "模块八：组学技术与基因组学", "modI": 7, "q": "下列哪项技术可在保留组织空间位置信息的前提下测定基因表达谱？", "o": ["A. 单细胞转录组学（10x Genomics）", "B. 空间转录组学（10x Visium）", "C. CITE-seq", "D. Oxford Nanopore Direct RNA-seq"], "a": "B", "e": "空间转录组学（如10x Visium、Stereo-seq）在保留组织空间位置信息的前提下测定基因表达谱，解决“基因在哪里表达”的问题；单细胞转录组学丢失空间信息。", "kp": "ch04_s7_9"}, {"id": "ch04_mcq_40", "mod": "模块八：组学技术与基因组学", "modI": 7, "q": "目前已被测序的最大动物基因组——南美肺鱼，其基因组大小约为多少？", "o": ["A. 3.2 Gb", "B. 12.1 Mb", "C. 91 Gb", "D. 120 Mb"], "a": "C", "e": "南美肺鱼基因组大小约91 Gb，约为人类基因组的30倍，其中约90%为重复序列，主要源于转座元件扩增和重复序列积累。", "kp": "ch04_s7_14"}], "judge": [{"id": "ch04_judge_1", "modI": 0, "q": "琼脂糖凝胶的分辨率高于聚丙烯酰胺凝胶，可区分仅相差一个碱基的DNA片段。", "a": "错", "e": "琼脂糖凝胶分辨率较低，但分离范围宽；聚丙烯酰胺凝胶分辨率高，可区分仅相差一个碱基的DNA片段，但分离范围窄。", "kp": "ch04_s0_8"}, {"id": "ch04_judge_2", "modI": 0, "q": "在凝胶电泳中，超螺旋DNA比开环或切口环状DNA迁移更快。", "a": "对", "e": "超螺旋DNA结构最紧凑，在凝胶网络中迁移最快；开环或切口环状DNA较松散，迁移最慢；线性DNA居中。", "kp": "ch04_s0_3"}, {"id": "ch04_judge_3", "modI": 1, "q": "SDS-PAGE中蛋白质的迁移率主要取决于其天然电荷和形状。", "a": "错", "e": "SDS使蛋白质变性并带上均匀负电荷，因此迁移率主要取决于分子量；非变性电泳才保留天然构象，迁移率受电荷、形状和大小共同影响。", "kp": "ch04_s1_0"}, {"id": "ch04_judge_4", "modI": 1, "q": "凝胶过滤层析中，大分子被排阻在凝胶珠外，路径短，先被洗脱。", "a": "对", "e": "小分子可进入珠内孔隙而路径延长、洗脱较慢；大分子被排阻在珠外，路径短、先被洗脱，因此蛋白质按分子量从大到小依次流出。", "kp": "ch04_s1_5"}, {"id": "ch04_judge_5", "modI": 1, "q": "亲和层析利用生物分子间强而特异的亲和力进行纯化，如His标签与Ni2+高亲和结合可一步纯化融合蛋白。", "a": "对", "e": "亲和层析将配体固定于基质，目标蛋白选择性结合，杂质被洗去后改变条件洗脱目标蛋白；His标签与Ni2+高亲和结合是典型亲和体系，选择性极高、步骤简便。", "kp": "ch04_s1_6"}, {"id": "ch04_judge_6", "modI": 2, "q": "Southern blotting以发明者Edwin Southern命名，用于检测RNA。", "a": "错", "e": "Southern blotting用于检测DNA；检测RNA的印迹杂交称为Northern blotting。", "kp": "ch04_s2_7"}, {"id": "ch04_judge_7", "modI": 2, "q": "FISH无需提取核酸，能在原位保留目标核酸的空间位置信息。", "a": "对", "e": "FISH用甲酰胺联合加热使固定细胞中双链DNA变性，加入标记探针杂交后荧光成像，无需提取核酸，特别适合DNA序列在染色体上的定位分析和染色质三维组织研究。", "kp": "ch04_s2_11"}, {"id": "ch04_judge_8", "modI": 3, "q": "PCR的退火温度通常约为95℃，延伸温度约为72℃。", "a": "错", "e": "PCR变性温度约95℃，退火温度约50-60℃，延伸温度约72℃。", "kp": "ch04_s3_1"}, {"id": "ch04_judge_9", "modI": 3, "q": "RT-PCR中Oligo(dT)引物识别mRNA的Poly(A)尾，适合常规mRNA分析，但不适用于无Poly(A)尾的RNA。", "a": "对", "e": "Oligo(dT)引物识别mRNA的Poly(A)尾，优先逆转录带Poly(A)的真核mRNA，适合常规mRNA分析，不适用于无Poly(A)尾的RNA；随机引物不依赖Poly(A)尾，适用范围更广。", "kp": "ch04_s3_7"}, {"id": "ch04_judge_10", "modI": 3, "q": "分子信标在游离状态下荧光基团与淬灭基团靠近，荧光被淬灭；与目标序列杂交后发夹结构打开，发出荧光信号。", "a": "对", "e": "分子信标是发夹型杂交探针，两端分别标记荧光基团和淬灭基团；游离时形成发夹结构使荧光淬灭，与目标序列特异性杂交后发夹打开、荧光基团与淬灭基团分离而发出荧光，具有高特异性，适合区分单核苷酸变异。", "kp": "ch04_s3_10"}], "fill": [{"id": "ch04_fill_1", "modI": 0, "q": "凝胶电泳中，DNA分子因磷酸骨架带________电荷，在电场中向________极迁移。", "a": "负,正", "kp": "ch04_s0_4"}, {"id": "ch04_fill_2", "modI": 0, "q": "超螺旋DNA结构最紧凑，在凝胶网络中迁移最________；开环或切口环状DNA较松散，迁移最________；线性DNA居中。", "a": "快,慢", "kp": "ch04_s0_3"}, {"id": "ch04_fill_3", "modI": 0, "q": "聚丙烯酰胺凝胶分辨率高，可分辨仅相差________个碱基对的DNA片段，但分离范围窄（约1至几百bp）。", "a": "一", "kp": "ch04_s0_8"}, {"id": "ch04_fill_4", "modI": 0, "q": "脉冲场凝胶电泳通过周期性改变________，使DNA分子在凝胶中不断调整取向，从而分离10kb至10Mb的大分子DNA。", "a": "电场方向", "kp": "ch04_s0_10"}, {"id": "ch04_fill_5", "modI": 1, "q": "SDS-PAGE中，SDS使蛋白质变性并带上均匀________电荷，因此迁移率主要取决于________。", "a": "负,分子量", "kp": "ch04_s1_0"}, {"id": "ch04_fill_6", "modI": 1, "q": "凝胶过滤层析中，小分子可进入凝胶珠孔隙而路径延长、洗脱较________；大分子被排阻在珠外、先被洗脱，因此蛋白质按分子量从________到________依次流出。", "a": "慢,大,小", "kp": "ch04_s1_5"}, {"id": "ch04_fill_7", "modI": 2, "q": "Southern印迹流程中，碱性溶液处理使DNA变性为________链，再将单链DNA从凝胶转移到________膜上。", "a": "单,硝酸纤维", "kp": "ch04_s2_6"}, {"id": "ch04_fill_8", "modI": 3, "q": "PCR每个循环包括三个基本步骤：变性（约________℃）、退火（约50-60℃）、延伸（约________℃）。", "a": "95,72", "kp": "ch04_s3_2"}, {"id": "ch04_fill_9", "modI": 3, "q": "RT-PCR中，Oligo(dT)引物识别mRNA的________尾，优先逆转录带Poly(A)的真核mRNA；随机引物不依赖Poly(A)尾，适用于多种RNA及部分降解的RNA。", "a": "Poly(A)", "kp": "ch04_s3_7"}, {"id": "ch04_fill_10", "modI": 3, "q": "qPCR中，SYBR Green I荧光染料结合双链DNA________，属于非特异检测；TaqMan探针和分子信标属于扩增序列________检测。", "a": "小沟,专一", "kp": "ch04_s3_9"}], "short": [{"id": "ch04_short_1", "modI": 0, "q": "简述凝胶电泳分离DNA片段的基本原理，并说明琼脂糖与聚丙烯酰胺凝胶在分辨率和分离范围上的差异。", "a": "1. 原理：DNA因磷酸骨架带负电荷，在电场中向正极迁移；凝胶基质形成多孔网络，较长的分子更容易被网络捕获而移动较慢，较短的分子移动较快，从而实现按大小分离。2. 琼脂糖：分辨率较低，但分离范围宽，可分离几百bp至数十kb的DNA，适合常规DNA片段分析。3. 聚丙烯酰胺：分辨率高，可区分仅相差一个碱基的DNA片段，但分离范围窄（约1至几百bp），适合DNA测序、PCR产物精细分析和蛋白质电泳。4. 实验设计应根据目标片段大小和所需分辨率选择凝胶种类与浓度。", "kp": "ch04_s0_5"}, {"id": "ch04_short_2", "modI": 1, "q": "简述Western blotting的基本流程及其主要应用。", "a": "1. 基本流程：SDS-PAGE分离蛋白质→转膜（硝酸纤维素或PVDF膜）→封闭→一抗孵育→酶标二抗孵育→显色/发光检测。2. 原理：利用抗体特异性识别转移到膜上的目标蛋白，实现定性和半定量检测。3. 特点：灵敏度高、特异性强。4. 应用：蛋白质表达验证、翻译后修饰分析及疾病标志物检测，是分子生物学中不可或缺的蛋白质分析技术。", "kp": "ch04_s1_2"}, {"id": "ch04_short_3", "modI": 2, "q": "简述Southern印迹杂交的操作流程，并说明变性、转膜、封闭和杂交各步骤的作用。", "a": "1. 流程：琼脂糖凝胶电泳分离DNA片段→碱性溶液处理使DNA变性为单链→将单链DNA从凝胶转移到硝酸纤维膜上（毛细扩散或电场转移）→用非特异性DNA或蛋白质封闭→加入标记探针孵育杂交→放射自显影或磷光成像检测阳性条带。2. 变性：使双链DNA解为单链，便于探针互补配对。3. 转膜：将凝胶中分离的DNA固定到固相膜上，便于后续杂交检测。4. 封闭：减少探针非特异性结合，降低背景。5. 杂交：标记探针与目标序列互补配对，只有含目标序列的片段才产生信号，保证特异性。", "kp": "ch04_s2_6"}, {"id": "ch04_short_4", "modI": 3, "q": "简述RT-PCR的原理和基本步骤，并说明内参基因在半定量分析中的作用。", "a": "1. 原理：将RNA信息转化为DNA信息，以mRNA为模板在逆转录酶作用下合成cDNA，再以cDNA为模板进行PCR扩增，半定量检测基因mRNA表达水平。2. 步骤：提取组织或细胞总RNA→以Oligo(dT)、随机引物或基因特异性引物逆转录合成cDNA→以cDNA为模板PCR扩增→凝胶电泳检测。3. 内参基因作用：选择表达稳定的内参基因（如ACTIN、GAPDH、β-actin、18S rRNA）作为参照尺，校正样本间RNA上样量、逆转录效率等差异；若内参信号基本一致而目标基因条带明显增强，则说明目标基因转录本增加。4. 内参基因需根据实验条件验证其稳定性。", "kp": "ch04_s3_8"}, {"id": "ch04_short_5", "modI": 3, "q": "简述实时荧光定量PCR（qPCR）的原理及两类常用荧光标记方法。", "a": "1. 原理：在PCR反应体系中加入荧光基团，实时监测荧光信号累积，通过标准曲线对未知模板进行定量分析；利用指数增长期荧光信号与起始模板量的线性关系进行定量。2. 非特异检测：如SYBR Green I荧光染料，结合双链DNA小沟，只有结合双链DNA时才发出荧光。3. 扩增序列专一检测：如TaqMan探针和分子信标，探针与目标序列特异性杂交后产生荧光信号。4. 特点：高灵敏度、高特异性和宽动态范围，广泛应用于基因表达定量、病原体检测、SNP分析等领域。", "kp": "ch04_s3_9"}], "calc": [{"id": "ch04_calc_1", "modI": 0, "q": "论述凝胶电泳中DNA拓扑构象对迁移率的影响，并说明该原理在质粒质量分析中的应用。", "a": "1. 超螺旋DNA结构最紧凑，在凝胶网络中迁移最快。2. 开环或切口环状DNA较松散，迁移最慢。3. 线性DNA迁移速度居中。4. 因此电泳不仅可分离不同大小的DNA，还可用于检测质粒DNA的超螺旋程度和拓扑构象变化。5. 应用：质粒质量分析中，可通过电泳条带判断质粒是否以超螺旋形式存在、是否存在开环或线性化降解产物，是质粒质量分析的常用方法。", "steps": "要点：三种构象的紧凑程度→迁移速度差异→电泳可检测拓扑构象变化→质粒质量分析应用。", "kp": "ch04_s0_3"}, {"id": "ch04_calc_2", "modI": 0, "q": "论述脉冲场凝胶电泳（PFGE）为何能分离普通凝胶电泳无法分辨的大分子DNA，并举例说明其应用。", "a": "1. 普通凝胶电泳中，大于10kb的DNA分子迁移速度接近，难以分离。2. PFGE通过周期性改变电场方向，使DNA分子在凝胶中不断调整取向。3. 较小的分子转向快、迁移快；较大的分子转向困难、迁移慢，从而按分子量、形状和拓扑特性分离。4. PFGE可有效分离10kb至10Mb的大分子DNA。5. 应用举例：分离完整的细菌或真菌染色体；酵母染色体PFGE可见16条条带，代表0.2Mb至2.2Mb的染色体；用于微生物基因组分型、染色体数目与大小分析、核型分析、基因组大小估计和染色体多态性研究。", "steps": "要点：普通电泳对大分子DNA分辨率不足→PFGE交替改变电场方向使长链DNA反复重定向→小分子转向快迁移快、大分子转向慢迁移慢→可分离Mb级DNA→酵母染色体和微生物分型等应用。", "kp": "ch04_s0_10"}], "term": [{"id": "ch04_term_1", "modI": 0, "term": "Gel Electrophoresis", "def": "在电场作用下使DNA/RNA或蛋白质通过凝胶基质，按分子大小（并受电荷、形状、拓扑性质等影响）进行分离的技术；分离后需用荧光染料（如EB）染色显示；是核酸分析最基础、最常用的手段，可判断片段大小、数量及纯度。", "kp": "ch04_s0_6"}, {"id": "ch04_term_2", "modI": 0, "term": "Agarose Gel", "def": "由琼脂糖形成的较大孔径多孔网络，分辨率低于聚丙烯酰胺，但分离范围宽，可分离几百bp至数十kb的DNA；浓度越高孔径越小，适合较小片段；制备简便，是常规DNA电泳最常用的基质。", "kp": "ch04_s0_6"}, {"id": "ch04_term_3", "modI": 0, "term": "Polyacrylamide Gel", "def": "由丙烯酰胺与交联剂聚合形成孔径较小且可精确调控的三维网络；分辨率高，可分辨仅相差一个碱基对的DNA片段，但分离范围窄（约1至几百bp）；广泛用于DNA测序、PCR产物精细分析及蛋白质单向/双向电泳。", "kp": "ch04_s0_6"}, {"id": "ch04_term_4", "modI": 0, "term": "Pulsed-Field Gel Electrophoresis (PFGE)", "def": "通过周期性改变电场方向，使DNA分子在凝胶中不断调整取向：小分子转向快、迁移快，大分子转向困难、迁移慢，从而按分子量、形状和拓扑特性分离；可有效分离10kb至10Mb的大分子DNA，是基因组图谱和染色体分析的重要方法。", "kp": "ch04_s0_10"}, {"id": "ch04_term_5", "modI": 1, "term": "SDS-PAGE", "def": "十二烷基硫酸钠-聚丙烯酰胺凝胶电泳；SDS使蛋白质变性并带上均匀负电荷，因此迁移率主要取决于分子量；是蛋白质纯度分析、分子量测定及Western blotting前分离的基础技术。", "kp": "ch04_s1_0"}, {"id": "ch04_term_6", "modI": 1, "term": "Western Blotting", "def": "蛋白质印迹；利用抗体特异性识别电泳分离后转移到膜（硝酸纤维素或PVDF膜）上的目标蛋白，实现定性和半定量检测；流程包括SDS-PAGE分离、转膜、封闭、一抗孵育、酶标二抗孵育及显色/发光检测；灵敏度高、特异性强。", "kp": "ch04_s1_2"}, {"id": "ch04_term_7", "modI": 1, "term": "Ion Exchange Chromatography", "def": "根据物质所带电荷差异进行分离的层析方法；带正电的DEAE-Sephadex作为阴离子交换剂结合带负电蛋白质，磷酸纤维素作为阳离子交换剂结合带正电蛋白质；通过改变pH或盐浓度梯度洗脱，分辨率高、载量大，常用于蛋白质精细纯化。", "kp": "ch04_s1_2"}, {"id": "ch04_term_8", "modI": 1, "term": "Gel Filtration Chromatography", "def": "凝胶过滤层析（分子排阻层析）；依据分子大小分离物质，小分子可进入凝胶珠孔隙而路径延长、洗脱较慢，大分子被排阻在珠外、先被洗脱；蛋白质按分子量从大到小依次流出；条件温和，常用于脱盐、缓冲液交换及分子量估算。", "kp": "ch04_s1_2"}, {"id": "ch04_term_9", "modI": 1, "term": "Affinity Chromatography", "def": "利用生物分子间强而特异的亲和力进行纯化；将配体（抗体、酶底物类似物、镍离子等）固定于基质，目标蛋白选择性结合，杂质被洗去后改变条件洗脱目标蛋白；如His标签与Ni2+高亲和结合可一步纯化融合蛋白；选择性极高、步骤简便。", "kp": "ch04_s1_2"}, {"id": "ch04_term_10", "modI": 2, "term": "Southern Blot Hybridization", "def": "由Edwin Southern发明并以他命名的DNA印迹杂交技术；先电泳按大小分离DNA片段，再变性并转移到固相膜上，最后用标记探针杂交检测目标序列；把凝胶电泳的分辨能力与核酸杂交的特异性结合，用于基因组DNA、重组质粒和噬菌体DNA的特异性鉴定。", "kp": "ch04_s2_5"}, {"id": "ch04_term_11", "modI": 2, "term": "Northern Blotting", "def": "与Southern blotting类似但电泳分离对象为RNA的印迹杂交技术；转膜后与标记探针杂交检测特定RNA，条带强度反映该RNA的相对含量；用于RNA定性和定量分析、研究基因表达调控，是检测基因转录活性的经典方法。", "kp": "ch04_s2_10"}, {"id": "ch04_term_12", "modI": 2, "term": "Fluorescence in situ Hybridization (FISH)", "def": "荧光原位杂交；用甲酰胺联合加热使固定细胞中的双链DNA变性，加入标记DNA探针杂交，通过荧光成像直接观察探针在染色体上的位置；无需提取核酸，保留目标核酸的空间位置信息，适合DNA序列在染色体上的定位分析和染色质三维组织研究。", "kp": "ch04_s2_14"}], "preview": {"main": "本章系统介绍分子生物学三大类核心技术：以凝胶电泳和层析为代表的分离纯化技术、以Southern/Northern/FISH为代表的核酸杂交技术、以及以PCR及其衍生技术为代表的核酸扩增技术，并阐明各类技术的原理、操作要点与典型应用。", "questions": [{"q": "琼脂糖凝胶与聚丙烯酰胺凝胶在分辨率、分离范围和适用场景上有何本质区别？实验中应如何根据目标片段选择凝胶种类与浓度？", "a": "琼脂糖分辨率较低但分离范围宽（几百bp至数十kb），适合常规DNA片段分析；聚丙烯酰胺分辨率高，可区分相差1个碱基的片段，但分离范围窄（约1至几百bp），用于测序、精细分析及蛋白质电泳。选择时按目标片段大小和所需分辨率决定凝胶种类，并调整浓度：浓度越高孔径越小，适合小片段；浓度越低孔径越大，适合大片段。"}, {"q": "普通凝胶电泳为何难以分离大于10kb的DNA？脉冲场凝胶电泳通过什么机制克服这一限制？", "a": "普通凝胶电泳中大于10kb的DNA分子迁移速度接近，难以分辨。PFGE通过周期性改变电场方向，使DNA分子不断调整取向：小分子转向快、迁移快，大分子转向困难、迁移慢，从而按分子量、形状和拓扑特性分离，可分离10kb至10Mb的大分子DNA。"}, {"q": "Southern印迹、Northern印迹和FISH三类杂交技术在样品处理、检测对象和信息输出上有何异同？各自最适合回答什么生物学问题？", "a": "三者均基于互补配对特异识别：Southern检测DNA（电泳分离、变性转膜、探针杂交），用于基因组DNA、重组质粒和噬菌体DNA的特异性鉴定；Northern检测RNA（电泳对象为RNA），用于RNA定性定量和基因转录活性分析；FISH无需提取核酸，对固定细胞/染色体变性后原位杂交并荧光成像，保留空间位置信息，用于染色体定位和染色质三维组织研究。"}, {"q": "杂交探针的标记方式有哪几类？放射性标记与非放射性标记在灵敏度、安全性和检测方式上各有什么优缺点？", "a": "标记方式有三类：合成短DNA时直接加入荧光等标记；PCR等DNA合成过程中掺入标记核苷酸（链内标记）；在已制备DNA末端加标记。放射性标记（如³²P）灵敏度高，但具放射性风险，用X光胶片自显影检测；非放射性标记（地高辛、生物素、荧光）安全性好，分别用抗DIG抗体酶促显色/化学发光、streptavidin-HRP/AP、直接荧光观察检测，灵敏度与设备需求各异。"}, {"q": "PCR的三个温度循环步骤各自的作用是什么？为什么说指数增长期是实时荧光定量PCR定量的关键阶段？", "a": "变性（约95℃）使双链DNA氢键断裂解链为单链模板；退火（约50–60℃）使引物与模板互补序列特异性结合；延伸（约72℃）由热稳定DNA聚合酶从引物3'端沿模板合成互补链。指数增长期产物量与起始模板量呈线性关系，qPCR正是利用此阶段荧光信号与起始模板量的线性关系进行定量，故为定量关键阶段。"}, {"q": "RT-PCR中Oligo(dT)、随机引物和基因特异性引物各适用于什么情况？内参基因在相对定量中起什么作用？", "a": "Oligo(dT)识别mRNA的Poly(A)尾，适合常规真核mRNA分析，不适用于无Poly(A)尾的RNA；随机引物在RNA多位点启动逆转录，适用于多种RNA及部分降解RNA，但cDNA可能来自rRNA；基因特异性引物只逆转录目标RNA，目标性强但通量低。内参基因（如ACTIN、GAPDH）表达稳定，用于校正样本间上样量、逆转录效率等差异，是相对定量的参照尺。"}, {"q": "离子交换层析、凝胶过滤层析和亲和层析分别依据什么原理分离蛋白质？各自在蛋白质纯化流程中通常处于什么位置？", "a": "离子交换层析依据电荷差异分离，分辨率高、载量大，常用于粗提后的精细纯化；凝胶过滤层析依据分子大小（小分子进入凝胶珠孔隙而滞后，大分子先洗脱），条件温和，用于脱盐、缓冲液交换和分子量估算；亲和层析依据生物分子间特异亲和力（如His标签与Ni²⁺），选择性极高，常用于重组蛋白的一步纯化。"}]}, "appcards": [{"front": "比较琼脂糖凝胶与聚丙烯酰胺凝胶在分辨率、分离范围和适用场景上的差异，并说明实验中应如何选择。", "back": "琼脂糖：分辨率较低，分离范围宽（几百bp至数十kb），制备简便，适合常规DNA片段分析；聚丙烯酰胺：分辨率高，可分辨相差1个碱基的片段，但分离范围窄（约1至几百bp），适合DNA测序、PCR产物精细分析和蛋白质电泳。选择依据：目标片段大小和所需分辨率；大片段用琼脂糖，小片段高分辨用聚丙烯酰胺。", "points": "琼脂糖低分辨宽范围；聚丙烯酰胺高分辨窄范围；按片段大小和分辨率选择", "mod": 0, "modName": "模块一：方法总览与核酸凝胶电泳", "level": "掌握", "src": "生成"}, {"front": "为什么普通凝胶电泳难以有效分离大于10kb的DNA，而脉冲场凝胶电泳（PFGE）可以分离Mb级DNA？请说明其机制。", "back": "普通电泳中大于10kb的DNA分子迁移速度接近，难以按大小分辨。PFGE通过周期性改变电场方向，使DNA分子在凝胶中不断调整取向：较小分子转向快、迁移快；较大分子转向困难、迁移慢，从而按分子量、形状和拓扑特性分离，可有效分离10kb至10Mb的大分子DNA。", "points": "普通电泳大分子迁移速度接近；PFGE周期改变电场方向；小分子转向快迁移快、大分子转向慢迁移慢；实现Mb级分离", "mod": 0, "modName": "模块一：方法总览与核酸凝胶电泳", "level": "掌握", "src": "生成"}, {"front": "在凝胶电泳中，超螺旋DNA、开环/切口环状DNA和线性DNA的迁移顺序如何？这一现象有什么应用意义？", "back": "迁移顺序：超螺旋DNA最快，线性DNA居中，开环/切口环状DNA最慢。原因：超螺旋结构最紧凑，在凝胶网络中迁移最快；开环或切口环状较松散，迁移最慢。应用意义：电泳不仅可分离不同大小的DNA，还可检测质粒DNA的超螺旋程度和拓扑构象变化，是质粒质量分析的常用方法。", "points": "超螺旋最快、线性居中、开环最慢；结构紧凑程度决定迁移；用于质粒拓扑构象和超螺旋程度分析", "mod": 0, "modName": "模块一：方法总览与核酸凝胶电泳", "level": "掌握", "src": "生成"}, {"front": "RNA电泳前为什么常需要进行变性处理？请举例说明处理试剂及其作用，并说明不变性处理可能带来的问题。", "back": "单链RNA易形成复杂二级、三级结构，会影响电泳迁移率，使其迁移行为不完全取决于分子量。用乙二醛等试剂处理可使RNA高级结构解体，处理后迁移率约与分子量成正比。若不变性处理，RNA迁移行为受构象影响，难以准确判断RNA大小和完整性。", "points": "RNA易形成高级结构影响迁移；乙二醛等变性处理破坏高级结构；变性后迁移率与分子量成正比；便于准确判断大小和完整性", "mod": 0, "modName": "模块一：方法总览与核酸凝胶电泳", "level": "掌握", "src": "生成"}, {"front": "SDS-PAGE与非变性电泳在分离原理和适用场景上有何主要区别？请比较说明。", "back": "SDS-PAGE：SDS使蛋白质变性并带上均匀负电荷，迁移率主要取决于分子量，适合分子量测定和纯度分析；非变性电泳：保留天然构象与活性，迁移率受电荷、形状和大小共同影响，适合保留活性或研究天然构象。", "points": "SDS变性+均匀负电荷；SDS-PAGE按分子量分离；非变性保留构象与活性；非变性受电荷/形状/大小共同影响；适用场景区分", "mod": 1, "modName": "模块二：蛋白质电泳与层析", "level": "掌握", "src": "生成"}, {"front": "Western blotting为什么具有高灵敏度和高特异性？请从方法机制角度说明。", "back": "先经SDS-PAGE按分子量分离蛋白质，再转膜固定；封闭减少非特异结合；一抗特异性识别目标蛋白，酶标二抗放大信号；显色/发光检测提高灵敏度。因此可实现目标蛋白的定性和半定量检测。", "points": "SDS-PAGE分离；转膜；封闭；一抗特异识别；酶标二抗信号放大；显色/发光检测；定性/半定量", "mod": 1, "modName": "模块二：蛋白质电泳与层析", "level": "掌握", "src": "生成"}, {"front": "凝胶过滤层析中为什么大分子蛋白质先被洗脱、小分子后洗脱？这一特点有何应用意义？", "back": "层析柱中多孔凝胶珠排阻大分子，大分子不能进入孔隙，路径短，先洗脱；小分子可进入珠内孔隙，路径延长，洗脱慢。该法条件温和、不依赖电荷，常用于脱盐、缓冲液交换、分子量估算及多步纯化组合。", "points": "多孔凝胶珠；大分子被排阻；大分子路径短先洗脱；小分子进入孔隙路径长后洗脱；按分子大小分离；脱盐/缓冲液交换/分子量估算/组合纯化", "mod": 1, "modName": "模块二：蛋白质电泳与层析", "level": "掌握", "src": "生成"}, {"front": "请以真核生物RNA聚合酶多重形式为例，说明离子交换层析在蛋白质研究中的应用价值。", "back": "海胆胚胎材料经DEAE-Sephadex阴离子交换层析分离，蛋白质含量曲线与RNA聚合酶活性峰对应多个活性峰，对应RNA聚合酶I、II、III；植物还有IV、V。说明离子交换层析可分离功能相关但电荷性质不同的同工酶，为研究真核转录机制和酶多型性提供实验证据。", "points": "DEAE-Sephadex阴离子交换层析；海胆胚胎材料；多个RNA聚合酶活性峰；对应RNA聚合酶I/II/III；植物还有IV/V；分离电荷性质不同的同工酶；服务转录机制与酶多型性研究", "mod": 1, "modName": "模块二：蛋白质电泳与层析", "level": "掌握", "src": "生成"}, {"front": "某实验室要检测某基因在不同组织中的转录活性，应选择Southern还是Northern印迹？请说明理由并简述操作流程。", "back": "应选Northern印迹。理由：Northern印迹电泳分离对象为RNA，转膜后用标记探针杂交检测特定RNA，条带强度反映该RNA的相对含量，可直接反映基因转录活性；Southern检测的是DNA，不能反映转录水平。流程：收集不同组织样本→提取RNA→电泳分离→转膜→标记探针杂交→X光胶片/成像检测，观察条带大小与强度。", "points": "选Northern（1分）；理由：检测RNA、条带强度反映转录活性（2分）；流程含提取RNA、电泳、转膜、杂交、检测（2分）", "mod": 2, "modName": "模块三：分子杂交（探针·Southern/Northern·FISH）", "level": "掌握", "src": "生成"}, {"front": "为什么Southern印迹流程中必须先用碱性溶液使DNA变性，再进行转膜和杂交？请从杂交原理角度解释。", "back": "分子杂交的本质是两条互补单链核酸通过碱基互补配对形成双链，探针只能与单链目标序列配对。电泳后的DNA是双链，若不先变性为单链，探针无法与目标序列互补结合，就没有特异性信号。碱性处理使DNA解链为单链，转膜固定后才能与标记探针杂交，保证序列特异性识别和低背景。", "points": "杂交本质是互补单链配对（1分）；双链DNA不能与探针结合（1分）；碱性变性使DNA成单链（1分）；保证特异性识别与信号产生（1分）", "mod": 2, "modName": "模块三：分子杂交（探针·Southern/Northern·FISH）", "level": "掌握", "src": "生成"}, {"front": "DNA指纹技术为什么能用于法医学个体鉴别？请结合微卫星序列、HaeIII酶切和杂交检测说明其机制。", "back": "基因组中存在微卫星（minisatellite）重复序列，不同个体重复次数不同，形成长度多态；HaeIII只在微卫星序列两侧切割而不切内部，酶切后片段长度因个体而异；电泳分离、转膜后用含微卫星序列的放射性探针杂交，自显影得到个体特异的条带图谱。两个模式完全相同的个体几乎不存在，故可用于法医学鉴别和亲子鉴定。", "points": "微卫星重复次数个体差异（1分）；HaeIII切两侧不切内部（1分）；电泳转膜后微卫星探针杂交（1分）；条带图谱个体特异、可用于鉴别（1分）", "mod": 2, "modName": "模块三：分子杂交（探针·Southern/Northern·FISH）", "level": "掌握", "src": "生成"}, {"front": "FISH与Southern印迹在检测对象和空间信息保留上有何不同？请举例说明FISH的独特应用价值。", "back": "Southern印迹需提取DNA、电泳分离并转膜，检测的是片段大小和序列，丢失空间位置信息；FISH无需提取核酸，对固定细胞/染色体变性后直接杂交，荧光成像保留目标核酸在染色体或核内的空间位置。独特价值举例：DNA序列在染色体上的定位分析；染色体涂染显示间期核内各染色体“领地”，研究染色质三维组织与基因表达调控。", "points": "Southern需提取、电泳、转膜，无空间信息（1分）；FISH原位杂交、保留空间位置（1分）；举例：染色体定位/染色体涂染/染色质三维组织（2分）", "mod": 2, "modName": "模块三：分子杂交（探针·Southern/Northern·FISH）", "level": "掌握", "src": "生成"}, {"front": "在RT-PCR实验中，为什么必须设置内参基因？如果内参基因条带在样本间不一致，应如何解释和调整？", "back": "内参基因（如ACTIN、GAPDH）表达稳定，用作参照尺校正样本间RNA上样量、逆转录效率等差异。若内参条带不一致，说明上样量或逆转录效率存在差异，不能直接比较目标基因条带强弱；应重新定量RNA、调整上样量或重新逆转录，并验证内参在实验条件下的稳定性。", "points": "内参作用（校正上样量/逆转录效率差异）；内参不一致的处理（重新定量/调整/验证稳定性）；不能直接比较目标基因", "mod": 3, "modName": "模块四：PCR与衍生技术", "level": "掌握", "src": "生成"}, {"front": "qPCR中Ct值与起始模板量有何关系？请说明绝对定量和相对定量（2^-ΔΔCt法）如何利用这一关系。", "back": "Ct值是荧光信号达到阈值时的循环数，与起始模板量的对数呈线性关系：模板量越多，Ct越小；模板量越少，Ct越大。绝对定量：用已知浓度标准品制作标准曲线，由未知样本Ct推算起始拷贝数。相对定量：比较目标基因与内参基因的Ct，用2^-ΔΔCt法计算相对表达差异，前提是扩增效率一致。", "points": "Ct与起始模板量对数线性关系（模板多Ct小）；绝对定量用标准曲线；相对定量用2^-ΔΔCt；扩增效率一致性前提", "mod": 3, "modName": "模块四：PCR与衍生技术", "level": "掌握", "src": "生成"}, {"front": "SYBR Green I法与TaqMan探针法在qPCR中有何区别？为什么SYBR Green I法必须做溶解曲线分析？", "back": "SYBR Green I是非特异双链DNA染料，成本低但可能结合非特异性产物和引物二聚体；TaqMan是水解型杂交探针，序列专一、特异性高但设计成本高。SYBR Green I法必须做溶解曲线分析：单一峰表明产物特异，多峰提示非特异性扩增或引物二聚体，用于排除假阳性信号。", "points": "SYBR非特异/成本低；TaqMan探针特异/成本高；溶解曲线单一峰判特异、多峰判非特异；SYBR法必要质控", "mod": 3, "modName": "模块四：PCR与衍生技术", "level": "掌握", "src": "生成"}, {"front": "反向PCR和锚定PCR都用于扩增已知序列一侧或两侧的未知序列，请比较二者原理及局限性，并各举一应用场景。", "back": "反向PCR：限制酶消化目标DNA后自身环化，用与已知序列两端反向互补的引物扩增两侧未知序列；局限是需合适酶切位点、环化效率低。锚定PCR：cDNA 3'端加poly(dG)尾，用poly(dC)锚定引物加已知序列特异性引物扩增一侧未知序列；不依赖酶切位点。应用：反向PCR用于转座子/病毒插入位点侧翼序列分析；锚定PCR用于已知一端序列的cDNA全长克隆。", "points": "反向PCR原理（酶切+环化+反向引物）；反向PCR局限（酶切位点/环化效率）；锚定PCR原理（加尾+锚定引物）；锚定PCR优势（不依赖酶切位点）；各举应用", "mod": 3, "modName": "模块四：PCR与衍生技术", "level": "掌握", "src": "生成"}, {"front": "为什么说cDNA文库与基因组文库在用途上互补？请从内容差异和适用场景两方面比较说明。", "back": "基因组文库由总基因组DNA切割克隆而成，尽可能保存全部基因组信息，但克隆片段不一定含完整基因，含内含子和调控序列；cDNA文库以mRNA逆转录合成cDNA后构建，只含表达基因序列，不含内含子和调控序列。因此克隆编码特定蛋白的基因时优先用cDNA文库；研究基因组全貌、测序或调控序列时用基因组文库，两者互补。", "points": "基因组文库含全部基因组信息、含内含子/调控序列；cDNA文库只含表达基因、不含内含子；cDNA适合克隆编码蛋白基因；基因组文库适合基因组测序/全貌研究；互补关系", "mod": 4, "modName": "模块五：基因克隆（酶·载体·文库·筛选）", "level": "掌握", "src": "生成"}, {"front": "蓝白斑筛选为什么能区分重组克隆与非重组克隆？请说明其分子机制及IPTG、X-gal各自的作用。", "back": "pUC载体MCS位于lacZ'基因内部。外源DNA插入MCS会破坏lacZ'阅读框，使β-半乳糖苷酶失活，不能水解X-gal，故重组克隆为白色菌落；未插入外源DNA的载体lacZ'完整，水解X-gal产生蓝色化合物，形成蓝色菌落。IPTG是乳糖类似物、强诱导剂，不被细菌代谢且稳定，诱导lac启动子表达lacZ'；X-gal是人工合成半乳糖苷，被β-半乳糖苷酶水解后产生蓝色化合物，作为显色底物。", "points": "MCS位于lacZ'内；插入破坏阅读框使酶失活；X-gal被水解产蓝色；IPTG诱导lac启动子；重组为白斑、非重组为蓝斑", "mod": 4, "modName": "模块五：基因克隆（酶·载体·文库·筛选）", "level": "掌握", "src": "生成"}, {"front": "限制酶识别序列长度如何影响其在基因组中的切割频率？请举例说明这一规律在实验中的意义。", "back": "识别序列越长，在基因组中出现频率越低：4 bp约每256 bp一次，6 bp约每4096 bp一次，8 bp约每65 kb一次，14 bp理论频率约每2.68亿bp一次；宏核酸酶识别14–40 bp。例如人类基因组约3.1 Gb，EcoRI（6 bp）约每4 kb、NotI（8 bp）约每65 kb出现一次（理论估算）。实验中可据此选择酶：需高频切割获得小片段时选短识别序列酶，需低频切割获得大片段时选长识别序列酶。", "points": "识别序列越长切割频率越低；4/6/8 bp频率数值；EcoRI与NotI举例；按所需片段大小选择酶", "mod": 4, "modName": "模块五：基因克隆（酶·载体·文库·筛选）", "level": "掌握", "src": "生成"}, {"front": "在cDNA文库构建中，若cDNA内部含EcoRI位点，应采取什么保护策略？请说明原因和操作要点。", "back": "原因：cDNA内部存在EcoRI位点时，酶切连接会被切断，破坏cDNA完整性。策略：在EcoRI酶切之前，先用EcoRI甲基转移酶对cDNA内部的EcoRI位点进行甲基化保护，使其不被EcoRI切割；而接头上的EcoRI位点未被甲基化，仍可被切割用于连接载体。意义：保证cDNA片段完整，提高文库构建效率。", "points": "内部EcoRI位点会被切断；先用EcoRI甲基转移酶甲基化保护；接头EcoRI位点仍可切割用于连接；保证cDNA完整性、提高建库效率", "mod": 4, "modName": "模块五：基因克隆（酶·载体·文库·筛选）", "level": "掌握", "src": "生成"}, {"front": "比较原核表达系统与真核表达系统在表达外源基因时的主要差异，并说明各自适用场景。", "back": "原核系统（如大肠杆菌）：操作简便、周期短、产量高、成本低；但缺乏翻译后修饰，蛋白易形成包涵体，需复性。真核系统（酵母、昆虫、哺乳动物细胞）：可正确折叠并进行糖基化、磷酸化等翻译后修饰，产物更接近天然蛋白；但操作复杂、周期长、成本高。适用：原核适合无需修饰的简单蛋白大量制备；真核适合需翻译后修饰的复杂真核蛋白（功能研究、药物生产）。", "points": "原核优缺点（产量高/无修饰/包涵体）；真核优缺点（正确折叠/翻译后修饰/成本高）；适用场景对应", "mod": 5, "modName": "模块六：克隆基因的表达", "level": "掌握", "src": "生成"}, {"front": "为什么在大肠杆菌中高水平表达外源基因时常形成包涵体？如何获得有活性的蛋白？", "back": "原因：外源蛋白合成过快、浓度过高，缺乏正确折叠所需条件（如分子伴侣、二硫键形成环境），导致不溶、无活性的蛋白聚集体。对策：调整诱导强度和条件（降低温度、减少诱导剂浓度）改善可溶性与折叠；若已形成包涵体，则分离包涵体、变性溶解后经复性重折叠获得有生物活性的蛋白。", "points": "包涵体形成原因（合成过快/折叠条件不足）；调整诱导条件；变性溶解+复性重折叠", "mod": 5, "modName": "模块六：克隆基因的表达", "level": "掌握", "src": "生成"}, {"front": "举例说明融合标签在克隆基因表达中的作用及原理。", "back": "His-tag：N端融合六个组氨酸，与镍离子高亲和结合，用镍亲和层析纯化，咪唑或低pH竞争洗脱；标签小、免疫原性低，一般不影响蛋白结构功能，必要时用肠激酶（识别DDDDK，K后切割）切除。LacZ融合：与LacZ编码序列融合，X-gal显色检测。GFP融合：插入GFP N端或C端，发绿色荧光便于示踪。作用：便于检测、纯化或提高溶解度。", "points": "His-tag纯化原理（镍亲和/咪唑洗脱/肠激酶切除）；LacZ显色检测；GFP荧光示踪；融合标签总体作用", "mod": 5, "modName": "模块六：克隆基因的表达", "level": "掌握", "src": "生成"}, {"front": "为什么表达载体常采用诱导型启动子？请列举常用诱导型启动子及其诱导方式。", "back": "原因：未诱导时关闭基因表达，避免过早表达影响细菌生长（尤其外源蛋白有毒性时）；诱导后开启，并通过调整诱导强度和条件改善蛋白可溶性与正确折叠。常用：lac启动子（IPTG诱导）；trc启动子（trp与lac杂合，IPTG诱导）；PBAD启动子（阿拉伯糖诱导）；PL启动子（温度诱导，42℃）。", "points": "诱导型启动子意义（避免过早表达/毒性/可调条件）；lac-IPTG；trc-IPTG；PBAD-阿拉伯糖；PL-温度", "mod": 5, "modName": "模块六：克隆基因的表达", "level": "掌握", "src": "生成"}, {"front": "比较过表达（gain of function）与RNAi/基因敲除（loss of function）两种策略在确定基因功能中的逻辑差异，并说明为何二者常需相互印证。", "back": "①过表达：将目标基因克隆到强启动子/表达载体，转染后蛋白水平显著升高，观察表型增强、增殖/凋亡/信号通路变化，提示该基因起促进或调控作用；②RNAi/敲除：用siRNA/shRNA降低表达或敲除基因，观察表型减弱或消失，提示该基因必要；③二者为互补路径：功能获得看“升高后是否增强”，功能缺失看“降低后是否减弱/消失”；④单一方向结果可能有假象（如过表达超生理水平），双向结果一致时功能推断更可靠。", "points": "过表达=功能获得、升高表达看表型增强；RNAi/敲除=功能缺失、降低表达看表型减弱；两条互补路径；相互印证提高可靠性", "mod": 6, "modName": "模块七：基因操作（过表达·RNAi·CRISPR）", "level": "掌握", "src": "生成"}, {"front": "简述RNAi降低靶基因表达的原理，并说明RNAi实验流程中为何要用qPCR检测敲低效率、设阴性对照和管家基因内参。", "back": "①原理：dsRNA被Dicer切割成siRNA→siRNA组装进RISC→以碱基配对识别靶mRNA→导致mRNA降解或翻译受抑，特异性降低表达；②流程：siRNA/shRNA转染细胞→培养→提取总RNA→反转录cDNA→Realtime PCR检测靶基因mRNA水平；③qPCR检测敲低效率：确认靶基因确实被降低，避免表型误判；④阴性对照siRNA：排除转染/非特异效应；⑤管家基因内参：归一化上样量差异，保证定量可靠；⑥效率确认后再观察表型推断功能。", "points": "dsRNA→Dicer→siRNA→RISC→靶mRNA降解/翻译受抑；qPCR确认敲低效率；阴性对照排除非特异；管家基因归一化；效率确认后看表型", "mod": 6, "modName": "模块七：基因操作（过表达·RNAi·CRISPR）", "level": "掌握", "src": "生成"}, {"front": "CRISPR/Cas9切割基因组DNA后，NHEJ与HDR两种修复途径的结果和用途有何不同？请比较并各举一应用。", "back": "①NHEJ：无修复模板，断裂处随机插入/缺失（indel），可造成移码或功能丧失→用于获得功能性敲除细胞系；②HDR：提供修复模板，在特定位点精确引入用户定义序列→用于过表达新基因、建立疾病相关细胞模型、用报告基因标记内源基因；③区别：NHEJ易错、非精确、无需模板；HDR精确、需模板、效率相对低；④应用举例：NHEJ构建基因敲除细胞；HDR敲入报告基因或突变序列。", "points": "NHEJ无模板→indel→移码/功能丧失→敲除细胞系；HDR有模板→精确引入序列→敲入/疾病模型/报告基因；NHEJ易错非精确、HDR精确需模板；各举一例", "mod": 6, "modName": "模块七：基因操作（过表达·RNAi·CRISPR）", "level": "掌握", "src": "生成"}, {"front": "CRISPR/Cas9为何被称为可编程基因编辑工具？不同Cas蛋白与PAM序列的选择对实验设计有何意义？请举例说明。", "back": "①可编程性：gRNA与Cas9形成复合物，gRNA碱基互补靶向特定位点，Cas9识别PAM后切割产生双链断裂；只需设计不同gRNA即可靶向几乎任何DNA序列，实现敲除、敲入或修饰；②PAM意义：不同Cas识别不同PAM，决定可靶向范围和工具选择；③举例：SpCas9识别NGG、最常用、分布广；SaCas9蛋白小、适合病毒载体递送；Cas12a识别TTTV、产生黏性末端、有时用于多基因编辑；xCas9等放宽PAM（NG、GAA）扩大靶向范围；④选择需兼顾PAM可用性、载体容量与编辑目的（延伸建议）。", "points": "gRNA可编程靶向+Cas9识别PAM切割；换gRNA即可靶向任意序列；PAM决定靶向范围；SpCas9=NGG常用、SaCas9小适合递送、Cas12a=TTTV黏性末端多基因、xCas9放宽PAM；兼顾PAM/载体/目的", "mod": 6, "modName": "模块七：基因操作（过表达·RNAi·CRISPR）", "level": "掌握", "src": "生成"}, {"front": "比较Illumina测序与Nanopore测序的原理和特点，并说明二者在基因组组装中如何互补。", "back": "Illumina采用边合成边测序：DNA片段固定于流动池桥式扩增成簇，每轮加入带荧光标记的可逆终止核苷酸，拍照读取荧光信号后切除标记进入下一轮，逐轮读取碱基。特点：通量高、准确度高、读长较短。Nanopore属于三代测序：单链DNA穿过纳米孔，不同碱基通过时引起特征性电流变化，据此直接读取序列。特点：读长长。互补：二代短读长高通量保证准确度和深度，三代长读长可跨越重复序列、帮助组装scaffold和解决复杂区域，二者结合可提高基因组组装完整性与准确性。", "points": "Illumina边合成边测序+可逆终止荧光核苷酸；高通量高准确短读长；Nanopore纳米孔电流特征读碱基；长读长；二者互补用于组装（短读长准确深度+长读长跨重复/搭scaffold）", "mod": 7, "modName": "模块八：组学技术与基因组学", "level": "掌握", "src": "生成"}, {"front": "组学研究的一般技术路线包括哪四步？为什么说生物信息学分析是核心步骤、下游验证不可省略？请举例说明。", "back": "四步：①样本制备与数据采集（高通量技术大规模获取数据）；②数据处理与生物信息学分析（序列比对/组装、定量与比较如疾病vs健康、功能富集分析找出差异分子显著集中的通路）；③整合分析（多组学联合如转录组+蛋白质组，构建调控网络）；④验证与机制研究。生物信息学分析是核心，因为海量原始数据必须经过比对、定量、差异分析和功能富集才能转化为可解释的生物学信息。下游验证不可省略，因为组学通常产生海量相关性假设，需靶向实验验证并探索机制。举例：转录组测序发现某通路基因在疾病组显著富集，需qPCR/Western blot或功能实验验证关键基因表达与因果作用。", "points": "四步：样本制备与数据采集、生物信息学分析、整合分析、验证与机制研究；生信核心原因（海量数据→比对定量差异富集）；组学多为相关性假设需靶向验证；举例（转录组差异基因需qPCR/WB/功能验证）", "mod": 7, "modName": "模块八：组学技术与基因组学", "level": "掌握", "src": "生成"}, {"front": "转录组有哪些主要特点？空间转录组学和单细胞转录组学分别解决了什么问题？各举一例应用。", "back": "转录组特点：①动态性——不同组织、发育阶段和环境条件下转录组变化；②多样性——一个基因可通过可变剪接产生多种RNA转录本；③组成广泛——包括mRNA和多种非编码RNA；是连接基因组与蛋白质组的桥梁，反映基因表达状态。空间转录组学在保留组织空间位置信息前提下测定基因表达谱，解决“基因在哪里表达”，如10x Visium、Stereo-seq用于绘制组织发育和肿瘤微环境图谱。单细胞转录组学在单细胞分辨率研究基因表达，揭示细胞异质性、鉴定稀有细胞类型、描绘分化轨迹，如10x Genomics、Smart-seq2。", "points": "转录组三特点：动态性、多样性（可变剪接）、组成广泛（mRNA+ncRNA）；桥梁作用；空间转录组解决空间位置表达（Visium/Stereo-seq，肿瘤微环境/发育图谱）；单细胞解决细胞异质性/稀有细胞/分化轨迹（10x Genomics/Smart-seq2）", "mod": 7, "modName": "模块八：组学技术与基因组学", "level": "掌握", "src": "生成"}, {"front": "南美肺鱼基因组约91 Gb、约为人类30倍且约90%为重复序列，这一案例说明了什么？对理解基因组大小与生物复杂性关系有何意义？", "back": "该案例说明：基因组大小与生物复杂性并不成正比；巨大基因组主要源于转座元件的大量扩增和重复序列的积累；重复序列在基因组演化中具有重要作用。意义：不能以基因组大小推断生物复杂程度；重复序列/转座元件是基因组演化的重要驱动力；也提示基因组测序与组装中重复序列带来的挑战，以及比较基因组学在理解脊椎动物水生向陆生演化中的价值。", "points": "基因组大小与复杂性不成正比；巨大基因组源于转座元件扩增/重复序列积累；重复序列在演化中重要作用；不能以大小推断复杂性；对比较基因组学与演化研究的意义", "mod": 7, "modName": "模块八：组学技术与基因组学", "level": "掌握", "src": "生成"}]};